import type { QuizQuestion } from '../../types/quiz';

const questions: QuizQuestion[] = [
  { q: '"Mona Lisa" tablosunu kim yaptı?', a: ['Michelangelo', 'Raphael', 'Leonardo da Vinci', 'Botticelli'], c: 2, e: 'Mona Lisa, 16. yüzyılda Leonardo da Vinci tarafından yapıldı. Louvre Müzesi\'nde sergilenen tablo, dünyanın en çok ziyaret edilen eseridir.' },
  { q: 'Sistine Şapeli tavanını kim boyamıştır?', a: ['Leonardo da Vinci', 'Michelangelo', 'Raphael', 'Titian'], c: 1, e: 'Michelangelo, 1508-1512 yılları arasında sırtüstü yatarak Sistine Şapeli tavanını boyadı. "Adem\'in Yaratılışı" bu eserin en ünlü sahnesidir.' },
  { q: '"Yıldızlı Gece" tablosunu kim yaptı?', a: ['Claude Monet', 'Paul Gauguin', 'Vincent van Gogh', 'Paul Cézanne'], c: 2, e: 'Van Gogh, 1889\'da bir akıl hastanesinde tedavi görürken "Yıldızlı Gece"yi yazdı. New York MoMA\'da sergilenmektedir.' },
  { q: '"Çığlık" tablosunu kim yaptı?', a: ['Gustav Klimt', 'Edvard Munch', 'Egon Schiele', 'Paul Klee'], c: 1, e: 'Norveçli ressam Edvard Munch\'un 1893 tarihli eseri modern kaygı ve varoluş korkusunun simgesi haline gelmiştir.' },
  { q: '"Guernica" tablosunu kim yaptı?', a: ['Salvador Dali', 'Pablo Picasso', 'Joan Miró', 'Juan Gris'], c: 1, e: 'Picasso, 1937\'de İspanya İç Savaşı\'nda Guernica kasabasının bombalanmasını protesto etmek için bu tabloyu yarattı.' },
  { q: 'Van Gogh hangi ülkelidir?', a: ['Belçika', 'Fransa', 'Almanya', 'Hollanda'], c: 3, e: 'Vincent van Gogh (1853-1890) Hollandalıdır. Yaşarken sadece bir tablo satabilen Van Gogh, bugün tarihin en pahalı sanatçıları arasındadır.' },
  { q: 'Empresyonizm akımı hangi ülkede başladı?', a: ['İtalya', 'Almanya', 'Fransa', 'İngiltere'], c: 2, e: 'Empresyonizm 1860\'larda Fransa\'da Monet, Renoir ve Degas öncülüğünde başladı. "İzlenim" anlamındaki Fransızca "impression"dan adını alır.' },
  { q: 'Türk resim sanatının öncüsü sayılan ressam kimdir?', a: ['Osman Hamdi Bey', 'İbrahim Çallı', 'Halil Paşa', 'Şeker Ahmet Paşa'], c: 0, e: 'Osman Hamdi Bey (1842-1910) hem ressam hem müze kurucusudur. İstanbul Arkeoloji Müzesi\'ni kurmuş, Türk müzeciliğinin öncüsüdür.' },
  { q: '"Kaplumbağa Terbiyecisi" tablosunun ressamı kimdir?', a: ['İbrahim Çallı', 'Osman Hamdi Bey', 'Şeker Ahmet Paşa', 'Avni Lifij'], c: 1, e: 'Osman Hamdi Bey\'in 1906 tarihli bu eseri, Türk resminin en çok tanınan tablolarından biridir. Şu an Pera Müzesi\'ndedir.' },
  { q: 'Beethoven kaç numaralı senfonisini sağır olarak besteledi?', a: ['5. Senfoni', '7. Senfoni', '9. Senfoni', '6. Senfoni'], c: 2, e: 'Beethoven 9. Senfoni\'yi 1824\'te tamamen sağırken besteledi. Eserin prömiyerinde Beethoven müziği duymamış, seyircinin alkışladığını fark etmemiştir.' },
  { q: 'Mozart hangi yaşta hayatını kaybetti?', a: ['25', '30', '35', '40'], c: 2, e: 'Wolfgang Amadeus Mozart, 5 Aralık 1791\'de 35 yaşında hayatını kaybetti. 6 yaşından itibaren beste yapan Mozart, 600\'den fazla eser bıraktı.' },
  { q: '"Dört Mevsim" eserini kim besteledi?', a: ['Bach', 'Handel', 'Vivaldi', 'Haydn'], c: 2, e: 'Antonio Vivaldi\'nin 1723\'te bestelediği "Dört Mevsim", keman konçertolarından oluşan ve programlı müziğin erken örneklerinden biridir.' },
  { q: 'Shakespeare hangi ülkelidir?', a: ['Fransa', 'Almanya', 'İtalya', 'İngiltere'], c: 3, e: 'William Shakespeare (1564-1616), Stratford-upon-Avon\'da doğdu. 37 oyun ve 154 sonet yazan Shakespeare, İngiliz edebiyatının zirvesidir.' },
  { q: '"Don Kişot" romanını kim yazdı?', a: ['Shakespeare', 'Dante', 'Cervantes', 'Goethe'], c: 2, e: 'Miguel de Cervantes\'in 1605\'te yazdığı Don Kişot, modern romanın başlangıcı sayılır. "Dünyanın ilk romanı" olarak da anılır.' },
  { q: '"Suç ve Ceza" romanını kim yazdı?', a: ['Leo Tolstoy', 'Anton Chekhov', 'Ivan Turgenev', 'Fyodor Dostoyevski'], c: 3, e: 'Dostoyevski\'nin 1866\'da yazdığı "Suç ve Ceza", bir cinayetin psikolojik ağırlığını işler; psikolojik romanın şaheseri sayılır.' },
  { q: '"Savaş ve Barış" romanını kim yazdı?', a: ['Dostoyevski', 'Turgenev', 'Leo Tolstoy', 'Gorki'], c: 2, e: 'Tolstoy\'un 1869\'da tamamladığı bu devasa roman, Napolyon savaşları döneminde Rus aristokrasisini konu alır; edebiyatın zirvelerinden biridir.' },
  { q: 'Türk edebiyatının ilk romanı sayılan eser hangisidir?', a: ['İntibah', 'Araba Sevdası', 'Taaşşuk-ı Talat ve Fitnat', 'Zehra'], c: 2, e: '"Taaşşuk-ı Talat ve Fitnat" (1872), Şemseddin Sami tarafından yazılan Türk edebiyatının ilk romanı kabul edilir.' },
  { q: '"İnce Memed" romanının yazarı kimdir?', a: ['Ahmet Hamdi Tanpınar', 'Sabahattin Ali', 'Yaşar Kemal', 'Orhan Pamuk'], c: 2, e: 'Yaşar Kemal\'in 1955\'te yazdığı "İnce Memed", Çukurova\'da geçen ve ağa baskısına karşı mücadeleyi anlatan başyapıttır.' },
  { q: 'Türkiye\'den Nobel Edebiyat Ödülü alan tek isim kimdir?', a: ['Yaşar Kemal', 'Orhan Pamuk', 'Murathan Mungan', 'Zülfü Livaneli'], c: 1, e: 'Orhan Pamuk, 2006\'da Nobel Edebiyat Ödülü kazandı. "Kar", "Benim Adım Kırmızı" ve "İstanbul" en tanınan eserleri arasındadır.' },
  { q: '"1984" distopik romanını kim yazdı?', a: ['Aldous Huxley', 'George Orwell', 'Ray Bradbury', 'Franz Kafka'], c: 1, e: 'George Orwell\'ın 1949\'da yazdığı "1984", totaliter bir devleti anlatan distopik bir başyapıttır. "Büyük Birader" kavramı bu kitaptan gelir.' },
  { q: 'Pop Art akımının öncüsü sayılan sanatçı kimdir?', a: ['Jackson Pollock', 'Mark Rothko', 'Andy Warhol', 'Roy Lichtenstein'], c: 2, e: 'Andy Warhol, 1960\'larda Campbell\'s çorba kutularını ve Marilyn Monroe portresini sanata dönüştürerek Pop Art\'ı tanımladı.' },
  { q: '"Düşünür" heykelinin sanatçısı kimdir?', a: ['Michelangelo', 'Donatello', 'Auguste Rodin', 'Bernini'], c: 2, e: 'Fransız heykeltıraş Auguste Rodin\'in 1880\'de yaptığı "Düşünür" (Le Penseur), felsefî düşüncenin evrensel simgesi haline gelmiştir.' },
  { q: 'Divan edebiyatının en büyük şairi kabul edilen isim kimdir?', a: ['Baki', 'Fuzuli', 'Nedim', 'Şeyh Galip'], c: 1, e: 'Fuzuli (1494-1556), hem Türkçe hem Arapça hem de Farsça yazan evrensel bir şairdir. "Leyla ve Mecnun" mesnevisi en ünlü eseridir.' },
  { q: 'Louvre Müzesi hangi şehirdedir?', a: ['Londra', 'Berlin', 'Paris', 'Amsterdam'], c: 2, e: 'Louvre, Paris\'te bulunan dünyanın en büyük ve en çok ziyaret edilen sanat müzesidir. Yaklaşık 35.000 eser barındırır.' },
  { q: '"Ay Işığı Sonatı" kimin eseridir?', a: ['Mozart', 'Chopin', 'Beethoven', 'Bach'], c: 2, e: 'Beethoven\'ın 1801\'de bestelediği bu piyano sonatı, "Ay Işığı" adını bestecinin ölümünden sonra aldı.' },
  // ── Ek Sanat & Edebiyat Soruları ─────────────────────────────────
  { q: '"Hamlet" kimin eseridir?', a: ['Marlowe', 'Molière', 'Shakespeare', 'Goethe'], c: 2, e: '"Hamlet" Shakespeare\'in en ünlü trajedisidir. "Olmak ya da olmamak, işte bütün mesele!" repliği buradan gelir.' },
  { q: 'Türk tiyatrosunun kurucusu sayılan isim kimdir?', a: ['Muhsin Ertuğrul', 'Haldun Taner', 'Aziz Nesin', 'Reşit Galip'], c: 0, e: 'Muhsin Ertuğrul, modern Türk tiyatrosunu kurdu ve yönetmenliğini yaptı; Türk sinemasının da öncüsüdür.' },
  { q: '"Faust" adlı eserin yazarı kimdir?', a: ['Schiller', 'Kafka', 'Goethe', 'Nietzsche'], c: 2, e: 'Goethe\'nin "Faust" eseri şeytanla anlaşan bir bilgini anlatır; Alman edebiyatının zirvesi kabul edilir.' },
  { q: 'Kübizm akımını kim kurdu?', a: ['Dali', 'Picasso ve Braque', 'Matisse', 'Léger'], c: 1, e: 'Pablo Picasso ve Georges Braque, 1908\'de Kübizmi geliştirdi; nesneler birden fazla bakış açısından aynı anda gösterilir.' },
  { q: 'Sürrealizm akımının öncüsü kimdir?', a: ['Salvador Dali', 'André Breton', 'Max Ernst', 'René Magritte'], c: 1, e: 'André Breton, 1924\'te "Sürrealizm Manifestosu"nu yazdı. Salvador Dali ise en tanınan sürrealist ressam oldu.' },
  { q: '"Eriyen Saatler" tablosunu kim yaptı?', a: ['Picasso', 'Magritte', 'Salvador Dali', 'Munch'], c: 2, e: 'Salvador Dali\'nin 1931 tarihli "Belleğin Azmi" (Eriyen Saatler) tablosu, zamanın göreceliliğini simgeleyen sürrealist başyapıttır.' },
  { q: '"Karamazov Kardeşler" romanının yazarı kimdir?', a: ['Tolstoy', 'Dostoyevski', 'Turgenev', 'Gogol'], c: 1, e: 'Dostoyevski\'nin 1880\'de tamamladığı son romanı; inanç, ahlak ve özgür irade temalarını işler.' },
  { q: '"Yabancı" (L\'Étranger) romanının yazarı kimdir?', a: ['Sartre', 'Camus', 'Beauvoir', 'Flaubert'], c: 1, e: 'Albert Camus\'nun 1942\'deki eseri absürdizmin simgesidir; başkahramanın annesinin ölümüne kayıtsız kalmasıyla başlar.' },
  { q: 'Türk edebiyatında Tanzimat dönemi hangi yılda başladı?', a: ['1839', '1856', '1876', '1908'], c: 0, e: 'Tanzimat Fermanı 1839\'da ilan edildi; bu dönemde Batılı edebi türler Türk edebiyatına girdi.' },
  { q: '"Servet-i Fünun" edebiyat akımının öncüsü kimdir?', a: ['Namık Kemal', 'Tevfik Fikret', 'Ziya Gökalp', 'Ahmet Haşim'], c: 1, e: 'Tevfik Fikret, Servet-i Fünun dergisini yöneterek bu akımın öncüsü oldu (1896-1901).' },
  { q: 'Türk resim tarihinde "1914 Kuşağı" neyi ifade eder?', a: ['Savaş ressamları', 'Avrupa\'da eğitim gören Türk ressamlar', 'Empresyonist grup', 'Kübist Türk sanatçılar'], c: 1, e: '1914 Kuşağı; Paris\'te eğitim alarak Türk resmini modernize eden İbrahim Çallı, Halil Paşa gibi ressamlardır.' },
  { q: '"Anna Karenina" romanının yazarı kimdir?', a: ['Dostoyevski', 'Çehov', 'Tolstoy', 'Turgenev'], c: 2, e: 'Tolstoy\'un 1877\'de tamamladığı roman; evlilik dışı aşkın trajedisini anlatır.' },
  { q: 'Türkiye\'nin en köklü tiyatrosu hangisidir?', a: ['İstanbul Şehir Tiyatroları', 'Devlet Tiyatroları', 'Ankara Sanat Tiyatrosu', 'Kenter Tiyatrosu'], c: 1, e: 'Devlet Tiyatroları, 1949\'da kuruldu; Ankara merkezli Türkiye\'nin en köklü ve yaygın tiyatro kurumudur.' },
  { q: '"Picasso\'nun Gernika\'sı" hangi tarihsel olayı anlatır?', a: ['I. Dünya Savaşı', 'İspanya İç Savaşı\'nda Guernica kasabasının bombalanması', 'II. Dünya Savaşı', 'Fransız Devrimi'], c: 1, e: '1937\'de Nazi Almanyası\'nın İspanya\'daki Guernica kasabasını bombalamasını protesto eden eserdir.' },
  { q: '"Hamlet"te ünlü monolog hangi soruyla başlar?', a: ['"Neden?"', '"Kim?"', '"Olmak ya da olmamak"', '"Nereye?"'], c: 2, e: '"To be, or not to be, that is the question" — varoluşu ve ölümü sorgulayan bu replik edebiyat tarihinin en ünlüsüdür.' },
  { q: 'Türk müziğinde "makam" nedir?', a: ['Bir enstrüman', 'Belirli ses aralıklarından oluşan dizilim ve kural sistemi', 'Bir ritim kalıbı', 'Şarkı sözü biçimi'], c: 1, e: 'Makam; melodinin hareket ettiği ses dizisini, başlangıç ve bitiş notalarını, seyre ilişkin kuralları belirler.' },
  { q: 'Aşık Veysel hangi sanatla uğraşmıştır?', a: ['Resim', 'Heykel', 'Halk şairliği (saz şairliği)', 'Tiyatro'], c: 2, e: 'Aşık Veysel Şatıroğlu, görme engelli Türk halk ozanıdır; "Uzun İnce Bir Yoldayım" onun en sevilen eseri.' },
  { q: 'Balıkesirli Türk ressam Atatürk portrelerini yapmasıyla tanınan kimdir?', a: ['İbrahim Çallı', 'Halil Paşa', 'Avni Lifij', 'Sabiha Bozcalı'], c: 3, e: 'Sabiha Bozcalı, Atatürk\'ün resmi portresini yapmış Türk kadın ressamıdır.' },
  { q: 'Türk sinemasında "Yeşilçam" adı nereden gelir?', a: ['Bir yapımcı adı', 'İstanbul\'da bir sokak adı', 'İlk stüdyonun adı', 'Film türü'], c: 1, e: 'Yeşilçam, İstanbul Beyoğlu\'ndaki Yeşilçam Sokağı\'ndan adını alır; yapım şirketleri burada yoğunlaşmıştı.' },
  { q: '"Halide Edip Adıvar"ın en ünlü romanı hangisidir?', a: ['Sinekli Bakkal', 'İnce Memed', 'Çalıkuşu', 'Vurun Kahpeye'], c: 0, e: '"Sinekli Bakkal" (1935), İstanbul\'un geleneksel mahalle yaşamını anlatan, ilk İngilizce çevirileri yapılan Türk romanlarından.' },
  { q: 'Reşat Nuri Güntekin\'in en ünlü eseri hangisidir?', a: ['İnce Memed', 'Çalıkuşu', 'Sinekli Bakkal', 'Yaprak Dökümü'], c: 1, e: '"Çalıkuşu" (1922), idealist öğretmen Feride\'nin Anadolu\'daki maceralarını anlatan klasik Türk romanıdır.' },
  { q: 'Orhan Kemal\'in eserlerinin konusu ağırlıklı olarak nedir?', a: ['Osmanlı tarihi', 'İşçi sınıfı ve yoksullar', 'Aşk hikayeleri', 'Felsefi düşünceler'], c: 1, e: 'Orhan Kemal, Adana pamuk tarlası işçilerini ve fabrika emekçilerini anlatan toplumcu gerçekçi bir yazardır.' },
  { q: '"Bir Gün Tek Başınasın" kimin şiirine aittir?', a: ['Nazım Hikmet', 'Orhan Veli', 'Cemal Süreya', 'Edip Cansever'], c: 1, e: 'Orhan Veli Kanık, geleneksel divan şiiri kalıplarını kırarak sade ve halk diline yakın şiirleriyle Türk şiirini dönüştürdü.' },
  { q: 'Aziz Nesin\'in eserlerinin temel özelliği nedir?', a: ['Romantik aşk', 'Toplumsal hiciv ve yergi', 'Tarihi anlatı', 'Felsefi monologlar'], c: 1, e: 'Aziz Nesin, bürokratik ve sosyal çarpıklıkları mizah ve hicivle eleştiren Türk edebiyatının en önemli yazarlarından.' },
  { q: '"Şiir nedir?" sorusuna "sözcüklerin müziği" diyen Fransız şair kimdir?', a: ['Rimbaud', 'Baudelaire', 'Verlaine', 'Mallarmé'], c: 2, e: 'Paul Verlaine "Şiir Sanatı"nda şiiri müzikle özdeşleştirdi; sembolizm akımının öncülerindendir.' },
  // ── Ek Sanat Soruları ─────────────────────────────────────────────
  { q: 'Türk heykel sanatının öncüsü sayılan sanatçı kimdir?', a: ['Zühtü Müridoğlu', 'Hüseyin Gezer', 'Ali Hadi Bara', 'Nusret Suman'], c: 2, e: 'Ali Hadi Bara (1906-1971), Türkiye\'nin ilk uluslararası tanınırlık kazanan heykeltraşıdır; figüratif heykelleriyle öne çıkmıştır.' },
  { q: '"Primitivizm" sanat akımı neyi simgeler?', a: ['Batı sanatını taklit etme', 'İlkel ve geleneksel kültürlerden ilham alma', 'Sanayileşmeyi kutlama', 'Soyut biçimleri reddeme'], c: 1, e: 'Primitivizm; Picasso ve Gauguin gibi Avrupalı sanatçıların Afrika, Okyanusya ve Asya sanatından ilham almasıyla ortaya çıktı.' },
  { q: 'Edebiyatta "akış of bilinç" (stream of consciousness) tekniğini en ünlü kullanan yazar kimdir?', a: ['Ernest Hemingway', 'James Joyce', 'F. Scott Fitzgerald', 'William Faulkner'], c: 1, e: 'James Joyce, "Ulysses" ve "Bir Genç Adamın Portresi"nde iç monolog ve bilinç akışı tekniğini zirveye taşıdı.' },
  { q: '"Mavi Dönem" hangi sanatçıyla özdeşleşmiştir?', a: ['Matisse', 'Monet', 'Picasso', 'Van Gogh'], c: 2, e: 'Picasso\'nun 1901-1904 yıllarını kapsayan Mavi Döneminde tablolara hâkim renk mavidir; yoksulluk ve hüznü yansıtır.' },
  { q: 'Türk mimarisinde "Sinan" lakabıyla anılan büyük mimar kimdir?', a: ['Davut Ağa', 'Mimar Kemalettin', 'Mimar Sinan', 'Hayreddin'], c: 2, e: 'Mimar Sinan (1490-1588), Süleymaniye ve Selimiye camilerini tasarlayan Osmanlı\'nın baş mimarıdır; 300\'den fazla eser bırakmıştır.' },
  { q: 'Selimiye Camii hangi şehirdedir?', a: ['İstanbul', 'Bursa', 'Edirne', 'Konya'], c: 2, e: 'Mimar Sinan\'ın en büyük eseri saydığı Selimiye Camii, Edirne\'de 1575\'te tamamlandı ve UNESCO listesindedir.' },
  { q: '"Empresyonizm" akımının ismi nereden gelir?', a: ['Bir sanatçının adından', 'Monet\'nin "İzlenim, Gün Doğumu" adlı tablosundan', 'Fransız bir dergiden', 'Bir sergi adından'], c: 1, e: '1874\'te eleştirmen Louis Leroy, Monet\'nin "Impression, Soleil Levant" tablosunu alay yollu "empresyonist" diye adlandırdı; isim kaldı.' },
  { q: 'Türkiye\'de "devlet sanatçısı" unvanı kime verilir?', a: ['Herkese', 'Sanat alanında üstün başarı gösteren kişilere devlet tarafından', 'Yabancı sanatçılara', 'Emekli sanatkarlara'], c: 1, e: 'Devlet Sanatçısı unvanı, Kültür Bakanlığı\'nın kararıyla sanat alanında olağanüstü katkı sağlayan kişilere verilir.' },
  { q: '"Gotik" mimari stili hangi öğelerle tanınır?', a: ['Düz çatılar ve simetri', 'Sivri kemerler, uçan payandalar ve yüksek kuleler', 'Sütunlar ve kubbeler', 'Tahta çerçeveler'], c: 1, e: 'Gotik mimari 12-16. yüzyıl Avrupa\'sında doğdu; ışığı içeri almak için büyük vitray pencereler ve sivri kemerler kullanıldı.' },
  { q: '"Barok" sanat döneminin temel özelliği nedir?', a: ['Sadelik ve minimalizm', 'Abartılı süsleme, dramatik ışık-gölge ve hareket duygusu', 'Geometrik soyutlama', 'Doğadan uzaklaşma'], c: 1, e: 'Barok sanat (17. yüzyıl); dramatik ışık kontrastı (chiaroscuro), dinamizm ve görkemli süslemeyle tanınır. Caravaggio ve Rubens öncülerindendir.' },
  { q: '"Kolaj" tekniği nedir?', a: ['Kağıt üzerine çizim', 'Farklı malzemelerin yapıştırılmasıyla oluşturulan sanat', 'Boyama tekniği', 'Heykel yöntemi'], c: 1, e: 'Kolaj; gazete kesiği, kumaş parçası gibi malzemelerin bir yüzeye yapıştırılmasıyla oluşturulan eserdir. Picasso ve Braque öncüdür.' },
  { q: '"Türk ebru sanatı" ne üzerine yapılır?', a: ['Kağıt', 'Su yüzeyine boyalar yayılarak kağıda aktarılır', 'Ahşap', 'Deri'], c: 1, e: 'Ebru; suyun yüzeyine damlanan boyaların çeşitli araçlarla şekillendirilip kağıda aktarılmasıyla oluşan geleneksel Türk sanatıdır.' },
  { q: 'Ahmet Hamdi Tanpınar hangi edebî akımla özdeşleşir?', a: ['Servet-i Fünun', 'Toplumcu Gerçekçilik', 'Modernizm ve psikolojik roman', 'Millî Edebiyat'], c: 2, e: 'Tanpınar, Doğu-Batı sentezi, zaman, bilinçaltı ve Türk kimliğini işleyen modernist bir yazardır; "Saatleri Ayarlama Enstitüsü" başyapıtıdır.' },
  { q: '"Sabahattin Ali" hangi nedenden dolayı önemlidir?', a: ['İlk Türk romancı', 'Toplumsal gerçekçi hikaye ve romanlarıyla', 'İlk kadın yazar', 'Divan şairi'], c: 1, e: 'Sabahattin Ali (1907-1948), Anadolu insanının hayatını anlatan toplumcu gerçekçi eserleriyle tanınır; "Kürk Mantolu Madonna" en ünlüsüdür.' },
  { q: '"Minyatür" sanatı Türk-İslam sanatında ne anlama gelir?', a: ['Küçük heykel', 'El yazması kitaplara yapılan renkli küçük boyutlu resimler', 'Taş oyma', 'Cam işlemesi'], c: 1, e: 'Minyatür; özellikle el yazması kitaplara yapılan ayrıntılı küçük boyutlu resimlerdir. Osmanlı minyatürü İslam sanatının zirvelerindendir.' },
  { q: 'Türkiye\'de "Galeri" ile "Müze" arasındaki fark nedir?', a: ['İkisi aynıdır', 'Galeride eserler satışa sunulur, müzede kalıcı sergi', 'Galeri devlet kurumu, müze özel', 'Müzede yalnızca antikalar bulunur'], c: 1, e: 'Galeri ticari amaçlı sanat eseri sergisi-satışı yapar; müze ise eserleri koruyup kalıcı olarak toplumla buluşturur.' },
  { q: '"Op Art" (Optik Sanat) nedir?', a: ['Fotoğrafik sanat', 'Göz yanılması yaratacak geometrik desenler kullanan sanat akımı', 'Doğa resimleri', 'Video sanatı'], c: 1, e: 'Op Art 1960\'larda ortaya çıktı; geometrik şekil ve renk zıtlıklarıyla optik yanılmalar yaratmayı amaçlar. Victor Vasarely öncüsüdür.' },

  // ── YENİ SORULAR ──────────────────────────────────────────────────
  { q: '"Rönesans" sanatının merkezi hangi şehirdir?', a: ['Roma', 'Paris', 'Floransa', 'Venedik'], c: 2, e: 'Floransa, 15. yüzyılda Medici ailesi\'nin himayesiyle Rönesans\'ın kalbi oldu; Da Vinci, Botticelli ve Michelangelo burada yetişti.', d: 1 },
  { q: 'Michelangelo\'nun Sistine Şapeli\'nin tavanına yaptığı eserin adı nedir?', a: ['Yaratılış', 'Son Yargı', 'Adem\'in Yaratılışı içeren Yaratılış freski', 'Meryem Ana'], c: 2, e: 'Sistine tavanının en ünlü bölümü "Adem\'in Yaratılışı"dır; 1508-1512 arasında boyanan bu dev freski, insanlık tarihinin ikonik sanat eserleri arasındadır.', d: 1 },
  { q: '"Mona Lisa" tablosunu kim yazmıştır?', a: ['Michelangelo', 'Raphael', 'Leonardo da Vinci', 'Titian'], c: 2, e: 'Mona Lisa, Leonardo da Vinci tarafından 1503-1519 yılları arasında yapıldı; şu an Paris Louvre Müzesi\'nde sergilenmektedir.', d: 1 },
  { q: '"Van Gogh"un "Yıldızlı Gece" tablosu nerede sergilenmektedir?', a: ['Louvre, Paris', 'MoMA, New York', 'Prado, Madrid', 'Tate Modern, Londra'], c: 1, e: 'Yıldızlı Gece (1889), New York\'taki Modern Sanat Müzesi\'nde (MoMA) sergilenmektedir.', d: 2 },
  { q: '"Empresyonizm" akımı hangi ülkede ortaya çıktı?', a: ['İtalya', 'İspanya', 'Fransa', 'Almanya'], c: 2, e: 'Empresyonizm, 19. yüzyılda Fransa\'da gelişti; Monet, Renoir ve Degas bu akımın öncü isimleridir.', d: 1 },
  { q: 'Pablo Picasso hangi sanat akımının kurucusudur?', a: ['Sürrealizm', 'Kübizm', 'Fütürizm', 'Dadaizm'], c: 1, e: 'Pablo Picasso ve Georges Braque, 1900\'lerin başında Kübizm\'i kurdu; nesneleri birden fazla açıdan aynı anda gösteren devrimci bir yaklaşımdır.', d: 1 },
  { q: '"Salvador Dali" hangi sanat akımıyla tanınır?', a: ['Kübizm', 'Realizm', 'Sürrealizm', 'Ekspresyonizm'], c: 2, e: 'Salvador Dali, bilinçaltı imgelerini rüya gibi sahnelerde işleyen Sürrealizm\'in en ünlü temsilcisidir; "Belleğin Azmi" eseri ikonikleşmiştir.', d: 1 },
  { q: '"Gotik mimari"nin en belirgin özelliği nedir?', a: ['Düz çatılar ve yuvarlak kemerler', 'Sivri kemerler, uçan payandalar ve büyük vitraylar', 'Sütun sıraları ve açık avlular', 'Piramit biçimli çatılar'], c: 1, e: 'Gotik mimari (12-15. yüzyıl); sivri kemer, uçan payanda ve büyük vitray pencerelerle tanınır. Notre-Dame Katedrali en iyi örneklerden biridir.', d: 2 },
  { q: '"Empresyonist" resimde en önemli unsur nedir?', a: ['Fotoğraf gerçekliği', 'Anlık ışık ve renk etkisini yakalamak', 'Mitolojik sahneler', 'Siyasi mesajlar'], c: 1, e: 'Empresyonistler akademik kurallara uymak yerine gün ışığının anlık etkisini, canlı fırça darbeleriyle tuvale aktarmayı amaçladı.', d: 2 },
  { q: 'Türk hat sanatının en önemli malzemesi nedir?', a: ['Tuval ve yağlı boya', 'Kamış kalem, mürekkep ve kağıt/deri', 'Mermer ve kalem', 'İplik ve iğne'], c: 1, e: 'Hat sanatında kamış kalem (divit), özel mürekkep (is ya da arap zamkı bazlı) ve pişirilmiş deri ya da kağıt kullanılır.', d: 2 },
  { q: '"Pitoresk" (Picturesque) kavramı sanatta ne anlama gelir?', a: ['Geometrik mükemmellik', 'Resme uygun doğal ya da kırsal güzellik', 'Modern kent yaşamı', 'Soyut renkler'], c: 1, e: 'Pitoresk, 18. yüzyılda İngiltere\'de gelişen; düzensiz, doğal ve kırsal manzaraların estetik değerini ön plana çıkaran bir güzellik anlayışıdır.', d: 3 },
  { q: '"Fresk" tekniği nedir?', a: ['Tuval üzerine yağlı boya', 'Islak sıva üzerine su bazlı boya', 'Tahta üzerine altın varak', 'Kağıt üzerine suluboya'], c: 1, e: 'Fresk, henüz ıslak olan duvar sıvasına su bazlı pigment uygulanarak yapılan duvar resmidir; boya sıvaya işler ve kalıcı olur.', d: 2 },
  { q: 'Türk İslam sanatında geometrik desenler neden kullanılır?', a: ['Pratik sebeplerle', 'İslam\'da canlı figür yasağına karşı alternatif estetik ifade', 'Ucuz malzeme olduğu için', 'Roma mimarisini taklit etmek için'], c: 1, e: 'İslam sanatında canlı figür tasvirine getirilen kısıtlamalar nedeniyle sanatçılar geometrik desenler, arabesk ve kaligrafide ustalık geliştirdi.', d: 2 },
  { q: '"Empresyonizm" adı nereden gelir?', a: ['Bir sanat gazetesinden', 'Monet\'nin "İzlenim: Gün Doğumu" tablosundan eleştirmenlerin türettiği alay yüklü ifadeden', 'Fransız Akademisi\'nden', 'Bir sergi adından'], c: 1, e: '1874\'te bir eleştirmen, Monet\'nin "Impression, Soleil Levant" tablosuna atfen bu akımı aşağılamak için "empresyonist" dedi; ad kaldı.', d: 3 },
  { q: '"Bauhaus" hangi alanda çığır açtı?', a: ['Yalnızca resimde', 'Tasarım, mimarlık ve zanaatı birleştiren modern eğitim anlayışında', 'Yalnızca heykelde', 'Fotoğrafçılıkta'], c: 1, e: 'Bauhaus (1919-1933, Almanya), sanat ve endüstriyel tasarımı birleştiren, işlevselliği esas alan devrimci bir okul ve akım oldu.', d: 3 },
  { q: '"Soyut Ekspresyonizm" hangi ülkede gelişti?', a: ['Fransa', 'İtalya', 'Almanya', 'ABD'], c: 3, e: 'Soyut Ekspresyonizm, II. Dünya Savaşı sonrası 1940-50\'lerde New York\'ta gelişti; Jackson Pollock ve Mark Rothko öncülerindendir.', d: 3 },
  { q: 'Wolfgang Amadeus Mozart hangi ülkede doğmuştur?', a: ['Almanya', 'Avusturya', 'İtalya', 'Çekya'], c: 1, e: 'Mozart (1756-1791), Salzburg\'da (o dönem Kutsal Roma İmparatorluğu\'na bağlı) doğdu; bugün Avusturya sınırlarında kalır.', d: 1 },
  { q: 'Beethoven\'ın 9. Senfonisi hangi özelliğiyle dikkat çeker?', a: ['Tamamen piyano için yazılması', 'Sır içermesi', 'Sağır olduğu dönemde besteleyen tek senfonisti', 'Yalnızca 10 dakika sürmesi'], c: 2, e: 'Beethoven, 9. Senfoniyi neredeyse tamamen işitmez durumdayken besteledi; "Neşeye Övgü" korosu içeren finaliyle tarihsel bir başyapıttır.', d: 2 },
  { q: '"Opera"nın doğduğu ülke hangisidir?', a: ['Almanya', 'Fransa', 'İtalya', 'Avusturya'], c: 2, e: 'Opera, 16. yüzyıl sonu – 17. yüzyıl başında Floransa\'da (İtalya) Camerata topluluğunun antik Yunan dramasını yeniden canlandırma çabasıyla doğdu.', d: 2 },
  { q: '"Divan edebiyatında "kaside" nedir?', a: ['Aşk şiiri', 'Padişah veya yüksek kişilere sunulan övgü şiiri', 'Ağıt', 'Halk türküsü'], c: 1, e: 'Kaside, Divan edebiyatında padişah, vezir gibi ileri gelenlere sunulan övgü şiiridir; en az 33, genellikle 99 beyitten oluşur.', d: 2 },
  { q: '"Sürrealizm"in öncüsü ve manifestosunu yazan kişi kimdir?', a: ['Salvador Dali', 'André Breton', 'Max Ernst', 'René Magritte'], c: 1, e: 'André Breton, 1924\'te Sürrealizm Manifestosu\'nu yayımlayarak bu akımı tanımladı; bilinçaltı imgeler ve rüya sahnelerine dayanan sanatı savundu.', d: 3 },
  { q: 'Türk çini sanatının merkezi olarak bilinen şehir hangisidir?', a: ['İstanbul', 'Bursa', 'İznik', 'Konya'], c: 2, e: 'İznik çini ve seramiği, Osmanlı\'nın 15-17. yüzyıllarında zirveye ulaştı; kobalt mavisi ve kırmızı tonlarıyla dünya çapında tanınır.', d: 2 },
  { q: '"Realizm" sanat akımının öncüsü olarak kabul edilen Fransız ressam kimdir?', a: ['Gustave Courbet', 'Eugène Delacroix', 'Jacques-Louis David', 'Jean-Auguste-Dominique Ingres'], c: 0, e: 'Gustave Courbet (1819-1877), idealize etmeden sıradan insanların yaşamını tuvale taşıyarak Realizm\'in öncüsü oldu.', d: 3 },
  { q: '"Kaligrafi" (Hat) hangi alfabelerde sanat olarak gelişmiştir?', a: ['Yalnızca Arap alfabesinde', 'Arap, Çin, Japon ve Latin alfabelerinde', 'Yalnızca Latin alfabesinde', 'Yalnızca Japonca\'da'], c: 1, e: 'Hat sanatı başta Arap, Farsça ve Osmanlıca olmak üzere Çin, Japon ve belirli ölçüde Latin alfabelerinde yüksek estetik değer kazanmıştır.', d: 2 },
  { q: '"Pop Art" akımının en ünlü temsilcisi kimdir?', a: ['Andy Warhol', 'Roy Lichtenstein', 'Jasper Johns', 'Robert Rauschenberg'], c: 0, e: 'Andy Warhol, Campbell\'s çorba kutusu ve Marilyn Monroe gibi popüler kültür imgelerini sanata taşıyarak Pop Art\'ın simgesi oldu.', d: 2 },
  { q: '"Rönesans"ın Türkçe anlamı nedir?', a: ['Aydınlanma', 'Yeniden Doğuş', 'Modernizm', 'İlerleme'], c: 1, e: 'Rönesans (Renaissance), Fransızca "yeniden doğuş" demektir; antik Yunan-Roma uygarlığının değerleri ve sanatının yeniden keşfedildiği dönemi anlatır.', d: 1 },
  { q: '"Çini" ile "seramik" arasındaki fark nedir?', a: ['İkisi aynıdır', 'Çini sırlı ve dekoratif kil levhalar; seramik daha genel bir kavram', 'Seramik renkli, çini tek renkli', 'Çini metal içerir'], c: 1, e: 'Seramik pişirilmiş kil ürünlerinin genel adıdır; çini ise sırlı ve genellikle geometrik-bitkisel motiflerle bezenmiş dekoratif seramik levhalardır.', d: 2 },
  { q: '"Sürrealiz"min öncüsü André Breton hangi alanda ün kazandı?', a: ['Ressam', 'Şair ve yazar; Sürrealizm manifestosunu kaleme aldı', 'Heykeltıraş', 'Mimar'], c: 1, e: 'André Breton, 1924\'te Sürrealizm manifestosunu yayımlayan Fransız şair ve yazardır; bilinçdışı yaratıcılığı ön plana çıkaran bu akımı teorize etmesiyle tanınır.', d: 2 },
  { q: '"Claude Monet" hangi sanat akımının temsilcisidir?', a: ['Kübizm', 'Empresyonizm', 'Sürrealizm', 'Realizm'], c: 1, e: 'Claude Monet, 1870\'lerden itibaren anlık ışığı ve rengi tuvale aktaran Empresyonizm\'in önde gelen temsilcisidir; Nilüfer serisi en ünlü yapıtları arasındadır.', d: 1 },
  { q: '"Vincent van Gogh"un "Yıldızlı Gece" tablosundaki girdap sarmallar neyi simgeler?', a: ['Fırtına', 'Hareketin ve enerji akışının görsel ifadesi', 'Yıldızlar', 'Dramatik efekt'], c: 1, e: 'Van Gogh\'un sarmal fırça darbeleri; gökyüzündeki enerji ve hareket hissini görsel olarak aktarır. Bu tablo 1889\'da Saint-Paul-de-Mausole akıl hastanesinde yatarken yapıldı.', d: 2 },
  { q: '"Rembrandt" hangi teknikle öne çıkmıştır?', a: ['Nokta baskı', 'Işık-gölge (chiaroscuro) ustası; bakır baskı ve yağlı boyada dramatik ışık oyunları', 'Fresk', 'Mozaik'], c: 1, e: 'Rembrandt van Rijn, 17. yüzyıl Hollanda\'sının en büyük ustasıdır; özellikle karanlık arka plandan parlayan dramatik ışık kullanımıyla tanınır.', d: 2 },
  { q: '"Mona Lisa"nın "gizemli gülümsemesi" neden tartışmalıdır?', a: ['Yalnızca teknik mükemmeliyetten', 'Subtonal ışık geçişleri ve sfumato tekniğinin yarattığı belirsizlik; bakış açısına göre değişen ifade', 'Boyaların solması', 'Modelin kim olduğu bilinmediğinden'], c: 1, e: 'Da Vinci\'nin sfumato tekniği; gülümsemenin kenarlarını bulanıklaştırarak izleyicinin bakış açısına ve göz hareketine bağlı değişen bir ifade illüzyonu yaratır.', d: 3 },
  { q: '"Salvador Dalí"nin en ünlü tablosunun adı nedir?', a: ['Guernica', 'The Persistence of Memory (Belleğin Azmi)', 'Les Demoiselles d\'Avignon', 'The Scream'], c: 1, e: 'Salvador Dalí\'nin 1931 tarihli "The Persistence of Memory" (Belleğin Azmi) tablosu; eriyen saatlerle zamanın akışkanlığını simgeleyen Sürrealizm\'in ikonik eseridir.', d: 1 },
  { q: '"Edward Munch"un "Çığlık" (The Scream) eserinde ne betimlenmiştir?', a: ['Deniz fırtınası', 'Varoluşsal kaygı ve paniği ifade eden figür; eriyen manzara', 'Bir savaş sahnesi', 'Dini tablo'], c: 1, e: 'Munch\'un 1893 tarihli Çığlık\'ı; doğanın "sonsuz bir çığlık attığı" hissini yaşayan kaygı dolu bir figürü, çarpık fırça darbeleriyle boyanmış eriyen bir manzara önünde gösterir.', d: 1 },
  { q: '"Henri Matisse" hangi sanat akımıyla özdeşleşir?', a: ['Kübizm', 'Empresyonizm', 'Fovizm', 'Ekspresyonizm'], c: 2, e: 'Henri Matisse; parlak, cesur renkleri ve basitleştirilmiş formlarıyla tanınan Fovizm\'in (Les Fauves - "Vahşi Hayvanlar") öncüsüdür.', d: 2 },
  { q: '"Jackson Pollock"un "action painting" tekniği nedir?', a: ['Küçük fırça darbeleriyle detaylı çalışma', 'Tuvale damlatan, döküp sıçratan beden hareketleriyle boya uygulama', 'Soyut geometrik şekiller', 'Fotoğrafçılık'], c: 1, e: 'Pollock; tuvali yere yayıp etrafında dolaşarak boya dökerek ve sıçratarak çalışırdı. Bu süreç odaklı beden hareketi sanat eserinin kendisi haline getirdi.', d: 2 },
  { q: '"Mark Rothko"nun tabloları ne anlama gelir?', a: ['Somut nesneler', 'Renk alanları; izleyicide derin duygusal deneyim yaratmaya yönelik büyük renkli dikdörtgenler', 'Soyut figürler', 'Manzara resimleri'], c: 1, e: 'Rothko\'nun büyük boyutlu renk alanları; dikkatli bir izleyicide hüzün, neşe ya da mistik bir deneyim yaratmayı hedefler. Sanatçı tablolarının ağlatması gerektiğini söylemiştir.', d: 2 },
  { q: '"Turner"ın deniz resimleri neden önemlidir?', a: ['Yalnızca tarihsel değeri', 'Işık, atmosfer ve hareketi soyutlamaya yakın bir dille aktararak Empresyonizm\'i önceden haber verdi', 'İlk deniz resimleri olduğu için', 'Sadece İngiltere\'de değer gördü'], c: 1, e: 'J.M.W. Turner\'ın 19. yüzyıl deniz ve manzara resimleri; geleneksel çizgisel anlatıdan uzaklaşarak atmosferi ve ışığı öne çıkarmasıyla Fransız Empresyonizmi\'nin habercisi sayılır.', d: 3 },
  { q: '"Michelangelo" heykeli nasıl tanımlar?', a: ['Maddenin dönüşümü', '"Mermer içinde zaten var olan figürü açığa çıkarmak"', 'Şekil yaratmak', 'Modeli kopyalamak'], c: 1, e: 'Michelangelo\'nun heykeli; mermerin içinde halihazırda var olan formu ortaya çıkarmak olarak tanımlaması sanat tarihi mitolojisine girmiştir.', d: 2 },
  { q: '"Donatello"nun "Davud" heykeli neden önemlidir?', a: ['İlk mermer heykel', 'İtalyan Rönesansı\'nda tam boy çıplak insan figürünün ilk büyük bronz örneği', 'İlk dini heykel', 'En büyük heykel'], c: 1, e: 'Donatello\'nun bronz Davud\'u (1440\'lar), Rönesans\'ta tam boy çıplak bronz figürün erken dönem başyapıtı sayılır ve klasik Yunan etkisini anımsatır.', d: 3 },
  { q: '"Bernini"nin "Santa Teresa\'nın Vecdi" heykeli hangi döneme aittir?', a: ['Rönesans', 'Barok', 'Rokoko', 'Gotik'], c: 1, e: 'Gian Lorenzo Bernini\'nin 1647-52 tarihli bu heykeli; Barok dönemin dramatik hareket, ışık oyunu ve duygusal yoğunluğunu taştaki zirveye taşıyan başyapıttır.', d: 2 },
  { q: '"Türk nakış sanatı"nın geleneksel renk ve motifleri nelerdir?', a: ['Yalnızca siyah beyaz', 'Kırmızı, mavi, altın sarısı; çiçek, lale, karanfil motifleri', 'Yalnızca geometrik', 'Yalnızca yeşil'], c: 1, e: 'Türk nakış geleneği; kırmızı, mavi, altın gibi canlı renkler ve özellikle lale, karanfil, gül, nar gibi bitkisel motiflerle bezeli zengin bir estetik sunar.', d: 2 },
  { q: '"Tezhip sanatı" ne anlama gelir?', a: ['Cam boyama', 'El yazmaları ve kitaplarda altın yaldızla uygulanan geleneksel süsleme sanatı', 'Taş oymacılığı', 'Kumaş dokuma'], c: 1, e: 'Tezhip; el yazmalarının, Kuran nüshalarının ve belgelerin kenar ve sayfa boşluklarına altın yaldız ve renkli pigmentlerle uygulanan İslam dünyasının geleneksel kitap süsleme sanatıdır.', d: 2 },
  { q: '"Türk kilim" ile "Türk halı" arasındaki temel fark nedir?', a: ['İkisi aynıdır', 'Kilim düz dokuma (havasz); halı ilmekli dokuma (havlı) yapılır', 'Halı daha büyüktür', 'Kilim daha pahalıdır'], c: 1, e: 'Kilim; ilmek kullanılmadan düz dokuma yöntemiyle üretilir. Halı ise ilmek tekniğiyle havlı dokuma yapılır; bu iki yöntem farklı doku ve görünüm yaratır.', d: 2 },
  { q: '"Karagöz ve Hacivat" gölge oyununun temel malzemesi nedir?', a: ['Ahşap kuklalar', 'Deriden yapılmış şeffaf veya renklendirilmiş figürler ve ışıklı ekran', 'Kumaş kuklalar', 'Cam malzeme'], c: 1, e: 'Karagöz ve Hacivat figürleri; genellikle deve ya da manda derisinden işlenerek hazırlanan, ışıklı beyaz ekranda gölge oluşturan renkli dekoratif figurlerden yapılır.', d: 2 },
  { q: '"Türk el sanatlarında" "sırma" ne anlama gelir?', a: ['İpek kumaş', 'Altın ya da gümüş tel kullanılarak yapılan süsleme işlemeciliği', 'Taş nakışı', 'Deri boyama'], c: 1, e: 'Sırma; metal tel (altın, gümüş) ile kumaş üzerine yapılan işleme sanatıdır. Osmanlı saray kıyafetleri ve askeri giysilerde yoğun kullanılmıştır.', d: 2 },
  { q: '"Iznik çinisinin" üretimi hangi dönemde zirveye ulaştı?', a: ['Selçuklu dönemi', 'Osmanlı dönemi 15-17. yüzyıllar', '19. yüzyıl', 'Cumhuriyet dönemi'], c: 1, e: 'İznik çinisi, 15. yüzyıldan 17. yüzyıla kadar süren Osmanlı altın çağında kobalt mavisi, kırmızı ve beyazla hazırlanan muhteşem özgün kompozisyonlarla zirveye ulaştı.', d: 2 },
  { q: '"Türkiye\'de modern sanat müzesi" olarak öne çıkan kurum hangisidir?', a: ['Topkapı Sarayı Müzesi', 'Istanbul Modern', 'Ankara Etnografya Müzesi', 'Pera Müzesi'], c: 1, e: 'İstanbul Modern (2004), Türkiye\'nin ilk modern ve çağdaş sanat müzesidir; güncel Türk sanatını ve uluslararası sergileri bünyesinde barındırır.', d: 2 },
  { q: '"Pera Müzesi"nin önemi nedir?', a: ['Yalnızca Osmanlı eserleri', 'Osman Hamdi Bey\'in eserleri ve özel koleksiyonları barındıran İstanbul\'daki sanat müzesi', 'Yalnızca modern sanat', 'Devlet müzesi'], c: 1, e: 'Pera Müzesi, Suna ve İnan Kıraç Vakfı\'nın özel koleksiyonunu barındırır; Osman Hamdi Bey\'in tabloları başta olmak üzere Osmanlı resim sanatı ve Anadolu ağırlıklı eserleriyle öne çıkar.', d: 2 },
  { q: '"Türk edebiyatında Nobel Ödülü" kazanan eser hangisidir?', a: ['Mesnevi', 'Orhan Pamuk\'un "Benim Adım Kırmızı" başta olmak üzere yapıtları', 'Yaşar Kemal\'in eserleri', 'İnce Memed'], c: 1, e: 'Orhan Pamuk, 2006 Nobel Edebiyat Ödülü\'nü kazandı; "Benim Adım Kırmızı" ve "Kar" gibi eserleri uluslararası beğeni topladı.', d: 1 },
  { q: '"Nazım Hikmet" Türk edebiyatında nasıl bir yere sahiptir?', a: ['Divan şairi', 'Serbest Türkçe şiirin öncüsü ve toplumcu şiirin en önemli temsilcisi', 'Roman yazarı', 'Tiyatro yazarı'], c: 1, e: 'Nazım Hikmet Ran; serbest şiir formunu Türk edebiyatına taşıyan, toplumsal temaları lirik dille buluşturan ve pek çok dile çevrilen Türk şiirinin dünya çapında tanınan ustasıdır.', d: 1 },
  { q: '"Yaşar Kemal" hangi eserleriyle tanınır?', a: ['Mesnevi', 'İnce Memed ve Çukurova efsaneleri', 'Yalnızca şiir', 'Divan edebiyatı'], c: 1, e: 'Yaşar Kemal; İnce Memed, Dağın Öte Yüzü gibi epik romanlarıyla Anadolu halk geleneğini ve Çukurova coğrafyasını evrensel bir dille dünya edebiyatına taşıdı.', d: 1 },
  { q: '"Türk müziğinde makam" ne anlama gelir?', a: ['Ritim kalıbı', 'Belirli perde dizisi ve melodik kurallara sahip müzik modu', 'Enstrüman türü', 'Nota sistemi'], c: 1, e: 'Makam; Türk müziğinde belirli perdeler, seyir kuralları ve karakteristik melodic formüllerden oluşan modal müzik çerçevesidir. Hicaz, Rast, Uşşak gibi yüzlerce makam mevcuttur.', d: 2 },
  { q: '"Fasıl müziği" nedir?', a: ['Türk halk müziği', 'Türk sanat müziğinin eserlerden oluşan toplu icra geleneği', 'Dini müzik', 'Askeri müzik'], c: 1, e: 'Fasıl; Türk sanat müziğinde aynı makamdan seçilmiş peşrev, şarkı, saz semaisi gibi farklı formların art arda seslendirilerek oluşturduğu toplu icra geleneğidir.', d: 2 },
  { q: '"Münir Nurettin Selçuk" Türk müziğinde kim olarak tanınır?', a: ['Besteci', 'Türk sanat müziğinin efsanevi yorumcusu', 'Halk ozanı', 'Caz müzisyeni'], c: 1, e: 'Münir Nurettin Selçuk (1900-1981), Türk sanat müziğinin ses tekniğini ve sahneleme anlayışını dönüştüren, onlarca eseri klasikleştiren usta yorumcusudur.', d: 2 },
  { q: '"Zeki Müren" Türk müziğinde nasıl anılır?', a: ['Halk ozanı', '"Sanat Güneşi" lakabıyla Türk sanat müziğinin efsanesi', 'Caz sanatçısı', 'Arabesk şarkıcısı'], c: 1, e: 'Zeki Müren; müzik, tiyatro ve sinema yeteneğini, çarpıcı sahne kıyafetleri ve yorumuyla birleştirerek "Sanat Güneşi" lakabını kazanan çok boyutlu bir Türk sanat ustasıdır.', d: 1 },
  { q: '"Barış Manço" Türk müziğinde hangi özgün tarzla tanınır?', a: ['Yalnızca pop', 'Türk halk müziğini rock ile harmanlayan özgün sentez', 'Yalnızca arabesk', 'Klasik Türk müziği'], c: 1, e: 'Barış Manço; Türk halk müziği enstrümanlarını elektro gitar ile buluşturan, özgün kostümleri ve "Dönence" gibi hitleriyle milyonları büyüleyen ikonik Türk müzisyenidir.', d: 1 },
  { q: '"Sezen Aksu" Türk pop müziğine nasıl katkıda bulunmuştur?', a: ['Yalnızca şarkıcı', 'Söz yazarı, besteci ve yorumcusu olarak Türk pop müziğini şekillendiren "Türk Popunun Kraliçesi"', 'Yalnızca dini müzik', 'Yalnızca folk'], c: 1, e: 'Sezen Aksu; söz yazarlığı, besteciliği ve sesini bir arada kullanan, Tarkan ve diğer pek çok sanatçıya şarkılar yazan ve "küçük hanım" lakabıyla sevilen Türk pop müziğinin efsanevi ismidir.', d: 1 },
  { q: '"Arabesk müzik" nedir?', a: ['Tamamen Arap müziği', 'Türkiye\'ye özgü, Arap etkisi ve Türk melodileriyle halk müziğinin harmanından doğan duygusal müzik türü', 'Klasik Türk müziği türü', 'Orkestra müziği'], c: 1, e: 'Arabesk; Türkiye\'de özellikle göç edenlerin kentlerde yarattığı, Arap müziği etkisi taşıyan, hüzün ve kader temalarını öne çıkaran özgün müzik türüdür. Orhan Gencebay bu türün kurucusu sayılır.', d: 1 },
  { q: '"Türkiye\'de opera" hangi kurumla yaygınlaştı?', a: ['TRT', 'Devlet Opera ve Balesi (DOB)', 'Özel opera şirketleri', 'İstanbul Müzik Festivali'], c: 1, e: 'Devlet Opera ve Balesi (DOB), kuruluşundan bu yana Ankara, İstanbul ve diğer büyük şehirlerde Türk opera ve bale sanatını halka ulaştıran ana kamu kurumudur.', d: 2 },
  { q: '"Türkiye\'de çağdaş sanat" alanında öne çıkan etkinlik nedir?', a: ['Yalnızca müze sergileri', 'İstanbul Bienali ve çeşitli çağdaş sanat fuarları', 'Yalnızca okul etkinlikleri', 'Yalnızca devlet sergileri'], c: 1, e: '1987\'den bu yana iki yılda bir düzenlenen İstanbul Bienali; Türkiye\'nin en prestijli çağdaş sanat etkinliği ve uluslararası sanat çevrelerinin buluşma noktasıdır.', d: 2 },
  { q: '"Heykel sanatında "çok malzeme" (mixed media) ne anlama gelir?', a: ['Sadece mermer', 'Birden fazla farklı malzeme ya da tekniğin bir arada kullanıldığı sanat', 'Boyamanın bir türü', 'Sadece metal'], c: 1, e: 'Mixed media (karışık teknik); video, fotoğraf, tekstil, metal ve boyayı bir arada kullanarak geleneksel malzeme sınırlarını aşan çağdaş sanat pratiğidir.', d: 2 },
  { q: '"Duchamp"ın "Çeşme" (Fountain) eseri sanat tarihini nasıl etkiledi?', a: ['Teknique açısından öncü', 'Sıradan bir pisuarın "sanat" olarak sunulmasıyla "hazır nesne" (readymade) kavramını yarattı', 'İlk soyut heykel', 'Dini sanat eleştirisi'], c: 1, e: 'Marcel Duchamp, 1917\'de imzalayıp sergiye sunduğu pisuarla sanatın ne olduğu sorusunu kökten sorguladı; "readymade" kavramı ve Dada hareketi üzerindeki etkisi günümüz sanatını şekillendirmeye devam etmektedir.', d: 2 },
  { q: '"Joseph Beuys"un "performans sanatı" anlayışı nedir?', a: ['Geleneksel sahne sanatı', 'Her insanın sanatçı olduğu ve sanatın toplumu iyileştirme işlevi gördüğü genişletilmiş sanat anlayışı', 'Yalnızca dans', 'Resim sanatı'], c: 1, e: 'Joseph Beuys; "Her insan bir sanatçıdır" sözü ve toplumsal eleştirilerini beden performansına dönüştüren eylemleriyle 20. yüzyılın en etkili kavramsal sanatçılarından biridir.', d: 3 },
  { q: '"Türkiye\'de müzik eğitimi"nin temel kurumu nedir?', a: ['TRT Orkestrası', 'Konservatuvar (Devlet ve üniversite bağlantılı)', 'Yalnızca özel okullar', 'Milli Eğitim Bakanlığı'], c: 1, e: 'Türkiye\'deki devlet konservatuvarları ve üniversite konservatuvarları; klasik müzik, Türk müziği ve sahne sanatları eğitiminin temel kurumlarıdır.', d: 2 },
  { q: '"Gustav Klimt"in sanatının ayırt edici özelliği nedir?', a: ['Siyah beyaz', 'Altın yaldız kullanımı ve dekoratif sembolizm; Art Nouveau ve Sembolizm\'in sentezi', 'Minimalizm', 'Soyut boya damlaları'], c: 1, e: 'Klimt\'in "Öpücük" ve "Judith" gibi eserleri; Bizans mozaiğinden ilham alan altın yaldız uygulaması, bedenin dekoratif motiflerle iç içe geçmesi ve sembolik yorumlarla Art Nouveau\'nun zirvesini oluşturur.', d: 2 },
  { q: '"Egon Schiele" sanat tarihinde nasıl anılır?', a: ['Empresyonist ressam', 'İnsan bedenini çarpıtılmış, gergin ve savunmasız biçimde aktaran Ekspresyonist Avusturyalı ressam', 'Soyut sanatçı', 'Heykeltıraş'], c: 1, e: 'Egon Schiele; Klimt\'in öğrencisi olup insan figürünü çarpıtılmış, sert çizgilerle betimleyen ve cinselliği ya da ölümlülüğü psikolojik yoğunlukla ele alan Avusturyalı Ekspresyonisttir.', d: 3 },
  { q: '"Toulouse-Lautrec"in sanatının özelliği nedir?', a: ['Dini tablolar', '19. yüzyıl sonu Paris gece hayatını; kabaret, dans salonları ve sanatçıları belgeleyen afişler ve litografiler', 'Manzara resimleri', 'Portreler'], c: 1, e: 'Lautrec\'in Moulin Rouge afişleri ve litografileri; 1880-90\'lar Montmartre\'ı, dans ve gece hayatını canlı çizgi ve renk tasarımıyla ölümsüzleştirdi; modern grafik tasarımı etkiledi.', d: 2 },
  { q: '"Banksy" kim/nedir?', a: ['Ünlü Fransız ressam', 'Kimliği bilinmeyen İngiliz sokak sanatçısı; siyasi hiciv içeren grafiti ve enstalasyonlarıyla tanınır', 'Bir sanat müzesi', 'Çizgi film karakteri'], c: 1, e: 'Banksy, kimliği gizemini koruyan İngiliz sokak sanatçısıdır; şiddet karşıtlığı, tüketicilik eleştirisi ve siyasi hicivi grafiti ve enstalasyona dönüştürerek dünya gündemine girdi.', d: 1 },
  { q: '"Yayoi Kusama"nın sanatının ayırt edici unsuru nedir?', a: ['Karanlık renkler', 'Puanlar ve tekrarlayan örüntüler; sonsuzluk odaları ve soyut enstalasyonlar', 'Geleneksel Japon resim', 'Heykel'], c: 1, e: 'Yayoi Kusama; onlarca yıl boyunca puan obsesyonunu tüm yüzeylere, kendiğine ve sonradan devasa enstalasyonlara uyguladı; "Sonsuzluk Odaları" serisi dünya çapında büyük ilgi gördü.', d: 2 },
  { q: '"Ai Weiwei" kim olarak tanınır?', a: ['Japon geleneksel sanatçı', 'Çinli çağdaş sanatçı ve aktivist; siyasi eleştirilerini sanatıyla bütünleştiriyor', 'Amerikan heykeltıraşı', 'Fransız mimar'], c: 1, e: 'Ai Weiwei; Çin hükümetini eleştiren enstalasyonları, insan hakları savunuculuğu ve mimarisiyle dünyanın en tanınan çağdaş sanatçı-aktivistlerinden biridir.', d: 2 },
  { q: '"Cindy Sherman"in fotoğrafları neyle öne çıkar?', a: ['Doğa fotoğrafçılığı', 'Farklı kadın arketiplerini canlandırdığı öz portreleriyle kimlik, medya ve toplumsal cinsiyet sorgulaması', 'Manzara çekimleri', 'Belgesel fotoğrafçılık'], c: 1, e: 'Cindy Sherman; kılık değiştirerek çeşitli kadın arketiplerini ve medya klişelerini kendisi canlandırdığı fotoğraf serisiyle kimlik, cinsiyet ve temsil üzerine derin sorular sorar.', d: 3 },
  { q: '"Wolfgang Amadeus Mozart" kaç yaşında hayatını kaybetti?', a: ['25', '30', '35', '41'], c: 2, e: 'Wolfgang Amadeus Mozart, 35 yaşında 5 Aralık 1791\'de Viyana\'da hayatını kaybetti; kısa ömrüne yüzlerce eser sığdırdı.', d: 1 },
  { q: '"Ludwig van Beethoven" hangi zorlukla mücadele etmiştir?', a: ['Görme engeli', 'İşitme kaybı; sonunda tamamen sağır oldu', 'Fiziksel engel', 'Ruh sağlığı sorunu'], c: 1, e: 'Beethoven, 20\'li yaşlarında başlayan işitme kaybıyla mücadele etti ve kariyerinin son döneminde tamamen sağır olmasına rağmen 9. Senfoni dahil başyapıtlarını besteledi.', d: 1 },
  { q: '"Johann Sebastian Bach" hangi dönem ve tarzla özdeşleşir?', a: ['Klasik dönem', 'Barok dönem; kontrpuan ve polifoninin ustası', 'Romantik dönem', 'Empresyonist dönem'], c: 1, e: 'Bach, 1600-1750 Barok döneminin zirvesidir; Mathew Passion, Das Wohltemperierte Klavier ve Brandenburg Konçertoları gibi yapıtlarla kontrpuan sanatını zirveye taşıdı.', d: 2 },
  { q: '"Frédéric Chopin"in müziği hangi enstrümanla özdeşleşir?', a: ['Keman', 'Piyano', 'Çello', 'Klarnet'], c: 1, e: 'Chopin neredeyse tüm eserlerini piyano için yazdı; etüdleri, noktürnleri ve polonezleriyle Romantik dönem piyano edebiyatının en önemli bestecisidir.', d: 1 },
  { q: '"Igor Stravinsky" hangi balenin müziğini yazmıştır?', a: ['Kuğu Gölü', 'Uyuyan Güzel', 'Ateş Kuşu, Bahar Ayini, Mahraba', 'Don Kişot'], c: 2, e: 'Stravinsky; Ateş Kuşu (1910), Mahraba (1911) ve Bahar Ayini (1913) ile çağdaş müziğin seyrini değiştirdi; Bahar Ayini\'nin prömiyeri skandala yol açtı.', d: 2 },
  { q: '"Billie Holiday" kimdir?', a: ['Klasik viyolinist', 'Amerikan caz ve blues şarkıcısı; "Strange Fruit" ile ırkçılığı sanat diliyle eleştirdi', 'Türk pop sanatçısı', 'Fransız opera şarkıcısı'], c: 1, e: 'Billie Holiday; caz tarihinin en etkili seslerinden biri olan ve "Strange Fruit" şarkısıyla ABD\'deki ırkçı linç pratiğini dünya gündemine taşıyan Afro-Amerikan blues-caz sanatçısıdır.', d: 2 },
  { q: '"Miles Davis" modern caza ne kazandırdı?', a: ['Yalnızca trompet tekniği', '"Sessizliğin gücü" ve cool jazz, modal jazz, fusion gibi yeni caz stillerinin öncülüğü', 'Blues armonisi', 'Klasik form'], c: 1, e: 'Miles Davis; Kind of Blue, Bitches Brew gibi albümlerle sürekli kendini yeniledi; cool jazz, modal jazz ve jazz-rock füzyonunu şekillendirerek 20. yüzyılın en etkili müzisyenlerinden biri oldu.', d: 2 },
  { q: '"The Beatles" müzik tarihini nasıl değiştirdi?', a: ['Yalnızca İngiltere\'de etki yarattı', 'Rock\'n\'roll\'u sanatsal biçimde geliştirerek stüdyo çalışması, söz yazarlığı ve pop kültürünü dönüştürdü', 'Yalnızca 1 albüm çıkardı', 'Yalnızca caz müziği yaptı'], c: 1, e: 'The Beatles; 1960\'larda söz yazarlığı, armoni, stüdyo yenilikleri (Sgt. Pepper) ve kültürel etkileriyle rock müziğini sanatsal bir disipline dönüştürerek tüm dünyayı sardı.', d: 1 },
  { q: '"Arabesk müziğin babası" olarak anılan sanatçı kimdir?', a: ['Müslüm Gürses', 'Orhan Gencebay', 'İbrahim Tatlıses', 'Bülent Ersoy'], c: 1, e: 'Orhan Gencebay; 1969\'da "Bir Teselli Ver" ile başlayan müzik yolculuğuyla Türkiye\'de arabesk türünü oluşturan ve bu türün kurucusu olarak anılan isimdir.', d: 1 },
  { q: '"Müslüm Gürses" neden efsane sayılır?', a: ['En fazla albüm satan', 'Dramatik yorumu ve sözleriyle arabesk müzikte derin iz bırakan "Müslüm Baba"', 'Yalnızca filmlerde oynayan', 'Klasik müzik yorumcusu'], c: 1, e: 'Müslüm Gürses; acı, aşk ve kaderi derin bir coşkuyla yorumlayan sesi ve "Müslüm Baba" kimliğiyle Türkiye\'nin en sevilen arabesk sanatçılarından biri olarak tarihe geçti.', d: 1 },
  { q: '"Türk rock müziğinin" öncüsü sayılan grup kimdir?', a: ['Sezen Aksu', 'Moğollar ve Cem Karaca', 'Tarkan', 'Sertab Erener'], c: 1, e: 'Moğollar ve Cem Karaca; Türk halk müziğini rock ile birleştirerek "Anadolu rock" anlayışını 1960-70\'lerde oluşturan öncü isimlerdir.', d: 2 },
  { q: '"Tarkan" Türk pop müziğinde nasıl öne çıkmıştır?', a: ['Yalnızca Türk dinleyiciler için', 'Uluslararası arenada da iz bırakan sahne performansı ve müziğiyle "Mega Star" unvanını kazandı', 'Yalnızca arabesk', 'Yalnızca 1 albüm çıkardı'], c: 1, e: 'Tarkan; Hepsi Senin Mi, Şımarık gibi hitleriyle uluslararası arenada da tanınan, güçlü sahne performansı ve kalabalık dinleyici kitlesiyle Türk pop tarihinin en büyük isimlerinden biridir.', d: 1 },
  { q: '"Türkiye\'de sanat eğitimi" hangi kurumlar aracılığıyla verilmektedir?', a: ['Yalnızca özel atölyeler', 'Güzel sanatlar fakülteleri, konservatuvarlar, mesleki liseler ve özel sanat okulları', 'Yalnızca devlet müzeleri', 'Yalnızca yurt dışı bursları'], c: 1, e: 'Türkiye\'de sanat eğitimi; güzel sanatlar ve tasarım fakülteleri, devlet konservatuvarları, güzel sanatlar liseleri ve özel sanat okulları aracılığıyla çeşitli kademelerde verilmektedir.', d: 2 },
  { q: '"Gotik" mimari hangi yapıyla simgeleşmiştir?', a: ['Partenon', 'Notre-Dame Katedrali', 'Pantheon', 'Hagia Sophia'], c: 1, e: 'Notre-Dame de Paris, sivri kemerleri, uçan payandaları ve renkli vitraylarıyla Gotik mimari geleneğinin en tanınan simgelerinden biridir.', d: 1 },
  { q: '"Bauhaus" tasarım okulu hangi ülkede kuruldu?', a: ['İsviçre', 'Avusturya', 'Almanya', 'İsveç'], c: 2, e: 'Bauhaus; 1919\'da Walter Gropius\'un önderliğinde Almanya\'nın Weimar şehrinde kurulan ve sanat-zanaat-endüstri birlikteliğini savunan devrimci tasarım okuludur.', d: 2 },
  { q: '"Empresyonizm" neden akademiye karşı çıktı?', a: ['Figür resmine karşı', 'Akademik kurallar yerine anlık izlenim ve ışık-renk deneyimini öne çıkardı', 'Renkten kaçındı', 'Yalnızca portre yaptı'], c: 1, e: 'Empresyonistler; Fransız Akademisi\'nin sert çizgi ve "yüksek konu" anlayışını reddederek gündelik yaşamı, doğayı ve anlık ışık değişimini tuvale aktarmayı tercih etti.', d: 2 },
  { q: '"Duchamp"ın dışında "ready-made" (hazır nesne) kavramını kullanan diğer önemli sanatçılar kimlerdir?', a: ['Yalnızca Duchamp', 'Andy Warhol, Jeff Koons ve Damien Hirst gibi sanatçılar hazır nesneyi farklı biçimlerde kullandı', 'Yalnızca Picasso', 'Yalnızca Kandinsky'], c: 1, e: 'Andy Warhol\'un Campbell\'s çorba kutuları, Jeff Koons\'un balon köpekleri ve Damien Hirst\'in formaldehit içindeki hayvanları; ready-made kavramını çeşitli biçimlerde yorumlayan önemli örneklerdir.', d: 2 },
  { q: '"Minyatür resim" Türk-İslam sanatında hangi malzeme üzerine yapılırdı?', a: ['Tuval', 'El yazması kağıt, deri ve fildişi üzerine', 'Ahşap', 'Taş'], c: 1, e: 'Geleneksel minyatür resmi; el yazması kitapların kağıt sayfaları, deri ya da fildişi üzerine doğal pigmentlerle hazırlanan çok ince fırçayla yapılırdı.', d: 2 },
  { q: '"Türk hat sanatının" en önemli ustası kimdir?', a: ['Sinan', 'Şeyh Hamdullah', 'Osman Hamdi Bey', 'İbrahim Çallı'], c: 1, e: 'Şeyh Hamdullah (1436-1520), Osmanlı hat sanatının en büyük ustası kabul edilir; geliştirdiği üslup bugün hâlâ hat sanatının referans noktasıdır.', d: 2 },
  { q: '"Türk sedefkârlığı" nedir?', a: ['Ahşap boyama', 'Sedef kabuğu parçalarının ahşap eşya üzerine kakılmasıyla yapılan geleneksel süsleme sanatı', 'Cam işlemeciliği', 'Kumaş dokuma'], c: 1, e: 'Sedefkârlık; inci sedefinin ince dilimlerinin ahşap yüzeylere kakılması ve perdahlanmasıyla elde edilen Osmanlı-Türk el sanatıdır. Özellikle sandık, müzik aleti ve mobilyalarda kullanılır.', d: 2 },
  { q: '"Türk çini ve seramiğinin" dünya müzelerindeki önemi nedir?', a: ['Yalnızca Türkiye\'de ilgi görür', 'Louvre, British Museum ve Metropolitan müzelerinde Osmanlı dönemi çini koleksiyonları sergilenmektedir', 'Yalnızca İznik\'te üretilir', 'Modern sanat sayılır'], c: 1, e: 'Osmanlı dönemine ait İznik çinileri ve seramikleri; Paris Louvre, Londra British Museum ve New York Metropolitan müzelerinde önemli koleksiyonlarla sergilenmektedir.', d: 2 },
  { q: '"Tanzimat dönemi edebiyatı"nın öne çıkan özellikleri nelerdir?', a: ['Yalnızca divan şiiri', 'Divan geleneğinden Batılı biçimlere geçiş; roman, tiyatro ve gazete edebiyatının başlangıcı', 'Yalnızca halk edebiyatı', 'Yalnızca dini edebiyat'], c: 1, e: 'Tanzimat edebiyatı; Namık Kemal, Şinasi ve Ahmet Cevdet Paşa gibi yazarların roman, tiyatro ve gazete türleriyle Divan geleneğinden Batılı anlatı biçimlerine geçişi sağladığı devrimsel dönemdir.', d: 2 },
  { q: '"Servet-i Fünun" edebiyat akımı nedir?', a: ['Halk şiiri', 'Batı estetiğini Osmanlı Türkçesiyle buluşturan 1890\'lar edebiyat topluluğu', 'Dini edebiyat', 'Cumhuriyet dönemi'], c: 1, e: 'Servet-i Fünun; 1890\'larda Recaizade Mahmut Ekrem ve Tevfik Fikret önderliğinde Fransız Parnasyen-Sembolizm etkisiyle şekillenen, aynı adlı dergide toplanan edebi topluluktur.', d: 3 },
  { q: '"Milli Edebiyat" hareketi Türk edebiyatında ne anlama gelir?', a: ['Osmanlı divan şiiri', 'Sade Türkçe ve halk kaynaklarına yönelen 20. yüzyıl başı milliyetçi edebiyat akımı', 'Batı taklitçiliği', 'Dini edebiyat'], c: 1, e: 'Milli Edebiyat; Ömer Seyfettin, Ziya Gökalp ve Halide Edib gibi isimlerin önderliğinde sade Türkçeyi, halk kültürünü ve milli kimliği ön plana çıkaran 1910\'lu yılların edebiyat hareketidir.', d: 2 },
  { q: '"Cumhuriyet dönemi Türk resmi"nin öne çıkan temsilcisi kimdir?', a: ['Osman Hamdi Bey', 'İbrahim Çallı', 'Namık İsmail', 'Hepsi birden farklı dönemlerde'], c: 3, e: 'Türk resminin kuşakları farklıdır: Osman Hamdi Bey (Osmanlı son dönemi), İbrahim Çallı ve Namık İsmail (Çallı kuşağı, Cumhuriyet erken dönemi); her biri kendi döneminin öncüsüdür.', d: 2 },
  { q: '"Müzikte "doğaçlama" (improvisation) nedir?', a: ['Notadan çalmak', 'Anlık kompozisyon; sanatçının anında yaratarak icra etmesi', 'Yalnızca caz müziği', 'Şarkının tekrarı'], c: 1, e: 'Doğaçlama; sanatçının önceden yazılmış nota olmaksızın anlık ilham ve teknik beceriyle müzik üretmesidir. Caz, blues ve Türk klasik müziğinde temel icra pratiğidir.', d: 2 },
  { q: '"Rock müziği" nasıl tanımlanır?', a: ['Yalnızca gürültülü müzik', 'Elektro gitar, ritm bölümü ve güçlü vokal üzerine kurulu, 1950\'lerde doğan popüler müzik türü', 'Yalnızca Amerikan müziği', 'Yalnızca 1960\'lara özgü'], c: 1, e: 'Rock müziği; blues ve country\'den ilham alan, elektrik gitar-bas-davul üçlüsüyle şekillenen ve 1950\'lerde Elvis Presley ve Chuck Berry gibi isimlerle doğan küresel müzik türüdür.', d: 1 },
  { q: '"Hip-hop" kültürü hangi unsurlardan oluşur?', a: ['Yalnızca rap müziği', 'Rap (MC), DJ\'lik, breakdance ve grafiti olmak üzere dört temel unsur', 'Yalnızca dans', 'Yalnızca New York'], c: 1, e: 'Hip-hop kültürü; 1970\'lerde New York\'un Bronx semtinde doğan ve rap müzik, DJ\'lik (turntablism), breakdance ve grafiti sanatını kapsayan dört temel unsurdan oluşan kentsel kültür hareketidir.', d: 2 },
  { q: '"Opera"nın kökeni nerede ve ne zaman?', a: ['Almanya, 18. yüzyıl', 'İtalya, 16. yüzyıl sonu - 17. yüzyıl başı', 'Fransa, 19. yüzyıl', 'Yunanistan, antik dönem'], c: 1, e: 'Opera; 16. yüzyıl sonunda Floransa\'da Camerata adlı entelektüel grubun antik Yunan dramını müzikle canlandırma denemeleriyle doğdu. İlk opera eseri Jacopo Peri\'nin Dafne\'si (1597-98) kabul edilir.', d: 2 },
  { q: '"Bale"nin doğduğu ülke hangisidir?', a: ['Almanya', 'İtalya ve Fransa', 'Rusya', 'İspanya'], c: 1, e: 'Bale; 15-16. yüzyılda İtalyan Rönesansı\'nda saray gösterileri olarak başladı ve Fransa\'da biçimlendi. 17. yüzyılda Louis XIV döneminde profesyonel dans okulu kurulmasıyla sistematize oldu.', d: 2 },
  { q: '"Empresyonizm"de "yüzey dokusu" neden önem kazandı?', a: ['Görsel efekt için', 'Fırça izlerinin görünür bırakılması renk-ışık titreşimini artırarak anlık izlenimi güçlendirdi', 'Ekonomiklik nedeniyle', 'Gizli teknik'], c: 1, e: 'Monet ve Renoir gibi empresyonistler; düzgün yüzey yerine kalın, görünür fırça dokunuşlarıyla ışığın yüzeyde parıltısını ve anlık atmosferi yakaladılar.', d: 2 },
  { q: '"Sürrealizm" akımının öncüsü kimdir?', a: ['Salvador Dali', 'André Breton', 'Max Ernst', 'René Magritte'], c: 1, e: 'Sürrealizm; 1924\'te Fransız yazar André Breton\'un "Sürrealizm Manifestosu"yla başlatıldı. Freud\'un bilinçdışı kuramından ilham alan hareket; rüya imgelerini ve mantık dışı bağlantıları sanata taşıdı.', d: 2 },
  { q: '"Soyut dışavurumculuk" hangi ülkede doğdu?', a: ['Fransa', 'Almanya', 'ABD (New York)', 'İtalya'], c: 2, e: 'Soyut Dışavurumculuk (Abstract Expressionism); 1940\'larda New York\'ta Jackson Pollock, Mark Rothko ve Willem de Kooning gibi sanatçılarla doğdu. Sanat dünyasının ağırlık merkezini Avrupa\'dan ABD\'ye taşıdı.', d: 2 },
  { q: '"Pop Art"ı diğer akımlardan ayıran temel özellik nedir?', a: ['Soyutlama', 'Kitle kültürü, reklam, pop müzik ve tüketim nesnelerini sanat malzemesi olarak kullanmak', 'Klasik teknik', 'Heykel odaklı'], c: 1, e: 'Pop Art; Andy Warhol ve Roy Lichtenstein öncülüğünde 1950-60\'larda reklam, film yıldızları, ambalaj ve çizgi roman gibi kitle kültürü imgelerini yüksek sanata taşıdı.', d: 1 },
  { q: '"Kübizm" sanatın görsel dilini nasıl değiştirdi?', a: ['Rengi daha çok kullandı', 'Tek bakış açısı yerine çok bakış açısını aynı anda göstererek perspektif geleneğini yıktı', 'Soyutlamayı kaldırdı', 'Yalnızca heykel için gelişti'], c: 1, e: 'Picasso ve Braque\'ın geliştirdiği Kübizm; tek noktadan bakış yerine bir nesneyi farklı açılardan aynı anda parçalara bölerek resmin düzlemsel gerçekliğini öne çıkardı.', d: 2 },
  { q: '"Barok dönem" sanatının özellikleri nelerdir?', a: ['Sadelik ve soyutlama', 'Dramatik ışık-gölge, hareket, duygusallık ve görkemli süsleme; 17. yüzyıl Avrupa\'sında', 'Yalnızca mimari', 'Minimalist görüntü'], c: 1, e: 'Barok; 17. yüzyılda İtalya\'dan yayılan, Caravaggio\'nun chiaroscuro (aydınlık-karanlık) tekniği ve Bernini\'nin dramatik heykelleriyle tanınan güçlü duygusal-gösterişli sanattır.', d: 2 },
  { q: '"Rönesans sanatı"nın temel yenilikleri nelerdir?', a: ['Yalnızca dini konu', 'Perspektif (derinlik), insan anatomisi, bireysel portre ve antik Yunan-Roma mirasının yeniden canlanması', 'Soyutlama', 'Yalnızca heykel'], c: 1, e: 'Rönesans; doğrusal perspektif, insan figürünün anatomik doğruluğu, bireysel portre ve paganist antik konuların yeniden ele alınmasıyla Orta Çağ geleneğinden köklü kopuşu temsil eder.', d: 2 },
  { q: '"Michelangelo" hangi eseriyle tavan freskosunda zirveye ulaştı?', a: ['Mona Lisa', 'Son Akşam Yemeği', 'Sistine Şapeli tavanı', 'Venüs\'ün Doğuşu'], c: 2, e: 'Michelangelo; 1508-1512 yıllarında Vatikan\'daki Sistine Şapeli tavanını boyayarak dönemin en büyük sanat başarılarından birini gerçekleştirdi. Tanrı\'nın Adem\'i Yaratışı en ünlü bölümüdür.', d: 1 },
  { q: '"Fütürizm" akımı nereye ve neye odaklandı?', a: ['Geçmişi kutlamak', 'İtalya\'da doğan ve hız, makine, kentsel yaşam ve teknolojinin dinamizmini yücelten 20. yüzyıl başı akımı', 'Doğa ve huzur', 'Dini konular'], c: 1, e: 'Fütürizm; 1909\'da Marinetti\'nin manifestosuyla İtalya\'da başladı; otomobil, uçak, demir yolu ve endüstriyel dinamizmi sanatsal konu olarak benimseyerek geçmişi reddetti.', d: 2 },
  { q: '"Dadaizm" neden ortaya çıktı?', a: ['Güzelliği kutlamak için', 'Birinci Dünya Savaşı\'nın saçmalığına karşı tutumlu bir protesto hareketi olarak', 'Teknik mükemmellik için', 'Dini reform'], c: 1, e: 'Dada; 1916\'da Zürih\'te Birinci Dünya Savaşı\'nın vahşetine karşı anlamsızlığı kucaklayan bir sanat-karşıtı isyan olarak doğdu. Mantık dışı, şok edici ve ironik eserlerle kültüre meydan okudu.', d: 2 },
  { q: '"Minimalizm" sanat anlayışı neyi öngörür?', a: ['Çok renkli ve karmaşık', '"Daha azı daha çoktur"; gereksiz süsü kaldırarak saf form, renk ve materyal üzerine odaklanmak', 'Duygusal yoğunluk', 'Klasik referanslar'], c: 1, e: 'Minimalizm; 1960\'larda ABD\'de Donald Judd ve Dan Flavin gibi sanatçılarla doğdu. Gereksiz süsü reddederek formu, rengi ve malzemenin kendisini ön plana çıkardı.', d: 2 },
  { q: '"Türk ebru sanatı"nın temel tekniği nedir?', a: ['Kağıda direkt boyama', 'Su yüzeyinde kıvamlandırılmış sıvıya boyalar damlatılıp desenler oluşturulduktan sonra kağıda aktarılır', 'İpek üzerine', 'Duvar boyama'], c: 1, e: 'Ebru; kıvamlandırılmış su üzerine doğal boyalar damlatılarak oluşturulan desenlerin kağıda aktarılmasıyla yapılan Türk-İslam süsleme sanatıdır. 2014\'te UNESCO listesine alındı.', d: 1 },
  { q: '"Türk kilim sanatı" dünyada nasıl değerlendirilir?', a: ['Sıradan tekstil', 'Desenlerinin anlam ve geometrik soyutlamasıyla uluslararası müzelerde sanat eseri statüsünde', 'Yalnızca pratik kullanım', 'Yalnızca Orta Asya'], c: 1, e: 'Türk kilimleri; geometrik desenler, bölgesel renk kodları ve el dokuma geleneğiyle Smithsonian, V&A Müzesi ve Louvre gibi kurumların koleksiyonlarında yer alan uluslararası sanat eserleridir.', d: 2 },
  { q: '"Klasik müzik"te "senfoni" ile "konçerto" arasındaki fark nedir?', a: ['İkisi aynıdır', 'Senfoni orkestra için yazılır; konçerto solist ve orkestra diyaloğuna dayanır', 'Konçerto daha uzun', 'Senfoni yalnızca koral'], c: 1, e: 'Senfoni; tüm orkestra için yazılan büyük ölçekli bir yapıt. Konçerto ise bir solist (piyano, keman vb.) ile orkestranın diyalogunu öne çıkaran form. İkisi birbirinden tamamen farklı yapılardır.', d: 2 },
  { q: '"Tiyatroda "trajedi" kavramını kim sistematize etti?', a: ['Shakespeare', 'Aristoteles', 'Sophokles', 'Molière'], c: 1, e: 'Aristoteles; "Poetika" adlı eserinde trajedinin katharsis (arınma) işlevi, olayların bütünlüğü ve uygun karakter yapısını tanımladı. Günümüzde de drama kuramının temel referansı olmaya devam etmektedir.', d: 2 },
  { q: '"Anadolu\'da kilim dokuma geleneği" hangi bölgelerle özdeşleşir?', a: ['Yalnızca Ege', 'Konya, Kayseri, Sivas, Uşak ve Doğu Anadolu başta olmak üzere birçok bölge', 'Yalnızca Karadeniz', 'Yalnızca İstanbul'], c: 1, e: 'Konya, Kayseri ve Uşak gibi İç Anadolu şehirlerinin yanı sıra Doğu ve Güneydoğu Anadolu da kendine özgü desen ve renk paleti taşıyan halı-kilim geleneğiyle öne çıkar.', d: 2 },
  { q: '"Türk tasavvuf müziği"nin merkezinde ne vardır?', a: ['Yalnızca saz', 'Mevlevi semahı ve ney başta olmak üzere Tanrı\'ya yakınlaşmayı amaçlayan mistik müzik ritüeli', 'Yalnızca ilahi', 'Yalnızca davul'], c: 1, e: 'Türk tasavvuf müziği; Mevlana\'nın tekkelerinde geliştirilen ney, ud, tanbur eşliğinde ilahi ve sema ritüelini kapsar. Ney; ruhun özlemi ve Tanrı ile birliğin simgesidir.', d: 2 },
  { q: '"Heykel sanatında "bronz döküm" tekniği ne anlama gelir?', a: ['Taşa şekil vermek', 'Mum ya da alçı modelin etrafına kalıp oluşturup erimiş bronzu dökerek kalıcı heykel elde etme', 'Ahşap oyma', 'Kil şekillendirme'], c: 1, e: 'Bronz döküm; kayıp balmumu (cire perdue) tekniğiyle mum model etrafına seramik kalıp oluşturulması, mumun eritilmesi ve yerine sıvı bronzun dökülmesiyle heykel yapmayı sağlayan eski bir tekniktir.', d: 2 },
  { q: '"Türkiye\'de Güzel Sanatlar Akademisi" tarihsel önemi nedir?', a: ['Yok böyle bir kurum', 'Mekteb-i Sanayi-i Nefise (1882) olarak Osmanlı döneminde kurulan ve Batılı akademik sanat eğitimini Türkiye\'ye taşıyan okul', 'Yalnızca mimarlık okulu', 'Cumhuriyet döneminde kuruldu'], c: 1, e: 'Mekteb-i Sanayi-i Nefise; Osman Hamdi Bey\'in öncülüğünde 1882\'de İstanbul\'da açıldı. Türkiye\'nin ilk güzel sanatlar akademisi olarak Batılı sanat eğitimini Anadolu\'ya taşıdı.', d: 2 },
  { q: '"Film müziği" bir sanat dalı olarak nasıl gelişti?', a: ['Her zaman vardı', 'Sessiz sinema döneminde canlı piyano eşliğiyle başladı; sesli film döneminde orkestral kompozisyon sanatına dönüştü', 'Yalnızca modern dönemde', 'Yalnızca Hollywood'], c: 1, e: 'Film müziği; 1920\'lere kadar sessiz sinemalarda canlı piyano/org eşliğiyle sunuldu. Bernard Herrmann, Ennio Morricone ve John Williams gibi bestecilerle bağımsız bir sanat dalı haline geldi.', d: 2 },
  { q: '"Türk halk müziği" hangi enstrümanlarla özdeşleşir?', a: ['Yalnızca kemençe', 'Saz (bağlama), davul, zurna, kaval ve kemençe gibi çalgılar', 'Yalnızca davul', 'Yalnızca ud'], c: 1, e: 'Türk halk müziğinin temel çalgıları; bölgeye göre bağlama/saz, davul-zurna, kaval, mey ve Karadeniz\'e özgü kemençedir. Her bölgenin kendine özgü çalgı geleneği bulunur.', d: 1 },
  { q: '"Türk klasik müziği" hangi makamlar üzerine kurulur?', a: ['Yalnızca 7 nota', 'Rast, Uşşak, Hicaz, Segah, Nihavend gibi çok sayıda makam; Batı müziğinden farklı mikrotonal yapı', 'Yalnızca majör-minör', 'Tek makam'], c: 1, e: 'Türk klasik müziği; Batı müziğinin majör-minör sisteminden farklı olarak dörtlük ve ikinci aralıklara bölünmüş mikrotonal yapıdaki makamlar üzerine kuruludur. Her makamın kendine özgü atmosfer ve ifade kapasitesi vardır.', d: 2 },
  { q: '"Grafiti" sokak sanatı hangi ülkede ve ne zaman gelişti?', a: ['Fransa, 1950\'ler', 'ABD (New York, Philadelphia), 1960-70\'ler', 'Brezilya, 1980\'ler', 'İngiltere, 1990\'lar'], c: 1, e: 'Modern grafiti; 1960-70\'lerde New York ve Philadelphia\'da başladı. Gençler metro vagonlarına ve duvarlarına imza ve resimler yaparak sanatsal-siyasi bir dil geliştirdi. Banksy gibi isimlerle galeri ortamına taşındı.', d: 2 },
  { q: '"Heykel"de "in situ" kavramı ne anlama gelir?', a: ['Galeri sanatı', 'Eserin bulunacağı mekân gözetilerek o mekân için tasarlanmış, yerle bütünleşik eser', 'Taşınan heykel', 'Dijital heykel'], c: 1, e: 'In situ; Latince "yerinde" anlamına gelir. Sanat bağlamında; eserin belirli bir mekân için özel olarak tasarlandığı ve başka yere taşındığında özgünlüğünü yitireceği site-specific (mekâna özgü) eseri tanımlar.', d: 2 },
  { q: '"Türk geleneksel el sanatları" UNESCO\'da nasıl yer almaktadır?', a: ['Hiç kayıtlı değil', 'Ebru, Türk kahvesi geleneği, Mevlevi semahı, Karagöz ve çeşitli el sanatları UNESCO listelerinde', 'Yalnızca mimari', 'Yalnızca müzik'], c: 1, e: 'Türkiye\'nin UNESCO Somut Olmayan Kültürel Miras listelerindeki unsurlar arasında Karagöz, Mevlevi semahı, ebru, Türk kahvesi geleneği ve geleneksel Nevruz kutlamaları yer almaktadır.', d: 2 },
  { q: '"Türk tiyatrosunun" geleneksel komedi biçimi nedir?', a: ['Opera', 'Karagöz ve Hacivat ile Ortaoyunu', 'Komedi deli oya', 'Modern tiyatro'], c: 1, e: 'Karagöz ve Hacivat (gölge oyunu) ile Ortaoyunu; Türk toplumsal komedisinin geleneksel biçimleridir. Her ikisi de farklı toplum kesimlerini temsil eden karakterlerle toplumsal eleştiri içerir.', d: 1 },
  { q: '"Türk sanatında Osman Hamdi Bey"in önemi nedir?', a: ['Mimar', 'Batılı anlamda ilk profesyonel Türk ressamı; aynı zamanda arkeolog ve müzeci', 'Heykeltraş', 'Hat sanatçısı'], c: 1, e: 'Osman Hamdi Bey; 19. yüzyılda Paris\'te eğitim aldı, oryantalist eleştiri doğrultusunda önemli tuvaller üretti ve İstanbul Arkeoloji Müzesi\'ni kurdu. Türk sanat tarihinin mihenk taşlarından biridir.', d: 2 },
  { q: '"Türk hat sanatında" hangi yazı türleri kullanılır?', a: ['Yalnızca Arapça harfler', 'Sülüs, Nesih, Talik, Divani ve Rik\'a gibi çeşitli hat türleri', 'Yalnızca Türkçe', 'Yalnızca Kur\'an ayetleri'], c: 1, e: 'Hat sanatında kullanılan başlıca türler: Sülüs (kitabeler için), Nesih (Kur\'an yazımı), Talik (Farsça şiir), Divani (resmi belgeler), Rik\'a (günlük yazışma) ve Celi (büyük yazı) biçimlerini kapsar.', d: 2 },
  { q: '"Türk "meddah" sanatı" nedir?', a: ['Halk dansı', 'Tek kişilik performansla çeşitli karakterleri canlandıran Osmanlı-Türk anlatı sanatı', 'Halk müziği', 'Kukla tiyatrosu'], c: 1, e: 'Meddah; tek başına sahnede farklı sesleri ve karakterleri canlandırarak dini-ahlaki ya da komik hikayeler anlatan Türk-Osmanlı performans sanatçısıdır. UNESCO listesindedir.', d: 2 },
  { q: '"Türk çini sanatının" en parlak dönemi hangi yüzyıldır?', a: ['13. yüzyıl', '15-17. yüzyıl (Osmanlı altın çağı)', '19. yüzyıl', '20. yüzyıl'], c: 1, e: '15-17. yüzyıllar, özellikle Kanuni Sultan Süleyman dönemi; İznik ve Kütahya çiniciliğinin en yüksek kaliteye ulaştığı, kobalt mavisi ve mercan kırmızısı desenlerinin dünyanın en değerli seramikleri arasına girdiği dönemdir.', d: 2 },
  { q: '"Leonardo da Vinci\'nin" Mona Lisa\'sının gizemi nedir?', a: ['Sahtedir', 'Özgün kimliği tartışmalı; belirsiz gülümseme ve sfumato tekniği onu eşsiz kılar', 'Yarım kalmış', 'Manzara resmi'], c: 1, e: 'Mona Lisa\'nın modeli büyük olasılıkla Lisa Gherardini\'dir. Sfumato (hava perspektifi) tekniğiyle oluşturulan belirsiz gülümseme ve arka planın izleyiciye göre değişen derinliği, tabloyu tarihinin en çok incelenen eseri yapmıştır.', d: 2 },
  { q: '"Venüs\'ün Doğuşu" tablosunu hangi sanatçı yapmıştır?', a: ['Raphael', 'Michelangelo', 'Leonardo da Vinci', 'Sandro Botticelli'], c: 3, e: 'Sandro Botticelli\'nin yaklaşık 1484-1486 yıllarında yaptığı "Venüs\'ün Doğuşu"; denizden yükselen Venüs tanrıçasını tasvir eder. Floransa Uffizi Galerisi\'nde sergilenmektedir.' },
  { q: '"Guernica" adlı ünlü tablonun sanatçısı ve konusu nedir?', a: ['Salvador Dali – Sürrealizm', 'Pablo Picasso – İspanya İç Savaşı\'nda Guernica kasabasının bombalanması', 'Joan Miró – Savaş karşıtı soyut', 'Marcel Duchamp – Dadaizm'], c: 1, e: 'Picasso\'nun 1937\'de yaptığı dev Guernica (349×776 cm); Nazilerin İspanya İç Savaşı\'nda bombaladığı Bask kasabasının acısını siyah-gri-beyaz savaş imgesiyle aktarır.' },
  { q: '"Vincent van Gogh" hangi ünlü eseriyle tanınır?', a: ['Mona Lisa', 'Kız ile İnci Küpe', 'Yıldızlı Gece', 'Son Akşam Yemeği'], c: 2, e: 'Van Gogh\'un 1889\'da Fransız Saint-Rémy-de-Provence\'daki akıl hastanesinde yarattığı "Yıldızlı Gece"; gece gökyüzünün dinamik, fırça darbeli ifadesiyle sanat tarihinin en tanınan eserlerinden biridir.' },
  { q: '"Yıldızlı Gece" şu an hangi müzede sergilenmektedir?', a: ['Louvre – Paris', 'MoMA – New York', 'Uffizi – Floransa', 'Rijksmuseum – Amsterdam'], c: 1, e: 'Van Gogh\'un "Yıldızlı Gece"si; New York\'taki Museum of Modern Art (MoMA)\'da kalıcı koleksiyon içinde sergilenmektedir.' },
  { q: '"Edvard Munch\'un" "Çığlık" adlı tablosunun genel ifadesi nedir?', a: ['Sevinç ve umut', 'Varoluşsal kaygı ve insanın doğa karşısındaki çaresizliği', 'Dini huzur', 'Aşk ve romantizm'], c: 1, e: 'Munch\'un 1893 tarihli "Çığlık"ı; kıvılan gökyüzü altında ıssız bir figürün ağzını açık bekleyişiyle modern insanın varoluşsal bunalımını simgeler. Ekspresyonizmin ikonik başyapıtıdır.' },
  { q: '"Empresyonizm" ile "Ekspresyonizm" arasındaki fark nedir?', a: ['İkisi aynı', 'Empresyonizm ışık-anı etkisini; Ekspresyonizm duygusal iç dünyayı ve kaygıyı bozulmuş biçimlerle dışa vurur', 'Ekspresyonizm daha eski', 'Yalnızca renk farkı'], c: 1, e: 'Empresyonizm; dış gözlem ve anlık atmosferi kaydeder. Ekspresyonizm ise dış gerçekliği bükarak sanatçının iç dünyasını—öfke, korku, kaygı—aktarır. Van Gogh geçiş figürü; Munch ekspresyonizmin öncüsüdür.' },
  { q: '"Salvador Dali" hangi akımın önde gelen temsilcisidir?', a: ['Dadaizm', 'Pop Art', 'Sürrealizm', 'Fütürizm'], c: 2, e: 'Salvador Dali; eriyip akan saatler, fil bacakları gibi bilinçdışı ve rüya imgelerini gerçekçi teknikle sahneleyen Sürrealizm akımının en tanınan temsilcilerindendir.' },
  { q: '"Henri Matisse" hangi sanatsal yaklaşımıyla öne çıktı?', a: ['Gerçekçilik', 'Fovizm; parlak, saf renkler ve cesur fırça darbeleriyle gerçekçi biçimden kopuş', 'Kübizm', 'Sürrealizm'], c: 1, e: 'Matisse; 1905\'te ortaya çıkan Fovizm akımının lideri olarak; rengi duygunun doğrudan dili olarak kullanan, doğal olmayan parlak renkleriyle tanınan Fransız sanatçıdır.' },
  { q: '"Caravaggio" resim tarihinde neyle devrim yarattı?', a: ['Perspektifi keşfetti', 'Chiaroscuro tekniğini en aşırı biçimiyle uygulayarak dramatik ışık-karanlık karşıtlığını yüceltti', 'İlk portre yaptı', 'Fresk tekniğini geliştirdi'], c: 1, e: 'Caravaggio; yoğun karanlık zemin üzerinde tek bir ışık kaynağından gelen dramatik aydınlatmayla figürler sundu. Bu "tenebrism" yaklaşımı Barok dönemin en etkili üslubu haline geldi.' },
  { q: '"Rembrandt" hangi teknikle portreleşmeye yeni bir boyut kazandırdı?', a: ['Fresk', 'Çok katmanlı yağlı boya ve ışık-gölge ustası olarak psikolojik derinliği aktarması', 'Tempera', 'Sulu boya'], c: 1, e: 'Rembrandt van Rijn; 350\'den fazla portreyi ışık ve karanlığın ustaca kullanımıyla resmetti. Kendi portreleri (otoportreler) psikolojik içgözlem sergilediği için sanat tarihinin en çarpıcı örnekleri arasındadır.' },
  { q: '"Rönesans\'ta perspektif" kimler tarafından sistematize edildi?', a: ['Michelangelo ve Raphael', 'Filippo Brunelleschi ve Leon Battista Alberti', 'Donatello ve Botticelli', 'Jan van Eyck ve Dürer'], c: 1, e: 'Erken 15. yüzyılda Brunelleschi deneysel olarak perspektifi kanıtladı; Alberti ise "Della Pittura" (1435) adlı eserinde geometrik tek noktalı perspektif kurallarını yazılı olarak sistematize etti.' },
  { q: '"Louvre Müzesi" kaç esere ev sahipliği yapmaktadır?', a: ['10.000', '35.000', '380.000', '1 milyon'], c: 2, e: 'Louvre; yaklaşık 380.000 eseri koleksiyonunda barındırır ve bunların yaklaşık 35.000\'i kalıcı sergi salonlarında görülebilir. Her yıl 7-9 milyon ziyaretçiyle dünyanın en çok ziyaret edilen müzesidir.' },
  { q: '"Sanat akımı" nasıl oluşur?', a: ['Devlet emriyle', 'Benzer estetik anlayış, teknik ve kültürel bağlamı paylaşan sanatçıların ortak üretimiyle dönemsel bir harekete dönüşmesi', 'Rastlantıyla', 'Yalnızca Avrupa\'da'], c: 1, e: 'Sanat akımları; belirli bir dönem ve coğrafyada ortak teknik, konu ve felsefi anlayışı paylaşan sanatçıların birbirleriyle etkileşimiyle oluşur. Manifestolar, galerilerde toplu sergiler ve eleştirmenler bu akımları tanımlar.' },
  { q: '"Yağlı boya" tekniği ne zaman yaygınlaştı?', a: ['Antik Çağ\'da', '15. yüzyılda Flaman ressamlarıyla (Jan van Eyck öncülük etti)', '18. yüzyılda', 'Rönesans\'ın sonunda'], c: 1, e: 'Yağlı boyayı sistematize eden Jan van Eyck (15. yüzyıl Flaman resmi) olarak kabul edilir. Pigmentlerin zeytinyağı veya keten tohumu yağıyla karıştırılması; kuruması yavaş olduğundan çok katmanlı çalışmaya olanak tanıdı.' },
  { q: '"Akvarel" (suluboya) tekniğinin özelliği nedir?', a: ['Opak ve kalın tabaka', 'Su bazlı, şeffaf katmanlar; üstten gelen ışığın beyaz kağıttan yansımasıyla parlaklık elde edilir', 'Pastel boya', 'Fresk tekniği'], c: 1, e: 'Akvarel; pigmentlerin suyla inceltilerek uygulandığı ve alt katmanların alttan görünebildiği şeffaf bir boya tekniğidir. Kağıdın beyazlığı ışık kaynağı işlevi görür; kağıt önceden ıslatılabilir.' },
  { q: '"Fotoğraf sanatı" geleneksel resim sanatını nasıl etkiledi?', a: ['Hiç etkilemedi', 'Gerçekçi temsil ihtiyacını ortadan kaldırarak ressamları duygu, soyutlama ve kavram arayışına yöneltti', 'Resmi bitirdi', 'Yalnızca portre'], c: 1, e: '19. yüzyılda fotoğrafın icadı; ressamları gerçekçi belgeleme görevinden kurtararak Empresyonizm, Sembolizm ve Soyut sanat gibi yeni yönlere açtı. Sanat; "ne" değil "nasıl" ve "neden" sorusu üzerinde yoğunlaştı.' },
  { q: '"Heykel malzemeleri" açısından Antik Yunan ile Rönesans\'ı nasıl karşılaştırırız?', a: ['İkisi de yalnızca bronz', 'Antik Yunan; mermer ve bronz. Rönesans; mermer büyük olduğu kadar döküm bronzu da (Donatello, Ghiberti) geliştirdi', 'Yalnızca taş', 'İkisi de ahşap'], c: 1, e: 'Antik Yunan\'da mermer ve bronz dökümü yaygındı. Rönesans heykelcileri; Michelangelo\'nun mermer ustalığı ve Donatello ile Ghiberti\'nin bronz tekniğiyle her ikisinde de zirveye ulaştı.' },
  { q: '"Türk resim sanatının" erken dönem figürü Osman Hamdi Bey\'in "Kaplumbağa Terbiyecisi" tablosu neden önemlidir?', a: ['İlk Türk tablosu', 'Oryantalist resmin Doğu\'nun kendi perspektifinden içeride yeniden yorumlanması olarak ters oryantalizm tartışması açar', 'Teknik yeniliği', 'Dini konu'], c: 1, e: '"Kaplumbağa Terbiyecisi" (1906); Osman Hamdi Bey\'in Batılı oryantalist resimlerin "egzotik Doğu" kurgusu yerine kendi gerçeğinden bakan bir Osmanlı-Türk perspektifi sunması olarak yorumlanır.' },
  { q: '"Müze"nin kökeni ve tarihsel dönüşümü nasıldır?', a: ['19. yüzyılda başladı', 'Antik Yunan Mouseion\'undan (bilgi evi) Avrupa\'da 18-19. yy\'daki kamusal erişimli ulusal müzelere dönüşüm', 'Yalnızca Avrupa\'da', 'Ortaçağ kiliselerinden'], c: 1, e: 'Mouseion; Antik Alexandria\'da bilgin topluluklarına ayrılmış bir bilgi kurumuydu. Modern anlamdaki müze; 18. yüzyılda Louvre ve British Museum gibi kraliyet koleksiyonlarının halka açılmasıyla doğdu.' },
  { q: '"Sanat eleştirisinin" işlevi nedir?', a: ['Sanatçıyı yargılamak', 'Eserleri tarihsel, estetik ve kültürel bağlamda yorumlayarak izleyicinin anlama kapasitesini ve diyaloğu derinleştirmek', 'Yalnızca satış fiyatını belirlemek', 'Yalnızca müze görevi'], c: 1, e: 'Sanat eleştirisi; eserleri teknik, bağlamsal, anlamsal ve estetik boyutlarda analiz ederek hem izleyicilere rehberlik eder hem de sanat tarihine diyalektik katkı sunar.' },
  { q: '"Natürmort" resminin konusu nedir?', a: ['Manzara', 'Cansız nesneler — meyve, çiçek, kap kacak, oyun kağıtları — ın düzenlemesi', 'İnsan figürü', 'Tarih sahneleri'], c: 1, e: 'Natürmort (still life); cansız nesnelerin özenle düzenlendiği, ışık-gölge ve doku oyununu sergileyen resim türüdür. Hollanda Altın Çağı ressamları bu türde zirveye ulaştı.' },
  { q: '"Pastel" tekniği ile "yağlı boya" arasındaki temel fark nedir?', a: ['Renk paleti farklı', 'Pastel; bağlayıcı içermeyen pigment çubuklar — hemen kuruyan, kadifeli mat doku. Yağlı boya; daha yavaş kuruyan, parlaklık sağlayan', 'Yalnızca kağıt üzerine', 'İkisi aynı'], c: 1, e: 'Pastel çubuklar; saf pigment ve minimum bağlayıcıdan oluşur, hemen kurur ve kadifemsi mat bir yüzey sağlar. Yağlı boya ise yağ ile karışık olduğundan yavaş kurur ve parlak, katmanlı çalışmaya olanak tanır.' },
  { q: '"Tapınak sanatı" (religious art) ile "laik sanat" farkı ne zaman belirginleşti?', a: ['Antik Çağ\'da', 'Rönesans ile birlikte; mitoloji, tarih ve birey portresi dini konularla yarışmaya başladı', '18. yüzyılda', 'Modernizmle'], c: 1, e: 'Orta Çağ boyunca sanat büyük ölçüde kilise hizmetindeydi. Rönesans ile birlikte bireysel portrecilik, mitolojik konu ve laikleşen himaye (Medici gibi banker aileler) dini olmayan konuları sahnelemeye açtı.' },
  { q: '"Kavramsal sanat" neden 1960\'larda ortaya çıktı?', a: ['Teknik yetersizlik', 'Sanatın özünün nesne değil fikir olduğu anlayışıyla; geleneksel sanat piyasasına, estetiğe ve meta kavramına karşı çıkış', 'Malzeme kıtlığı', 'Fotoğrafın rekabeti'], c: 1, e: 'Kavramsal sanat; Sol LeWitt ve Marcel Duchamp\'ın mirasıyla 1960\'larda "sanat bir fikir olabilir; nesne ikincil" yaklaşımını benimsedi. Bu hareket sanat eserinin el emeği ya da estetik kaygıdan bağımsızlığını savundu.' },
  { q: '"Türk tasavvuf şiirinin" en büyük temsilcisi kimdir?', a: ['Karacaoğlan', 'Yunus Emre', 'Pir Sultan Abdal', 'Köroğlu'], c: 1, e: 'Yunus Emre; 13-14. yüzyıllarda yaşamış ve Türkçe tasavvuf şiirinin kurucusu sayılan şairdir. Hümanizan, hoşgörü ve sevgi temalı şiirleriyle hem divan hem de halk edebiyatına köprü oldu.' },
  { q: '"Edebiyatta anti-kahraman" kimdir?', a: ['Kötü adam', 'Geleneksel kahraman niteliklerinden yoksun; topluma uyumsuz, kusurlu ve ahlaki gri alanda yaşayan ana karakter', 'Yardımcı karakter', 'Kötü yazılmış kahraman'], c: 1, e: 'Anti-kahraman; klasik erdem, cesaret ve idealizm yerine sıradan, kusurlu, şüpheci ve bazen ahlaki açıdan tartışmalı özelliklere sahip protagonisttir. Hamlet, Holden Caulfield ve Don Quijote bu kategorinin örnekleridir.' },
  { q: '"Müzikal leitmotif" ne demektir?', a: ['Melodi tekrarı', 'Richard Wagner\'ın geliştirdiği, bir karakter veya fikri temsil eden tekrar eden müzikal motif', 'Koro bölümü', 'Müzik terimi'], c: 1, e: 'Leitmotif; özellikle Wagner\'ın operalarında belirli bir karakter, duygu veya durumu simgeleyen kısa melodik/armonik motiftir. Film müziğine taşınan bu teknik; John Williams\'ın Star Wars temalarında yaygın kullanılır.' },
  { q: '"Sonat formu" klasik müzikte ne anlama gelir?', a: ['Tek bölüm', 'Sergileşme, gelişim ve yeniden sergileşme bölümlerinden oluşan ve tematik materyalin işlendiği form', 'Yalnızca piyano', 'Koro formu'], c: 1, e: 'Sonat-alegro formu; ana temayı sunan sergi, temaları dönüştüren gelişim ve temaları yeniden sunan yeniden sergi bölümlerinden oluşan 18-19. yüzyıl klasik müziğinin temel yapısal çerçevesidir.' },
  { q: '"Türk sinema tarihinde" hangi film yönetmeni uluslararası arenada en çok tanınır?', a: ['Atıf Yılmaz', 'Nuri Bilge Ceylan', 'Yılmaz Güney', 'Halit Refiğ'], c: 1, e: 'Nuri Bilge Ceylan; Cannes\'da Altın Palmiye (2014, "Kış Uykusu") dahil birçok ödül kazanarak Türk sinemasını uluslararası sanat sinemasının en üst kademine taşımıştır.' },
  { q: '"Yılmaz Güney" hangi filmiyle Altın Palmiye kazandı?', a: ['Umut', 'Sürü', 'Yol', 'Duvar'], c: 2, e: '"Yol" (1982); hapishaneden geçici izinle çıkan beş mahkumun hikayesini anlatan ve Türk sansürü nedeniyle Güney\'in hapisten yönettiği/yönetmen koltuğunu Şerif Gören\'e bıraktığı filmdir. Cannes\'da Altın Palmiye kazandı.' },
  { q: '"Mimarlıkta Brütalizm" akımının özelliği nedir?', a: ['Ahşap ve cam', 'Ham beton yüzeyler, işlevsel biçimler ve yapı iskeletinin görünür bırakılması', 'Tarihi süsleme', 'Art Nouveau'], c: 1, e: 'Brütalizm; 1950-70\'lerde yaygınlaşan ve ham (brut) beton yüzeyleri, masif biçimleri ve yapı sistemlerini estetik öge olarak kullanan mimari akımdır. Le Corbusier ve Paul Rudolph önemli temsilcileridir.' },
  { q: '"Türk geleneksel müziğinde makam" sistemi neden önemlidir?', a: ['Yalnızca melodi', 'Her makam; dizi, karakteristik ifade ve duygusal rengiyle Batı majör-minör sisteminden farklı mikrotonal yapı oluşturur', 'Yalnızca ritim', 'İslam kuralı'], c: 1, e: 'Makam; Türk ve Arap müziğinde belirli aralık yapısı, melodik formül ve ifade niteliğiyle tanımlanan tonal çerçevedir. Batı müziğindeki majör-minör sisteminden farklı olarak mikrotonal aralıklar içerir.' },
  { q: '"Figür resmi"nde "chiaroscuro" ne anlama gelir?', a: ['Perspektif', 'Işık ve karanlık arasındaki güçlü karşıtlık; hacim ve derinlik yanılsaması yaratır', 'Renk karışımı', 'Fresk tekniği'], c: 1, e: 'Chiaroscuro (İtalyanca: açık-koyu); figüre üç boyutlu hacim ve dramatizm kazandırmak için güçlü ışık-gölge karşıtlığının ustaca kullanıldığı teknik. Leonardo, Caravaggio ve Rembrandt bu tekniğin ustaları.' },
  { q: '"Türk edebiyatında Tanzimat dönemi" hangi yenilikleri getirdi?', a: ['Yalnızca dil değişikliği', 'Roman, gazete, tiyatro ve Batılı edebi formların Türk edebiyatına girmesi; bireysel ve toplumsal temaların öne çıkması', 'Yalnızca şiir', 'Yalnızca çeviri'], c: 1, e: 'Tanzimat (1839-1876) dönemi edebiyatı; Batılı edebi türleri (roman, öykü, gazete, oyun) benimsedi. Namık Kemal ve Şinasi öncülüğünde bireycilik, vatanseverlik ve sosyal eleştiri öne çıktı.' },
  { q: '"Türk hat sanatında" en önemli merkez hangi şehirdir?', a: ['Ankara', 'İzmir', 'İstanbul', 'Konya'], c: 2, e: 'İstanbul; Osmanlı döneminden itibaren hat sanatının en önemli merkezi olmuştur. Devrin büyük hattatları sarayda ve tekkede yetişerek bu geleneği sürdürdü.' },
  { q: '"Müzik eşlik (armoni)" neyi tanımlar?', a: ['Tek ses', 'Aynı anda çalınan farklı seslerin oluşturduğu ses dokusu ve bu seslerin birbirleriyle ilişkisinin bilimi', 'Ritim yapısı', 'Enstrüman seçimi'], c: 1, e: 'Armoni; iki veya daha fazla sesi eşzamanlı duyurarak melodi üzerinde oluşan ton dokusu ve bu tonlar arasındaki kuralları inceler. Akord teorisi, konsonans-disonans ve kadans armoninin temel konularıdır.' },
  { q: '"Türk geleneksel el sanatlarından kemençe" nerede yaygındır?', a: ['Ege', 'Güneydoğu', 'Karadeniz', 'Batı Anadolu'], c: 2, e: 'Kemençe; küçük boyutlu yaylı bir çalgıdır ve Karadeniz bölgesine özgü halk müziğinin vazgeçilmez enstrümanıdır. Trabzon ve Rize çevresinde özellikle horon danslarına eşlik eder.' },
  { q: '"Türk filminde" "Yol" (1982) ile "Kış Uykusu" (2014) arasındaki süreçte Cannes\'dan altın olan başka film var mı?', a: ['Evet, birçok', 'Hayır; Türkiye bu iki filmle Altın Palmiye aldı', 'Evet, "Bir Zamanlar Anadolu\'da"', 'Evet, "Masumiyet"'], c: 1, e: 'Türkiye, Cannes Altın Palmiyesi\'ni "Yol" (1982) ve "Kış Uykusu" (2014) ile iki kez kazandı. "Bir Zamanlar Anadolu\'da" büyük ödülü (Jury Grand Prix) 2011\'de aldı.' },
  { q: '"Grafik tasarım" ile "saf sanat" (fine art) arasındaki fark nedir?', a: ['Aynı şey', 'Grafik tasarım; işlevsel iletişim amacı güder. Saf sanat; estetik deneyim veya ifade için vardır', 'Yalnızca malzeme farkı', 'Grafik daha değerli'], c: 1, e: 'Grafik tasarım; logo, poster, ambalaj gibi belirli iletişim sorunlarını çözmek için biçim ve anlam birleştiren uygulamalı alandır. Saf sanat; zorunlu işlevsellik kaygısı taşımaz, duygu-fikir ifadesiyle kendi başına bir deneyim sunar.' },
  { q: '"Sanat galerisi" ile "müze" arasındaki fark nedir?', a: ['Aynı şey', 'Müze; kalıcı koleksiyon korur. Galeri; genellikle geçici sergi ve satış platformu', 'Galeri devlet kurumu', 'Müze yalnızca tarihi'], c: 1, e: 'Müzeler; kalıcı koruma, araştırma ve uzun vadeli sergileme göreviyle çalışır. Galeriler ise çoğunlukla ticari veya bağımsız mekânlar olarak sanatçıların eserlerini sergileyip satışa sunar.' },
  { q: '"Türk sanatçı Fahrelnissa Zeid" hangi akımla özdeşleşir?', a: ['Ekspresyonizm', 'Soyut dışavurumculuk; karmaşık geometrik örüntüler ve canlı renk patlama', 'Empresyonizm', 'Kübizm'], c: 1, e: 'Fahrelnissa Zeid; dev boyutlu, karmaşık geometrik soyut resimleri ve canlı renkleriyle Avrupa soyut sanatına önemli katkı sunan, Paris\'te faaliyet gösteren Türk-Ürdün prensesi ve ressamıdır.' },
  { q: '"Sanat piyasası"nda "provenance" ne anlama gelir?', a: ['Sanat eleştirisi', 'Bir eserin el değiştirme geçmişi; sahiplik zinciri ve köken belgesi', 'Eserin değeri', 'Teknik analiz'], c: 1, e: 'Provenance (köken belgesi); bir sanat eserinin tarihi sahiplik zincirini belgeleyen kayıtlardır. Müzayede evleri ve müzeler için kritiktir; sahtecilik tespiti, yağmalanmış eser iadesi ve değer belirlenmesinde temel referans.' },
  // --- BÖLÜM 3: Ek sorular (242 → 500) ---
  { q: '"Rönesans"ın doğduğu şehir neresidir?', a: ['Venedik', 'Roma', 'Floransa', 'Milano'], c: 2, e: 'Floransa; Medici ailesinin himayesiyle Rönesans\'ın merkezi oldu. Botticelli, Leonardo, Michelangelo ve Donatello gibi ustalar bu şehirde yetişip eserler verdi.' },
  { q: '"Sfumato" tekniği nedir?', a: ['Fresk boyama', 'Konturların belirsiz, dumanlı geçişlerle yumuşatıldığı ve derinlik/atmosfer yaratan yağlı boya tekniği', 'Rölyef kazıma', 'Mozaik döşeme'], c: 1, e: 'Sfumato; Leonardo da Vinci\'nin geliştirip mükemmelleştirdiği, figür kenarlarının keskin yerine yumuşak duman gibi belirsizleştirildiği tekniktir. Mona Lisa\'nın gizemli ifadesi bu teknikten kaynaklanır.' },
  { q: '"Empresyonizm"in doğduğu yıl ve olay nedir?', a: ['1848, Fransız Devrimi', '1874, Paris\'te reddetilmiş sanatçıların açtığı bağımsız sergi', '1900, Dünya Fuarı', '1863, Salon des Refusés'], c: 1, e: '1874\'te Monet, Renoir, Degas ve arkadaşları Fransız akademisinin reddettikleri eserlerini Paris\'te bağımsız sergilediler. Eleştirmen Louis Leroy "Empresyonizm" adını alaylı biçimde koydu; ad kalıcı oldu.' },
  { q: '"Claude Monet"in en bilinen serisi hangisidir?', a: ['Güneşin Doğuşu', 'Nilüferler (Water Lilies)', 'Saman Balyaları', 'Katedraller'], c: 1, e: 'Monet; ömrünün son 30 yılında Giverny\'deki bahçesinin göletindeki nilüferleri farklı ışık koşullarında 250\'den fazla tabloda resmetti. Bu seri empresyonizmin zirvesi sayılır.' },
  { q: '"Pierre-Auguste Renoir"in üslubu nasıl tanımlanır?', a: ['Karanlık ve dramatik', 'Canlı renkler, parlak ışık ve sosyal yaşamı neşeyle aktaran figüratif empresyonizm', 'Geometrik soyut', 'Gotik karanlık'], c: 1, e: 'Renoir; dans etkinlikleri, piknikler ve sosyal buluşmaları canlandıran neşeli, sıcak renk paletli empresyonist tabloları ile tanınır. "Moulin de la Galette\'te Dans" en ünlü eserlerinden biridir.' },
  { q: '"Paul Cézanne" modern sanatın neden "babası" olarak anılır?', a: ['Empresyonizm kurdu', 'Geometrik biçimleri parçalayarak hem Kübizm\'e hem soyut sanata zemin hazırladı', 'Fovizm kurdu', 'Gerçekçiliği yeniden canlandırdı'], c: 1, e: 'Cézanne; elmaları, dağları ve nesneleri silindir, küre ve koniye indirgeyen analitik yaklaşımıyla Picasso ve Braque\'ın Kübizm\'ini, sonrasında soyut sanatı doğrudan besledi.' },
  { q: '"Paul Gauguin" neden Fransız Polinezyası\'na gitti?', a: ['Sürgün edildi', 'Avrupa medeniyetinden kaçarak ilkel, saf yaşam ve egzotik renk arayan ruhsal arayış', 'Araştırma gezisi', 'Ticaret'], c: 1, e: 'Gauguin; Batı medeniyetinin yozlaşmasından kaçarak Tahiti\'ye yerleşti. Burada yerlilerin yaşamını, cesur renk blokları ve düz yüzeylerle resme aktardı; Post-Empresyonizm\'in önemli kolu Synthetism\'i geliştirdi.' },
  { q: '"Georges Seurat" hangi tekniği geliştirdi?', a: ['Kübizm', 'Pointilizm; saf renk noktalarının yan yana konulduğunda gözde karışarak zengin renk oluşturduğu teknik', 'Fovizm', 'Empresyonizm'], c: 1, e: 'Seurat\'nın Puan ticilizm (Pointilism) ya da Divisionizm\'i; bilimsel renk teorisine dayanan, milyonlarca küçük saf renk noktasının izleyicinin gözünde optik olarak karışmasını sağlayan sistematik bir yöntemdir.' },
  { q: '"Wassily Kandinsky" soyut sanatın gelişiminde neden önemlidir?', a: ['Kübizmi kurdu', 'Figüratif temsili tamamen terk ederek renk ve biçimi bağımsız ifade aracı olarak kullanan ilk soyut eserleri üretti', 'Empresyonizm kurdu', 'Pop Art öncüsü'], c: 1, e: 'Kandinsky; 1910\'da figüratif unsurdan tamamen arınmış ilk soyut suluboyayı yarattığı kabul edilir. Müzik ile rengi ilişkilendirerek Bauhaus\'ta teorik temeller oluşturdu.' },
  { q: '"Piet Mondrian" hangi görsel dil ile tanınır?', a: ['Gerçekçi portreciler', 'Yatay-dikey siyah çizgiler ve kırmızı-mavi-sarı-beyaz renk blokları; De Stijl akımı', 'Sürrealist imgeler', 'Barok süslemeler'], c: 1, e: 'Mondrian; De Stijl (Yeni Plastisizm) akımının öncüsü olarak sanatı yatay-dikey çizgiler ve üç ana renge indirgeyen radikalist kompozisyonlar üretiyor. Bu görsel dil grafik tasarım ve mimarlığı derinden etkiledi.' },
  { q: '"Mark Rothko"nun tuvallerinde ne hissettirmek istedi?', a: ['Çevre güzelliği', 'Büyük renk alanlarıyla izleyicide derin duygusal ve ruhani deneyim — korku, haz, trajedi', 'Matematiksel düzen', 'Hiciv'], c: 1, e: 'Rothko; dev boyutlu, titreşen renk alanlarının izleyiciyi sarmasıyla hüzün, neşe ve trajedi gibi derin duyguları tetiklemesini amaçladı. "Renk Alanı Resmi"nin en önemli temsilcisi sayılır.' },
  { q: '"Jackson Pollock"un "damlatma" (drip painting) tekniği nasıl çalışır?', a: ['Fırçayla boyama', 'Tuvali yere sererek üzerine boya damlatıp saçarak ve dökerek oluşturulan eylem resmi (action painting)', 'Baskı tekniği', 'Kolaj'], c: 1, e: 'Pollock; tuvali yere koyarak boya kutularından boya damlatır, döker ve saçardı. Bilinçdışı ve içgüdüsel hareketi esas alan bu "action painting" yaklaşımı Soyut Dışavurumculuğun simgesi oldu.' },
  { q: '"Jean-Michel Basquiat" sanat dünyasında neyi temsil eder?', a: ['Empresyonizm temsilcisi', 'Sokak sanatından galerilere yükselen, ırk, kimlik ve sosyal eşitsizliği acımasız bir enerjide ele alan Neo-Ekspresyonist', 'Minimalizm', 'Sürrealizm'], c: 1, e: 'Basquiat; 1980\'lerin New York sokaklarından çıkıp kısa sürede uluslararası sanat piyasasına giren, Afrikalı-Amerikalı kimliği ve sosyal eleştiriyi çarpıcı bir görsel dille aktaran fenomen sanatçıydı.' },
  { q: '"Frida Kahlo"nun sanatının temel temaları nelerdir?', a: ['Manzara ve tabiat', 'Fiziksel acı, kimlik, Meksika kültürü ve kadın deneyimi; çoğunlukla otoportre', 'Soyutlama', 'Sürrealist ütopya'], c: 1, e: 'Kahlo; 1925\'teki ağır trafik kazasından kaynaklanan fiziksel acısını, Meksika kültürel kimliğini ve kadın bedeninin deneyimini 55 otoportre başta olmak üzere yoğun sembolik dille tuvale aktardı.' },
  { q: '"Diego Rivera" hangi sanat biçimiyle dünyaca tanınır?', a: ['Yağlı boya tablo', 'Dev boyutlu duvar freskleri; Meksika tarihi ve devrimci sınıf bilincini aktaran kamusal sanat', 'Heykel', 'Fotoğrafçılık'], c: 1, e: 'Rivera; Meksika\'nın ulusal kültürünü, tarihini ve işçi sınıfı mücadelesini anlatan dev duvar freskleriyle (murales) Meksika muralizminin en önemli temsilcisi oldu. Rockefeller Center fresği tartışmalı kaldı.' },
  { q: '"Andy Warhol"un "Factory"si neydi?', a: ['Fabrika sahibi', 'New York\'ta sanat, müzik ve sinema üretiminin iç içe geçtiği, sanatçı ve ünlülerin buluştuğu atölye-sosyal mekân', 'Film stüdyosu', 'Galeri'], c: 1, e: 'The Factory; 1960\'larda Warhol\'un New York\'taki gümüş folyolu atölyesiydi. Baskı üretimi, avant-garde film çekimi, müzik pratiği ve sanat çevrelerinin sosyal buluşma noktası olarak Pop Art\'ın kalbi oldu.' },
  { q: '"Roy Lichtenstein" hangi görsel dilden ilham aldı?', a: ['Empresyonizm', 'Çizgi roman (comic strip) estetiği; ben-day noktaları, kalın konturlar ve renkli konuşma balonları', 'Sürrealizm', 'Ekspresyonizm'], c: 1, e: 'Lichtenstein; çizgi romanların mekanik baskı tekniğini (ben-day dots) ve dramatik anlatısını birebir büyütüp tuvaline taşıdı. Bu yaklaşım Pop Art\'ın popüler kültürü yüksek sanata entegre etme stratejisinin en net örneğidir.' },
  { q: '"Marcel Duchamp"ın "Çeşme" (Fountain) eseri neden önemlidir?', a: ['Güzel bir heykel', 'Sıradan bir pisuar imzalanarak sergilenmeye sunuldu; "sanat nedir ve kim belirler" sorusunu kökten sorguladı', 'Barok dönem eseri', 'Empresyonist çalışma'], c: 1, e: 'Duchamp\'ın 1917\'de "R. Mutt" imzasıyla sergilemeye sunduğu fabrika pisuarı, sanatın tanımını ve sanatçının rolünü tarihin en radikal biçimde sorgulayan "ready-made" eserdir.' },
  { q: '"Banksy" kimdir ve neden önemlidir?', a: ['Bilinen sanatçı', 'Kimliği bilinmeyen İngiliz sokak sanatçısı; siyasi eleştiri ve hicvi kamusal mekânlarda şablonlu grafitiyle aktarır', 'Fransız ressamı', 'Müzayede ustası'], c: 1, e: 'Banksy; anonimliğini koruyarak dünya şehirlerinde siyasi ve sosyal eleştiri içerikli şablonlu graffiti çalışmaları üreten ve eserleri açık artırmalarda milyonlarca pound eden gizemli İngiliz sokak sanatçısıdır.' },
  { q: '"Street art" ile "vandalizm" arasında nasıl bir sınır çizilir?', a: ['İkisi aynı', 'İzin, estetik amaç ve kamusal diyalog; izinsiz yapılan yasal suçtur ancak sanatsal değer tartışmayı besler', 'Sadece boyaya göre', 'Sadece boyuta göre'], c: 1, e: 'Sokak sanatı tartışması; yasal izinli kamusal sanat ile mülke zarar veren graffiti arasındaki sınırı estetik değer, niyete göre yorum ve kurumsal kabulle çizer. Banksy gibi isimler bu sınırı kasıtlı bulanıklaştırır.' },
  { q: '"Sanat akımı olarak Romantizm" neyi öne çıkardı?', a: ['Akıl ve bilim', 'Duygu, doğa, milliyetçilik, birey kahramanlığı ve aydınlanma karşıtı içgüdü', 'Geometri ve simetri', 'Klasik mitoloji'], c: 1, e: 'Romantizm (18-19. yy); Aydınlanma\'nın akıl vurgusu yerine duyguyu, yüce doğayı, halk kültürünü ve ulusal destanları ön plana çıkardı. Delacroix, Turner ve Caspar David Friedrich en önemli temsilcilerdir.' },
  { q: '"Eugène Delacroix"nin "Halka Yol Gösteren Özgürlük" tablosu neyi anlatır?', a: ['Yunan mitolojisi', '1830 Temmuz Devrimi\'ni; bayrak taşıyan alegorik Özgürlük figürü barikatlar üzerinde yürüyor', 'Dini konu', 'Manzara'], c: 1, e: '1831 tarihli bu dev tablo; 1830 Fransız devrimini simgeleyen ve barikatlar üzerinde ilerleyen Marianne figürüyle Romantizm\'in en tanınan siyasi tablosu kabul edilir.' },
  { q: '"Caspar David Friedrich" hangi ruh haliyle özdeşleşir?', a: ['Neşe ve renk', 'Yüce doğa karşısında insan küçüklüğü; melankoli, hüzün ve tinsellik', 'Kentsel dinamizm', 'Tarihsel kahramanlık'], c: 1, e: 'Friedrich; arka dönük figürlerin uçurumlar, sisli ormanlar veya dağlar önünde seyrettiği kompozisyonları ile Alman Romantizmi\'nin en önemli ressamıdır. "Sis Denizinin Üzerindeki Gezgin" en ünlü eseridir.' },
  { q: '"Francisco Goya"nın "Karanlık Tablolar" serisi nedir?', a: ['Din resimleri', 'Ömrünün son döneminde evinin duvarlarına doğrudan çizdiği, korku, şiddet ve deliliği yansıtan karanlık eserler', 'Soylu portreleri', 'Savaş tarihi'], c: 1, e: '"Karanlık Tablolar" (Black Paintings); Goya\'nın 1819-23 arasında kendi evine (Quinta del Sordo) doğrudan duvarlara uyguladığı 14 gizemli, rahatsız edici eserdir. "Saturn Oğlunu Yiyor" bu serinin ikonik eseridir.' },
  { q: '"J.M.W. Turner" resim tarihinde neden öncü sayılır?', a: ['Portreciler arasında', 'Işık, sis ve hareketin soyut sınıra dayanan çarpıcı suluboya ve yağlıboyalarıyla empresyonizmi önceden haber verdi', 'Heykel alanında', 'Fresk ustası'], c: 1, e: 'Turner; fırtınalı denizleri, buharlı trenleri ve gün batımlarını ışık ve renkle erittiği tablolarıyla empresyonizmin doğrudan öncüsü sayılır. Monet Paris\'teki Turner eserlerinden derinden etkilendiğini kabul etti.' },
  { q: '"Japonizm" Batı sanatını nasıl etkiledi?', a: ['Hiç etkilemedi', 'Japon baskıların (ukiyo-e) düz renk alanı, asimetri ve kontur çizgisi Monet, Van Gogh ve Toulouse-Lautrec\'i derinden etkiledi', 'Yalnızca mimarlık', 'Yalnızca Çin etkisi'], c: 1, e: '19. yüzyılda Japonya\'nın Batı\'ya açılmasıyla ukiyo-e ahşap baskıları Avrupa\'ya ulaştı. Düz renk alanları, yüksek bakış açısı ve asimetrik kompozisyonlar; empresyonistler ve Art Nouveau\'yu dönüştürdü.' },
  { q: '"Ukiyo-e" nedir?', a: ['Japon heykeli', 'Edo dönemi Japonya\'sında gelişen ahşap baskı ve suluboya resim geleneği; günlük yaşam, aktörler ve doğa sahneleri', 'Çin kaligrafi', 'Kore seramiği'], c: 1, e: 'Ukiyo-e (geçici dünyanın resimleri); 17-19. yüzyıl Japonya\'sında Hokusai ve Hiroshige gibi ustaların ürettiği, kabartma baskı tekniğiyle çoğaltılan halk sanatı geleneğidir. "Büyük Dalga" en tanınan örneklerden.' },
  { q: '"Hokusai"nin "Büyük Dalga" eseri neden ikonikleşti?', a: ['En büyük resim', 'Güçlü dalga altında Fuji Dağı; ukiyo-e\'nin sadeliği ile dramatik güç duygusu Batı\'da da büyüledi', 'Yalnızca Japon kültürü', 'Fotoğraf kalitesi'], c: 1, e: '"Kanagawa Açıklarında Büyük Dalga" (1831); asimetrik kompozisyon, mavi renk hakimiyeti ve köpüklü dalganın dinamizmiyle ukiyo-e\'nin en tanınan eseri ve dünya sanatının ikonalarından biri haline geldi.' },
  { q: '"Art Nouveau" akımının temel özellikleri nelerdir?', a: ['Geometrik sertlik', 'Doğadan esinlenen kıvrımlı çizgiler, çiçek ve yaprak motifler; mimari, cam ve poster tasarımında uygulandı', 'Ham beton', 'Kübist parçalama'], c: 1, e: 'Art Nouveau (Yeni Sanat); 1890-1910\'da Avrupa\'yı kasıp kavuran ve doğanın organik biçimlerini mimari, cam, mücevher ve poster tasarımına taşıyan toplam tasarım hareketidir. Mucha ve Klimt en önemli temsilcilerdir.' },
  { q: '"Gustav Klimt"in "Öpücük" tablosu hangi akımı temsil eder?', a: ['Empresyonizm', 'Viyana Ayrılıkçılığı (Secession); altın yaprak kullanımı, Bizans mozaik etkisi ve erotik sembolizm', 'Kübizm', 'Sürrealizm'], c: 1, e: '"Öpücük" (1908); Klimt\'in Viyana Ayrılıkçılığı döneminin altın sarısı "altın evresi" içinde ürettiği, sarılı altın yaprak desenli figürlerle aşkı simgeleyen başyapıtıdır.' },
  { q: '"Egon Schiele" nasıl bir üslupla tanınır?', a: ['Yumuşak ve renkli', 'Çarpıtılmış figürler, açık erotik gerilim ve varoluşsal kaygıyı sert çizgilerle aktaran Viyana Ekspresyonizmi', 'Soyut', 'Minimalist'], c: 1, e: 'Schiele; genç yaşta hayatını kaybeden Avusturyalı Ekspresyonist ressamdır. Çarpıtılmış çıplak figürleri, keskin konturları ve rahatsız edici bakışlarıyla insan bedeninin kırılganlığını aktardı.' },
  { q: '"Bauhaus"ın temel felsefesi nedir?', a: ['Sanat sanat içindir', 'Güzel sanat ile zanaatı birleştirerek endüstriyel üretim için işlevsel ve estetik tasarım üretmek', 'Yalnızca boyama', 'Akademik figür'], c: 1, e: 'Bauhaus (1919-1933); Walter Gropius\'un kurduğu ve sanat-zanaat-teknoloji arasındaki hiyerarşiyi yıkarak "güzel ve kullanışlı" bütünselliğini hedefleyen tasarım okuludur. Modern grafik tasarım ve mimarinin temelini attı.' },
  { q: '"Bauhaus" neden kapandı?', a: ['Bütçesizlik', 'Naziler 1933\'te milliyetçi olmayan ve "yozlaşmış" buldukları okulun faaliyetine son verdi; pek çok öğretmen ABD\'ye göç etti', 'Başarısızlık', 'Öğrenci kalmadı'], c: 1, e: 'Nazi iktidarı; Bauhaus\'u "Bolşevik sanat" ve "yozlaşmış Yahudi kültürü" olarak damgalayarak 1933\'te kapattı. Başta Gropius, Mies van der Rohe ve Moholy-Nagy olmak üzere öğretmenler ABD\'ye göç ederek etkiyi dünyaya yaydı.' },
  { q: '"De Stijl" hareketi ne anlama gelir ve nerede doğdu?', a: ['Almanya, Ekspresyonizm', 'Hollanda\'da Piet Mondrian ve Theo van Doesburg önderliğinde gelişen, yatay-dikey ve üç temel renge indirgenmiş soyut tasarım hareketi', 'İtalya, Fütürizm', 'Fransa, Sürrealizm'], c: 1, e: 'De Stijl (Tarz); 1917\'de Hollanda\'da ortaya çıktı. Yatay-dikey çizgiler ve kırmızı-mavi-sarı-siyah-beyaz ile "evrensel estetiği" hedefledi. Mimarlık, mobilya ve grafiği dönüştürdü.' },
  { q: '"Gerçekçilik (Realism)" akımının öncüsü kimdir?', a: ['Jacques-Louis David', 'Gustave Courbet; "ancak gördüklerimi resmederim" ilkesiyle idealize etmeden sıradan hayatı aktardı', 'William-Adolphe Bouguereau', 'Thomas Gainsborough'], c: 1, e: 'Courbet; 1850\'lerde mitoloji ve tarih yerine köylüleri, işçileri ve günlük yaşamı tuvale taşıdı. "Ressamın Atölyesi" ve "Örrüsküncüler" bu manifestonun simgesel eserleridir.' },
  { q: '"Empresyonizmde açık hava resmi (plein air)" neden önemliydi?', a: ['Ucuz boyama', 'Değişen ışık ve atmosferi anında yakalamak; tüp boya sayesinde mümkün olan saha çalışması', 'Müze yerine', 'Müşteri bulmak için'], c: 1, e: 'Taşınabilir boya tüpünün icadı (1841) ressamları atölyeden çıkardı. Empresyonistler; gün işığının anlık değişimini yalnızca doğanın içinde yakalayabileceklerini savunarak plein air (açık hava) çalışmayı felsefi ilke haline getirdi.' },
  { q: '"Litografi" nedir?', a: ['Ahşap baskı', 'Yüzey üzerine çizim yapılıp baskı alınan düz baskı tekniği; Toulouse-Lautrec\'in poster sanatında kullandığı yöntem', 'Gravür', 'Serigrafi'], c: 1, e: 'Litografi (taş baskı); desenin yağlı kalemle taş veya metal plaka üzerine çizilip baskı alınmasıyla çalışır. Su ile yağın birbirini itmesini kullanan bu kimyasal süreç, renkli poster üretimini devrimleştirdi.' },
  { q: '"Serigrafi (screen printing)" baskı tekniği kimle özdeşleşir?', a: ['Jackson Pollock', 'Andy Warhol; Marilyn Monroe ve Campbell\'s Soup gibi seri baskı eserleri', 'Robert Rauschenberg', 'Roy Lichtenstein'], c: 1, e: 'Warhol; serigrafiyi sanatsal teknik olarak benimseyerek Marilyn Monroe, Elvis Presley ve Campbell\'s Soup kutularını tekrarlayarak seri üretim kültürünü hem aktardı hem de eleştirdi.' },
  { q: '"Gotik katedrallerde" büyük renkli cam pencerelere ne ad verilir?', a: ['Rozasyon', 'Vitray (stained glass)', 'Fresk', 'Mozaik'], c: 1, e: 'Vitray; renkli cam parçalarının kurşun çerçevelerle birleştirildiği Gotik katedrallerin ikonik pencere sanatıdır. Chartres ve Sainte-Chapelle vitrayları Orta Çağ sanatının en görkemli örnekleri arasındadır.' },
  { q: '"Bizans sanatının" en karakteristik özelliği nedir?', a: ['Gerçekçi portreler', 'Altın zemin üzerine hiyeratik (katı, simetrik) kutsal figürler; ikonalar, mozaikler ve dini soyutlama', 'Perspektif derinliği', 'Doğa manzarası'], c: 1, e: 'Bizans sanatı; perspektif yanılsaması yerine spiritüel hiyerarşiyi temsil eden frontal simetrik figürler ve altın zemin kullanımıyla tanınır. İkonlar, Ravenna ve Konstantinopolis mozaikleri en güçlü örneklerdir.' },
  { q: '"İkon" (icon) sanatı ne anlama gelir?', a: ['Bilgisayar ikonu', 'Ortodoks Hristiyanlığında kutsanmış, dini önemi olan tahta üzerine yumurta temlerası boya ile yapılan kutsal imge', 'Herhangi sembol', 'Pop Art figürü'], c: 1, e: 'İkonlar; Ortodoks Hristiyanlıkta kutsal kişilerin ya da sahnelerin temsil edildiği, teknik ve ikonografik kurallara bağlı ahşap panel resimlerdir. "Yazan değil dua eden sanatçı" geleneğine dayanır.' },
  { q: '"Rokoko" üslubu hangi dönemde ve ülkede ortaya çıktı?', a: ['İtalya, 16. yy', 'Fransa, 18. yy başı; Barok\'un ağır görkemine karşı hafif, süslü, eğlenceli ve pastel tonlu estetik', 'İngiltere, 19. yy', 'Almanya, 17. yy'], c: 1, e: 'Rokoko; 18. yüzyıl başı Fransa\'sında Versailles aristokrasisinin zevk ve eğlencesini yansıtmak üzere gelişti. Watteau, Fragonard ve Boucher en önemli temsilcilerdir; pastel renkler ve kıvrımlı süsleme karakteristik.' },
  { q: '"Neo-Klasizm" neden doğdu?', a: 'Rokoko\'ya tepki', a: ['Empresyonizme tepki', 'Rokoko\'nun aşırı süsüne karşı Antik Yunan-Roma değerlerine ve erdeme dönüş; Fransız Devrimi\'nin sanatı', 'Gotik\'in yeniden canlanması', 'Rönesans\'ın kopyası'], c: 1, e: 'Neo-Klasizm; 18. yy sonunda Pompeii kazılarının ilhamı ve Rönesans ideallerine dönüş arzusuyla Rokoko\'nun eğlenceli süslemeciliğine karşı çıktı. Jacques-Louis David başyapıtları Fransız Devrimi\'nin etik mesajını aktarır.' },
  { q: '"Jacques-Louis David"in en ünlü eseri hangisidir?', a: ['Guernica', 'Horatii Yemini (The Oath of the Horatii)', 'Yıldızlı Gece', 'Mona Lisa'], c: 1, e: '"Horatii Yemini" (1784); Neo-Klasizm\'in manifestosu kabul edilen bu tablo, Roma savaşçılarının kılıçlara yemin ettiği sahneyle vatanseverlik, erdem ve öz fedakarlığı aktarır.' },
  { q: '"Empresyonist tablolar" neden başlangıçta reddedildi?', a: 'Pahalıydı', a: ['Dini değil', 'Akademik tuvalden farklı görünmesi, boyaların tamamlanmamış iz bırakması ve resmi olmayan konu seçimi', 'Küçük boyut', 'Yanlış renk'], c: 1, e: 'Paris Sanat Akademisi\'nin jürisi; empresyonistlerin görünürde "taslak" kalan fırça izleri, akademik mitoloji yerine günlük yaşam sahneleri ve deneysel renk kullanımını reddetti. Bu red sanatçıları 1874\'te bağımsız sergi açmaya itti.' },
  { q: '"Kaligrafinin" sanat olarak kabul görmesi hangi kültürlerde güçlüdür?', a: 'Yalnızca Çin', a: ['Yalnızca Avrupa', 'İslam, Çin, Japon ve Kore kültürleri; yazıyı dini, felsefi ve estetik ifadenin en yüksek biçimi sayar', 'Yalnızca Afrika', 'Yalnızca Latin'], c: 1, e: 'İslam geleneğinde hat, Kur\'an metnini görsel güzellikle birleştirdiğinden en yüce sanat sayılır. Çin ve Japon kaligrafisi; fırça hareketini meditasyon ve kültürel kimlikle iç içe bir ifade biçimi olarak görür.' },
  { q: '"Heykelde bronz dökümünü" en çok kullanan antik uygarlık hangisidir?', a: 'Mısır', a: ['Roma', 'Antik Yunan; atletler, tanrılar ve savaşçılar için gerçekçi ve dinamik bronz heykeller döktü', 'Çin', 'Mezopotamya'], c: 1, e: 'Antik Yunan\'da MÖ 5-4. yüzyılda bronz heykel sanatı zirveye ulaştı. Kaybolan balmumu (cire perdue) tekniğiyle dökülen heykeller; orantı, idealize edilmiş anatomi ve hareket duygusuyla öne çıktı.' },
  { q: '"Donatello"nun önemi nedir?', a: 'Barok dönem', a: ['Orta Çağ sanatçısı', 'Erken Rönesans\'ta bağımsız büyük boy bronz heykel geleneğini yeniden canlandıran ilk ustalardan; Davut heykeli öncü', 'Empresyonist ressam', 'Mimar'], c: 1, e: 'Donatello; serbest duran ve gerçekçi anatomi gösteren bağımsız figür heykelini Orta Çağ\'dan Rönesans\'a taşıdı. Tüm vücuduyla duran bronz Davut (1440\'lar), antik dönemden bu yana ilk bağımsız çıplak erkek heykeldir.' },
  { q: '"Michelangelo"nun "Davut" heykeli nerede sergilenmektedir?', a: 'Roma', a: ['Vatikan', 'Roma', 'Floransa, Accademia Galerisi', 'Paris, Louvre'], c: 2, e: 'Michelangelo\'nun 1501-1504 yılları arasında yarattığı mermer Davut; 1873\'ten bu yana Floransa\'daki Galleria dell\'Accademia\'da korunmaktadır. Başlangıçta Floransa Katedrali için tasarlanan heykel meydana konulmuştu.' },
  { q: '"Heykelde in-the-round" ve "rölyef" arasındaki fark nedir?', a: 'Boyut farkı', a: ['Malzeme farkı', 'In-the-round; tüm yönlerden görülebilen tam bağımsız heykel. Rölyef; düz zemine kabartma biçiminde bağlı eser', 'Yalnızca antik', 'Renk farkı'], c: 1, e: '"In-the-round" (tam yuvarlak) heykel; 360° çevresinden izlenebilen bağımsız eserdir. Rölyef ise yüzeye işlenmiş kabartmadır: alçak (bas-relief), orta (mezzo-relief) ve yüksek (high-relief) derinlikte olabilir.' },
  { q: '"Land Art" nedir?', a: 'Arazi satın alma', a: ['Çevre sanatı', 'Doğal manzara içinde toprak, kaya ve çevre malzemeleriyle oluşturulan büyük ölçekli heykel/düzenleme', 'Sokak sanatı', 'Fotoğraf sanatı'], c: 2, e: 'Land Art (Toprak Sanatı / Earthworks); 1960\'larda Robert Smithson\'ın "Spiral Jetty"si gibi coğrafyayı malzeme ve zemin olarak kullanan, genellikle ulaşılması zor devasa düzenlemelerdir.' },
  { q: '"Yeni Gerçekçilik (Hyperrealism)" nedir?', a: 'Foto sanatı', a: ['Sürrealizm türü', 'Fotoğrafı aşan titizlikte ayrıntı ve yanılsama üreten resim ve heykel akımı; Chuck Close ve Duane Hanson öncüleri', 'Soyutlama', 'Karikatür'], c: 1, e: 'Hiper Gerçekçilik; 1970\'lerden itibaren fotoğraf kadar ya da daha keskin ayrıntıyla insan figürü, nesne veya manzarayı aktaran resim ve heykel akımıdır. İzleyici gerçekle yapıt arasında tereddüt eder.' },
  { q: '"Neon sanatı" hangi sanatçı ile popülerleşti?', a: 'Andy Warhol', a: ['Salvador Dali', 'Dan Flavin ve Bruce Nauman; 1960\'larda floresan ve neon ışık tüplerini birincil sanat malzemesi olarak kullandı', 'Banksy', 'Christo'], c: 1, e: 'Dan Flavin; hazır floresan ışık armatürlerini minimal sanat eseri olarak kullandı. Bruce Nauman ise neon tüplerini dil oyunları ve kavramsal mesajlar için araçsallaştırdı. İkisi neon sanatının temel figürleridir.' },
  { q: '"Video sanatının" öncüsü kimdir?', a: 'Andy Warhol', a: ['Banksy', 'Nam June Paik; 1960\'larda televizyon ekranlarını ve video kamerayı sanat malzemesi olarak kullanan Koreli-Amerikalı sanatçı', 'Jean-Luc Godard', 'Yoko Ono'], c: 1, e: 'Nam June Paik; Fluxus hareketi içinde videoyu sanatsal araç olarak keşfetti. Onlarca TV monitörden oluşan enstalasyonları, medya ve tüketim eleştirisiyle video sanatının kurucu babası sayılır.' },
  { q: '"Christo ve Jeanne-Claude" hangi tür sanatla tanınır?', a: 'Resimle', a: ['Heykel', 'Dev ölçekli çevresel paketleme ve örtme sanatı; Reichstag, köprüler ve adaları kumaşla kapladılar', 'Litografi', 'Fotoğrafçılık'], c: 1, e: 'Christo; Reichstag\'ı (Berlin, 1995) ve Pont Neuf\'ü (Paris, 1985) kumaşa sararak çevreyi geçici sanat alanına dönüştürdü. Bu projeler mühendislik, bürokratik müzakere ve gösteri üçgeninde kavramsal sanatı ifade etti.' },
  { q: '"Performans sanatı" nedir?', a: 'Tiyatro oyunu', a: ['Dans performansı', 'Sanatçının bedenini ve eylemini sanat ortamı olarak kullanan; zaman, mekân ve izleyici etkileşimini kapsayan disiplinlerarası ifade', 'Müzik konseri', 'Film çekimi'], c: 1, e: 'Performans sanatı; 1960\'larda Fluxus ve Happening hareketiyle doğdu. Marina Abramovic\'in saatlerce süren dayanıklılık deneylerinde olduğu gibi sanatçı bedenini malzeme ve mesaj olarak kullanır.' },
  { q: '"Marina Abramović" hangi eseriyle en çok tanınır?', a: '"Gernika"', a: ['"Çığlık"', '"The Artist Is Present"; MoMA\'da 3 ay boyunca günlerce oturarak izleyicilerle göz teması kurdu', '"Nilüferler"', '"Çeşme"'], c: 1, e: '"The Artist Is Present" (2010, MoMA); Abramović\'in günde 8 saat boyunca hareketsiz oturarak her izleyiciyle sessiz göz teması kurduğu ve 1.500\'den fazla kişinin karşısına geçip çoğunun ağladığı çığır açan bir performans sanatı eseridir.' },
  { q: '"Yoko Ono" sanat dünyasına nasıl katkı sundu?', a: 'Ressam', a: ['Heykeltıraş', 'Fluxus hareketi içinde kavramsal performans, talimat sanatı ve barışçıl aktivizmle öncü rol', 'Fotoğrafçı', 'Mimari'], c: 1, e: 'Yoko Ono; 1960\'larda talimat bazlı "instruction art" ve katılımcı performanslarıyla Fluxus\'un önemli figürüydü. "Grapefruit" kitabı sanat talimatlariyle doludur; "Imagine" ile de küresel barış aktivizmine katkı sundu.' },
  { q: '"Tasarım" sanatın neresinde durur?', a: 'Tasarım sanattır', a: ['Sanatın altı', 'Tamamen ayrı', 'İkisi örtüşür ama tasarım işlevsel bir problem çözmeye; saf sanat ise doğrudan estetik ve ifade deneyimine odaklanır', 'Sadece grafik'], c: 2, e: 'Tasarım-sanat sınırı; Bauhaus\'tan bu yana tartışılır. Tasarım işlevi, sanat ifadeyi önceliklendirir. Ancak iyi tasarım estetik içerir, iyi sanat da izleyiciyle iletişim kurar; modern pratikte bu sınırlar giderek eriyor.' },
  { q: '"Rönesans"ın üç büyük ustası kimlerdir?', a: 'Raphael, Giotto, Botticelli', a: ['Monet, Renoir, Degas', 'Leonardo da Vinci, Michelangelo, Raphael', 'Caravaggio, Rubens, Rembrandt', 'Dürer, Holbein, Cranach'], c: 1, e: 'Leonardo, Michelangelo ve Raphael; Yüksek Rönesans\'ın "üçlüsü" olarak kabul edilir. Üçü de Floransa ve Roma\'da faaliyet gösterdi; perspektif, anatomi ve kompozisyonda standart yarattı.' },
  { q: '"Raffaello Sanzio (Raphael)"in okul freski hangisidir?', a: '"Yaratılış"', a: ['"Son Akşam Yemeği"', '"Atina Okulu" (Scuola di Atene)', '"Sistine Şapeli Tavanı"', '"Venüs\'ün Doğuşu"'], c: 1, e: '"Atina Okulu" (1509-1511); Vatikan\'daki Stanza della Segnatura\'ya Raphael tarafından yapıldı. Platon ve Aristoteles\'in merkezde yer aldığı antik filozofların portresi Rönesans hümanizmasının simgesi sayılır.' },
  { q: '"Empresyonizmde" renk teorisi kimden ilham aldı?', a: 'Newton', a: ['Goethe', 'Michel Eugène Chevreul ve Ogden Rood\'un renk kontrastı teorileri; yan yana saf renklerin gözde daha canlı algılanması', 'Dalton', 'Helmholtz'], c: 1, e: 'Chevreul\'ün eş zamanlı renk kontrastı teorisi ve Rood\'un spektral renk tabloları; Seurat\'nın puan ticilizm ve empresyonistlerin renk kullanımı üzerinde doğrudan bilimsel etki bıraktı.' },
  { q: '"Egzistansiyalizm" sanatı nasıl etkiledi?', a: 'Hiç etkilemedi', a: ['Yalnızca edebiyat', 'Anlamsızlık, bireysel özgürlük ve varoluşsal yalnızlık; Soyut Dışavurumculuk ve Varoluşçu tiyatroya beslenme', 'Sadece felsefe', 'Sadece savaş sonrası'], c: 1, e: 'Sartre ve Camus\'nun varoluşçuluğu; 2. Dünya Savaşı sonrasında Pollock ve De Kooning\'in eylem resimleri ile Beckett\'in "Godot\'yu Beklerken" oyununa kadar uzanan sanatsal kaygıları besledi.' },
  { q: '"Soyut sanat" neden Almanya\'da baskıya uğradı?', a: 'Çok pahalıydı', a: ['Sanatsal başarısızlık', 'Nazi rejimi; soyut ve modern sanatı "yozlaşmış sanat" (Entartete Kunst) olarak nitelendirerek yasakladı ve sanatçıları sürgüne gönderdi', 'Halk beğenmedi', 'Kilise karşı çıktı'], c: 1, e: '1937 Munich "Entartete Kunst" (Yozlaşmış Sanat) sergisi; Nazilerin modernizmi aşağılamak için Kandinsky, Klee, Grosz gibi ustaların eserlerini aşağılayıcı biçimde sergilediği propaganda fuarıdır. Pek çok sanatçı ABD\'ye sığındı.' },
  { q: '"Türk müziğinde "maqam" (makam) kaç tondan oluşur?', a: '7', a: ['5', '7-8 perdelik dizi; ancak tam oktav değil, makam başlangıç ve bitiş notasına göre tanımlanır', '12', '4'], c: 1, e: 'Makam; genellikle 7-8 perdeden oluşan ama bu perdelerin tam tam ton veya yarım ton değil mikrotonal aralıklar içerdiği Türk ve Arap müziği teorisinin tonal sistemidir.' },
  { q: '"Wolfgang Amadeus Mozart" kaç yaşında ilk operasını besteledi?', a: '16', a: ['18', '21', '11 yaşında "La finta semplice"yi yazdı; 12 yaşında opera besteledi', '14'], c: 2, e: 'Mozart; müzisyen bir aileden gelen erken dehadı. İlk tam opera olan "La finta semplice"yi 12 yaşında besteledi. Sanatsal olgunluğu ise 1780\'lerin operalarında ("Don Giovanni", "Figaro\'nun Düğünü") doruk yaptı.' },
  { q: '"Ludwig van Beethoven" sağırlığına rağmen nasıl müzik üretebildi?', a: 'Yardım aldı', a: ['Sadece yazıyordu', 'Sesler kafasında işlenmiş halde vardı; çenesi piyano rezonansını hissederdi. 9. Senfoni tamamen sağırken besteledi', 'Kısmen işitiyordu', 'Müzik bıraktı'], c: 1, e: 'Beethoven; 1816\'dan itibaren tamamen sağırlaştı ancak 9. Senfoni\'yi (1824) ve son kuartetleri bu dönemde besteledi. Piyano ibrelerini kafasına tutarak titreşimi hissederdi; melodik hafızası olağanüstüydü.' },
  { q: '"Klasik müzikte" sonat, konçerto ve senfoni arasındaki en belirgin fark nedir?', a: 'Uzunluk', a: ['Tempo', 'Sonat; soloist veya küçük grup. Konçerto; solist + orkestra diyaloğu. Senfoni; tam orkestra için büyük ölçekli eser', 'Nota sayısı', 'Dönem'], c: 1, e: 'Sonat; piyano ya da keman gibi solist için yazılır. Konçerto; solist ile orkestranın karşılıklı konuştuğu formdur. Senfoni ise yalnızca orkestra için tasarlanmış, çoğunlukla dört bölümlü büyük yapıttır.' },
  { q: '"Johann Sebastian Bach"ın müzik tarihindeki yeri nedir?', a: 'Empresyonist', a: ['Klasik dönem', 'Barok dönemin zirvesi; kontrapunt ve fugue tekniğinin ustası, armoni ve çok sesli yazımın temsilcisi', 'Romantik dönem', 'Neo-Klasik'], c: 1, e: 'Bach; 1685-1750 yılları arasında yaşadı ve Barok dönemin en büyük figürüdür. Fugue, kontrapunt ve korali birleştiren eserleri (Brandenburk Konçertoları, Matthäus Passion) Batı müziğinin temel taşlarıdır.' },
  { q: '"Romantik dönem müziğinde" hangi besteci ulusal kimliği en güçlü yansıttı?', a: 'Beethoven', a: ['Wagner', 'Chopin, Sibelius, Dvořák ve Bartók; her biri kendi ülkesinin halk müziğini senfoni ile birleştirdi', 'Schubert', 'Schumann'], c: 1, e: 'Ulusal Romantizm; Chopin (Polonya polka/mazurka), Sibelius (Finlandiya), Dvořák (Çek), Bartók (Macar halk müziği) gibi besteciler kendi uluslarının müzikal kimliğini Avrupalı form içinde ifade etti.' },
  { q: '"Richard Wagner"in müzik anlayışı neydi?', a: 'Yalnızca opera', a: ['Yalnızca senfoni', '"Gesamtkunstwerk" (bütünsel sanat yapıtı); müzik, şiir, sahne, görsel ve dans tek bir sanatsal bütünde birleşmeli', 'Yalnızca koro', 'Kısa eserler'], c: 1, e: 'Wagner; müzik, şiir ve sahne tasarımını "Gesamtkunstwerk" (bütünsel sanat yapıtı) adını verdiği ideal içinde birleştiren dev mitolojik operalar üretti. Bayreuth Festivali\'ni kendi yapıtları için kurdu.' },
  { q: '"Caz müziğinin" doğduğu şehir neresidir?', a: 'Chicago', a: ['New York', 'New Orleans; 20. yy başında Afrikalı-Amerikan müzisyenlerin blues, ragtime ve Creole müziğini sentezlemesiyle doğdu', 'Kansas City', 'Detroit'], c: 1, e: 'Caz; 1890\'ların sonu ve 1900\'lerin başında New Orleans\'ta doğdu. Kuzey\'e göç eden müzisyenlerle Chicago ve New York\'a yayıldı; doğaçlama, senkop ve call-and-response yapısı temel özellikleridir.' },
  { q: '"Blues müziğinin" temel yapısı nedir?', a: 'Klasik armoni', a: ['3 akor', '12 ölçülük (bar) blues formu; I-IV-V akor dizisi ve pentatonik gam temelinde doğaçlama ve ifadesel vokal', '8 bar', 'Modal caz'], c: 1, e: '12-bar blues; I (tonik) – IV (subdominant) – V (dominant) akorlarının tekrarlayan döngüsünden oluşur. Call-and-response söz yapısı, bent notlar ve vibrato; blues\'un ifadesel karakterini belirler.' },
  { q: '"Rock müziğinin doğuşunda" en etkili öncüller nelerdi?', a: 'Pop ve klasik', a: ['Caz ve opera', 'Ritim ve blues (R&B), country ve gospel; 1950\'lerde elektro gitar, davul ve bas gitarla birleşerek rock\'n\'roll\'u yarattı', 'Blues ve klasik', 'Folk ve caz'], c: 1, e: 'Rock\'n\'roll; Afrikalı-Amerikan R&B ve gospelin ritmi ile Beyaz Amerikan country geleneğinin birleşiminden doğdu. Chuck Berry, Little Richard ve Elvis Presley bu geçiş döneminin simgeleriydi.' },
  { q: '"The Beatles"in müzik tarihindeki önemi nedir?', a: 'Çok sattılar', a: ['Yalnızca pop', 'Kompozisyon çeşitliliği, stüdyo inovasyonu ve kültürel küreselleşmeyle rock müziğini sanat formuna taşıyan dönüştürücü etkisi', 'Yalnızca İngiliz', 'Yalnızca 60\'lar'], c: 1, e: 'Beatles; besteci ortaklığı (Lennon-McCartney), stüdyo deneyleri (Sgt. Pepper), tematik kavram albümleri ve kültürel devrim getirerek popular müziği hem estetik hem ticari açıdan köklü biçimde dönüştürdü.' },
  { q: '"Hip-hop müziğinin" dört temel unsuru nedir?', a: 'Beat, rap, dans, moda', a: ['Caz, blues, funk, soul', 'DJ\'lik (scratch/sample), MCing (rap), breakdance ve graffiti; 1970\'ler South Bronx\'ta ortaya çıktı', 'Rap, rock, pop, R&B', 'Sadece rap ve beat'], c: 1, e: 'Kool Herc ve Afrika Bambaataa\'nın tanımladığı hip-hop kültürünün dört sütunu: DJ\'lik (plak manipülasyonu), MCing (sözel anlatı), breakdance ve graffiti sanatıdır. Ayrılmaz bir kültürel bütün oluşturur.' },
  { q: '"Elektronik müziğin" öncüsü kim sayılır?', a: 'Daft Punk', a: ['Kraftwerk', 'Almanya\'dan Kraftwerk; 1970\'lerde synthesizer, drum machine ve bilgisayarı müziğin merkezi haline getirdi', 'Jean-Michel Jarre', 'Giorgio Moroder'], c: 1, e: 'Kraftwerk; 1970\'lerde Autobahn, Trans-Europe Express ve The Man-Machine albümleriyle tamamen elektronik enstrümanlarla insan müziği yarattı. Tekno, house, ambient ve hip-hop için doğrudan ilham kaynağı oldu.' },
  { q: '"Minimalist müzik" ne anlama gelir?', a: 'Kısa müzik', a: ['Az nota', 'Tekrar eden kısa melodik ve ritmik kalıpların yavaşça dönüşümüyle büyük etki yaratan yaklaşım; Philip Glass, Steve Reich', 'Fısıltı müziği', 'Solo enstrüman'], c: 1, e: 'Minimalizm; Philip Glass, Steve Reich ve Terry Riley\'ın öncülük ettiği, yüksek tekrarlı kısa motifler üzerine kurulu müzik akımıdır. Karmaşık armoni yerine süreç ve tekrarın hipnotik etkisini kullanır.' },
  { q: '"Opera"da "tenor" ve "baritone" arasındaki fark nedir?', a: 'Yaş farkı', a: ['Yalnızca repertuvar', 'Tenor; en tiz erkek sesi. Baritone; orta aralık erkek sesi. Bass en derin. Opera\'da rolü sesin aralığı belirler', 'Yalnızca İtalyanca', 'Giysi farkı'], c: 1, e: 'Opera ses sınıflaması erkekler için; tenor (tiz), baritone (orta) ve bas (derin); kadınlar için soprano, mezzo-soprano ve alto\'dur. Kahraman rolleri genellikle tenor, yaşlı veya otoriter karakterler bas-baritone ile canlandırılır.' },
  { q: '"Türk pop müziği"nde en etkili dönem hangisidir?', a: '1950\'ler', a: ['1970\'ler', '1980\'ler ve 1990\'lar; Sezen Aksu, Tarkan ve Ajda Pekkan\'ın şekillendirdiği; Batı pop ve Türk geleneksel müziğinin sentezi', '2000\'ler', '1960\'lar'], c: 1, e: '1980-90\'lar Türk popunda Sezen Aksu (söz ve beste ustası), Tarkan (uluslararası tanınırlık) ve Ajda Pekkan gibi isimler belirleyici oldu. Bu dönemde Batı prodüksiyon anlayışı Türk melodi geleneğiyle sentezlendi.' },
  { q: '"Arabesk müzik"in Türkiye\'deki sosyal arka planı nedir?', a: 'Yalnızca eğlence', a: ['Elit kültür', 'Köyden kente göçle gelen kesimin yabancılaşma, özlem ve şehirle gerilimini aktaran; resmî kültür tarafından uzun süre dışlanan müzik', 'Yalnızca Doğu etkisi', 'Yalnızca 1990\'lar'], c: 1, e: 'Arabesk; 1960-80\'lerde köyden kente göç eden yoksul kitlelerin yalnızlık, özlem ve kaderine boyun eğişini yansıtan; Mısır Arap müziğinin etkisiyle şekillenen ve uzun süre devlet radyosundan yasaklanan türdür.' },
  { q: '"Türkiye\'de opera ve bale" kurumsal tarihi nasıl başladı?', a: '1950\'ler', a: ['Osmanlı dönemi', 'Atatürk\'ün kültür reformları kapsamında 1936\'da Ankara\'da Devlet Konservatuvarı kuruldu; ilk devlet operası 1940\'larda sahneye çıktı', 'Osmanlı 19. yüzyıl', '1960\'lar'], c: 1, e: 'Cumhuriyet\'in kültür modernleşmesi çerçevesinde 1936\'da Carl Ebert önderliğinde Ankara Devlet Konservatuvarı kuruldu. İlk yerli opera (Ahmet Adnan Saygun\'un "Özsoy"u, 1934) Atatürk\'ün emriyle İran Şahı\'nın ziyaretine özel sahnelendi.' },
  { q: '"Türk halk müziğinde" en karakteristik enstrüman hangisidir?', a: 'Keman', a: ['Ney', 'Bağlama (saz); Türk halk müziği geleneğinin omurgası ve âşık kültürünün vazgeçilmez çalgısı', 'Ud', 'Darbuka'], c: 1, e: 'Bağlama (saz); farklı boyutları (cura, bağlama, divan sazı) ile Türkiye\'nin en yaygın halk çalgısıdır. Alevi-Bektaşi törenleri, âşık geleneği ve halk oyunlarının vazgeçilmez eşlikçisidir.' },
  { q: '"Âşık geleneği" Türk kültüründe ne anlama gelir?', a: 'Sadece aşk şiiri', a: ['Osmanlı saray şiiri', 'Saz eşliğinde doğaçlama şiir söyleyen gezgin halk şairi geleneği; Yunus Emre, Pir Sultan Abdal ve Karacaoğlan öncüler', 'Dini tören', 'Yalnızca Doğu Anadolu'], c: 1, e: 'Âşık; saz çalarak aşk, doğa, toplumsal eleştiri ve dini coşkuyu doğaçlama nazım ve ezgiyle aktaran Türk-Anadolu halk şair geleneğidir. UNESCO 2009\'da bu geleneği insanlığın kültürel mirasına aldı.' },
  { q: '"Türk edebiyatında Nobel ödüllü" yazar kimdir?', a: 'Yaşar Kemal', a: ['Orhan Veli Kanık', 'Orhan Pamuk; 2006\'da edebiyat Nobel\'i kazandı. "Kar", "Benim Adım Kırmızı" ve "Masumiyet Müzesi" en tanınan eserleri', 'Nazım Hikmet', 'Ahmet Hamdi Tanpınar'], c: 1, e: 'Orhan Pamuk; 2006\'da Nobel Edebiyat Ödülü\'nü kazanarak Türk edebiyatını uluslararası arenada en üst düzeye taşıyan ilk yazar oldu. Doğu-Batı gerilimi ve hafıza temaları eserlerinin merkezinde yer alır.' },
  { q: '"Nazım Hikmet" hangi nedenle önemlidir?', a: 'Pop şair', a: ['Osmanlı şairi', 'Türk şiirini hece ölçüsünden serbest şiire taşıyan; siyasi tutumu nedeniyle sürgüne giden 20. yüzyıl Türk edebiyatının en büyük şairi', 'Divan şairi', 'Yalnızca tercüman'], c: 1, e: 'Nazım Hikmet; serbest vezni Türk şiirine kazandıran, işçi ve insan haklarını siyasi anlatımla şiire taşıyan ve komünist görüşleri nedeniyle yıllarca hapsedilip sonunda sürgüne giden efsanevi şairdir.' },
  { q: '"Ahmet Hamdi Tanpınar"\'ın edebiyattaki yeri nedir?', a: 'Halk yazarı', a: ['Cumhuriyet şairi', 'Doğu-Batı sentezini, Osmanlı kültürü ve modernleşme gerilimini derin psikolojik roman ve şiirle aktaran Türk modernizminin mihenk taşı', 'Çocuk yazarı', 'Yalnızca eleştirmen'], c: 1, e: 'Tanpınar; "Huzur" ve "Saatleri Ayarlama Enstitüsü" ile Türk modernizminin en derinlikli yazarı sayılır. Doğu-Batı gerilimi, zaman, hafıza ve kimlik temaları eserlerinin özüdür.' },
  { q: '"Türk sinemasında" "Yılmaz Güney" dışında uluslararası tanınırlık kazanan yönetmen kimdir?', a: 'Atıf Yılmaz', a: ['Halit Refiğ', 'Nuri Bilge Ceylan; Cannes\'da birden fazla ödül (Altın Palmiye dahil) kazanarak Türk sinemasını sanat sinema dünyasına tanıttı', 'Ömer Kavur', 'Memduh Ün'], c: 1, e: 'Nuri Bilge Ceylan; "Uzak" (2003 Cannes Grand Prix), "Bir Zamanlar Anadolu\'da" (2011 Cannes Grand Prix) ve "Kış Uykusu" (2014 Altın Palmiye) ile Türk sinemasının en büyük uluslararası temsilcisidir.' },
  { q: '"Sinema tarihinde ilk renkli film" hangisidir?', a: '"Beyaz Kar"', a: ['"Casablanca"', '"Oz Büyücüsü" değil; "A Visit to the Seaside" (1908) ve Technicolor denemeleri öncü; Oz (1939) geniş kitlelere ulaşan ilk renkli büyük prodüksiyon', '"Ben-Hur"', '"Doğunun Doğuşu"'], c: 1, e: '"A Visit to the Seaside" (1908); Kinemacolor süreciyle renklendirilmiş ilk filimdir. Technicolor ise 1930\'lardan itibaren yaygınlaştı. "Büyücü Oz" (1939) geniş kitlelerin renkli sinemayı keşfettiği dönüm noktasıdır.' },
  { q: '"Auteur (autör) teorisi" sinemada ne anlama gelir?', a: 'Oyuncu odaklı', a: ['Stüdyo filmi', 'Yönetmenin bir filmin yaratıcı vizyonunun başlıca mimarı olduğu; kişisel üslup ve temaların filmlere damgasını vurduğu anlayış', 'Senaryo odaklı', 'Prodüktör kararı'], c: 1, e: 'Auteur teorisi; 1950\'lerde Fransız Yeni Dalga eleştirmenleri tarafından geliştirilen ve yönetmeni sanatçı olarak öne çıkaran film anlayışıdır. Hitchcock, Bergman, Fellini bu teorinin simgesel isimleridir.' },
  { q: '"Fransız Yeni Dalgası" (Nouvelle Vague) nedir?', a: '1940\'lar hareketi', a: ['İtalyan Neo-gerçekçilik', '1950-60\'larda Godard, Truffaut ve Chabrol gibi yönetmenlerin stüdyo geleneğine karşı el kameraları ve sokakta çekim yaparak sinema dilini yeniden yarattığı Fransız hareketi', 'Hollywood akımı', 'Belgesel hareketi'], c: 1, e: 'Nouvelle Vague; "Cahiers du Cinéma" çevresinden çıkan, küçük bütçeli, doğal ışık ve sokak çekimleriyle, rasgele montajla kurallara meydan okuyan sinema hareketi. Modern bağımsız sinemanın DNA\'sı bu hareketten gelir.' },
  { q: '"Alfred Hitchcock"un hangi filmi psikanalitik gerilimin zirvesi sayılır?', a: '"Kuşlar"', a: ['"Arka Pencere"', '"Psycho" (1960); Janet Leigh\'ın duş sahnesiyle sinemanın en ikonik korku sekanslarından birini yaratan gerilim klasiği', '"Vertigo"', '"Sapık"'], c: 1, e: '"Psycho" (1960); filmin ilk yarısında öldürülen baş kahramanıyla izleyici beklentisini kıran, duş sahnesiyle sinema tarihinin en etkili kesim montaj örneğini yaratan ve psikolojik gerilim türünü yeniden tanımlayan yapımdır.' },
  { q: '"Orson Welles"in "Yurttaş Kane" filmi neden önemlidir?', a: 'En çok izlendi', a: ['İlk sesli film', 'Derin alan çekimi, çizgisel olmayan anlatı, tavan aynası çekimi gibi teknik yeniliklerle sinema dilini köklü biçimde dönüştürdü', 'İlk renkli film', 'En uzun film'], c: 1, e: '"Citizen Kane" (1941); Orson Welles\'in 26 yaşında çektiği ve derin alan çekimi, doğrusal olmayan zaman, ses kullanımı ve subjektif kamera açılarıyla çoğu sinema listesinin zirvesine oturan başyapıttır.' },
  { q: '"Belgesel sinema" kurucusu kim sayılır?', a: 'Dziga Vertov', a: ['Robert Flaherty', 'John Grierson; "Drifters" (1929) ve "Flaherty\'nin filmi" tartışmasıyla belgesel türünü teorize ve sistematize etti', 'Dziga Vertov', 'Louis Lumière'], c: 1, e: 'John Grierson; belgeseli teorileştirip "gerçekliğin yaratıcı yorumlaması" olarak tanımladı. Robert Flaherty\'nin "Nanook of the North" (1922) ise belgesel formatın öncü eseri kabul edilir. İkisi birlikte türü şekillendirdi.' },
  { q: '"Animasyon filminde" hangi stüdyo "sinemanın büyülü dünyasını" kurdu?', a: 'Pixar', a: ['DreamWorks', 'Walt Disney Studios; 1937\'de ilk animasyon uzun metrajı "Pamuk Prenses"le animasyon sinemasını endüstriyel ölçeğe taşıdı', 'Studio Ghibli', 'Warner Bros'], c: 1, e: 'Walt Disney; 1937\'de "Snow White and the Seven Dwarfs"ı ile ilk tam uzun metrajlı animasyon filmini yaparak hem teknolojik hem anlatısal standart koydu. Günümüzde Pixar ve Ghibli bu mirası sürdürüyor.' },
  { q: '"Türk edebiyatında Servet-i Fünun" akımı neydi?', a: 'Halk edebiyatı', a: ['Cumhuriyet dönemi', 'Tevfik Fikret ve Halit Ziya Uşaklıgil öncülüğünde Fransız Parnasizm ve Sembolizm\'den etkilenen, Osmanlı Türkçesini süslü bir dille kullanan edebiyat akımı (1896-1901)', 'Divan edebiyatı', 'Tanzimat öncesi'], c: 1, e: 'Servet-i Fünun (Edebiyat-ı Cedide); 1896\'da Recaizade Mahmut Ekrem\'in çevresinde toplanan genç yazarların Fransız Parnasizm ve Sembolizm\'den ilham alarak Osmanlı edebiyatını yenileme girişimidir.' },
  { q: '"Türk edebiyatında Millî Edebiyat" ne zaman ve nasıl doğdu?', a: '1839', a: ['1908 öncesi', '1911\'de Selanik\'te kurulan Genç Kalemler dergisi etrafında; sade Türkçe, hece vezni ve Türk kimliğini ön plana çıkaran toplumsal içerik', 'Cumhuriyet sonrası', 'Tanzimat dönemi'], c: 1, e: 'Millî Edebiyat hareketi; 1911\'de Ziya Gökalp, Ömer Seyfettin ve Ali Canip Yöntem\'in Genç Kalemler dergisi etrafında başlattığı; saf Türkçe, hece ölçüsü ve millî konu/değerlere yöneliş akımıdır.' },
  { q: '"Osmanlı minyatür sanatı"nda hangi konu öne çıkar?', a: 'Dini ikonlar', a: ['Batı portresi', 'Saray hayatı, savaş sahneleri, tarihi olaylar ve destanî anlatımlar; genellikle belirli bir perspektif sistemi yoktur', 'Manzara resimleri', 'Çıplak figür'], c: 1, e: 'Osmanlı minyatürü; padişah saray törenleri, seferler, divan toplantıları ve Şehnâme gibi destanların anlatıldığı, elle renklendirilmiş küçük boyutlu resim geleneğidir. Perspektif Batı sisteminden farklıdır; hiyerarşik ölçüt uygulanır.' },
  { q: '"Erken Türk resim sanatında" hangi ressam öne çıkar?', a: 'Matrakçı Nasuh', a: ['Nakkaş Osman', 'Halil Paşa ve Şeker Ahmet Paşa; 19. yüzyılda Paris\'te eğitim alan ve empresyonist etkiyi Türk resmine taşıyan öncüler', 'Levnî', 'Münif Ahmet'], c: 1, e: 'Şeker Ahmet Paşa (Ahmed Ali); 19. yy\'da Paris\'te Empresyonizm\'le tanışıp İstanbul\'a dönen ve ilk sergiyi açan ressamlardan biridir. Halil Paşa ile birlikte Türk empresyonizminin öncüsü sayılır.' },
  { q: '"Çallı kuşağı" Türk resminde neyi temsil eder?', a: 'Halk sanatı', a: ['Divan geleneği', 'İbrahim Çallı ve arkadaşlarının Paris\'te empresyonizmi özümseyip 1914 sonrası Türk resmini biçimlendirmesi', 'Soyut sanat', 'Natüralist akım'], c: 1, e: '"1914 Kuşağı" ya da "Çallı Kuşağı"; İbrahim Çallı, Feyhaman Duran ve Namık İsmail gibi ressamların Paris eğitiminden dönerek yurt koşullarını ve toplumsal yaşamı empresyonist anlayışla tuvaline taşıdığı Türk resim tarihinin dönüm noktasıdır.' },
  { q: '"Türk heykeli"nde cumhuriyet döneminin öne çıkan eseri nedir?', a: 'Sultanahmet Anıtı', a: ['Galata Kulesi heykeli', 'Krippel ve daha sonra Türk sanatçıların yaptığı Atatürk anıtları; Taksim Cumhuriyet Anıtı (1928, Pietro Canonica)', 'Topkapı heykeli', 'Boğaz heykeli'], c: 1, e: 'Taksim Meydanı\'ndaki Cumhuriyet Anıtı (1928); İtalyan heykeltıraş Pietro Canonica tarafından yapılmıştır. Türk cumhuriyeti heykeltıraşlığının başlangıcını simgeler; İlhan Koman ve Zühtü Müridoğlu ilerleyen dönemde öne çıkmıştır.' },
  { q: '"Türk kültüründe Karagöz ve Hacivat"ın UNESCO statüsü nedir?', a: 'Dünya Mirası yapısı', a: ['Coğrafi işaret', 'İnsanlığın Somut Olmayan Kültürel Mirası (2009)', 'Yalnızca ulusal', 'Kültürel miras değil'], c: 2, e: 'Karagöz ve Hacivat gölge oyunu; 2009\'da UNESCO İnsanlığın Somut Olmayan Kültürel Mirası Temsilci Listesi\'ne alındı. Bursa\'da ortaya çıktığı kabul edilen bu gelenek; toplumsal hicvi ve kahkahayı ortak bir sahnede buluşturur.' },
  { q: '"Türk mimarisinde erken Cumhuriyet dönemi"nde hangi üslup hâkimdi?', a: 'Gotik', a: ['Barok', '1930\'larda Milli Mimarlık (ya da Birinci Ulusal Mimarlık) akımı; Osmanlı-Selçuklu unsurları modern bina programlarıyla birleştirildi', 'Modernizm', 'Art Nouveau'], c: 1, e: 'Cumhuriyet\'in ilk döneminde Vedat Tek ve Mimar Kemaleddin; Osmanlı cami kubbesi, stalaktit süsleme ve kemer gibi unsurları modern banka, tren garı ve hükümet binasına taşıdı. Buna "1. Ulusal Mimarlık Akımı" denir.' },
  { q: '"Türk sanatında Bedri Rahmi Eyüboğlu"nun önemi nedir?', a: 'Heykeltıraş', a: ['Divan şairi', 'Anadolu halk sanatını ve renk geleneğini çağdaş Batı estetiğiyle harmanlayan; resim, şiir ve seramikteki çok yönlülüğüyle öne çıkan sanatçı', 'Mimar', 'Fotoğraf sanatçısı'], c: 1, e: 'Bedri Rahmi Eyüboğlu; Anadolu halı, kilim ve duvar resmi motiflerini modern tablo dilinde kullanan, Paris atölyelerinde pişen ama kök renk anlayışından vazgeçmeyen çok yönlü sanatçıdır. Türk resminin özgün sentezini simgeler.' },
  { q: '"Türkiye\'de çağdaş sanatta" hangi kurum öne çıkar?', a: 'Yalnızca devlet müzesi', a: ['Hiç kurum yok', 'İstanbul Modern (2004), Pera Müzesi ve SALT; çağdaş Türk ve uluslararası sanatı sergileyen özel kurumlar', 'Yalnızca üniversite galerileri', 'Yalnızca yurt dışı'], c: 1, e: 'İstanbul Modern; 2004\'te açılan ve Türk çağdaş sanatını dünya standartlarında sergileyen ilk büyük özel sanat müzesidir. Pera Müzesi ve SALT da çağdaş sanat, fotoğraf ve araştırma alanlarında öne çıkan kurumlar arasındadır.' },
  { q: '"Sanat fotoğrafçılığı" ne zaman bağımsız bir alan olarak kabul gördü?', a: 'Fotoğrafın icadıyla', a: ['1950\'ler', '1960-70\'lerde; önce "Photo Secession" (Alfred Stieglitz, 1902) sonra konsept fotoğrafın galeriye girmesiyle', '1990\'lar', 'Dijital dönemle'], c: 1, e: 'Alfred Stieglitz; 1902\'de Photo Secession hareketini kurarak fotoğrafı sanat olarak tanınması için kampanya açtı. Sonraki dönemde Henri Cartier-Bresson, Ansel Adams ve Diane Arbus fotoğrafı galeri ortamına taşıdı.' },
  { q: '"Kolaj" sanatı hangi akımda önemli bir araç haline geldi?', a: 'Empresyonizm', a: ['Barok', 'Kübizm; Picasso ve Braque gazete parçaları, kumaş ve farklı malzemeleri tuvale yapıştırarak geleneksel resim anlayışını sarstı', 'Gerçekçilik', 'Art Deco'], c: 1, e: 'Kübizm; 1912\'den itibaren "papier collé" (yapıştırılmış kağıt) tekniğiyle kolajı sanata kazandırdı. Picasso ve Braque; gazete, müzik notası, desen kağıdı gibi hazır malzemeleri tuvaline taşıyarak resmin illüzyon yanılsamasını sorguladı.' },
  { q: '"Sanatın küreselleşmesi" son 30 yılda sanat piyasasını nasıl dönüştürdü?', a: 'Hiç değişmedi', a: ['Yalnızca Batı', 'Çin, Hindistan, Orta Doğu ve Afrika sanatçıları uluslararası müzayedeye girdi; Batı merkezli kanon sorgulanmaya başlandı', 'Yalnızca dijital', 'Yalnızca bienal'], c: 1, e: 'Son 30 yılda İstanbul, Dubai, Shanghai ve Mumbai gibi şehirlerdeki bienaller ve artan uluslararası koleksiyonculuk sayesinde Batı dışı sanatçılar küresel piyasada yer kazandı; "Batı merkezci sanat tarihi" çok sesli bir eleştiri aldı.' },
  { q: '"NFT sanatı" nedir?', a: 'Normal dijital sanat', a: ['Yeni fotoğraf', 'Blokzincir üzerinde doğrulanan benzersiz dijital sanat eseri sahipliği; 2021\'de Beeple\'ın 69 milyon dolara NFT satışıyla gündemin merkezine oturdu', 'Sanal gerçeklik', 'Oyun estetiği'], c: 1, e: 'NFT (Non-Fungible Token); blokzincir teknolojisiyle dijital eserin orijinalliğini ve sahipliğini belgeler. Beeple\'ın "Everydays: The First 5000 Days" adlı NFT\'si Christie\'s açık artırmasında 69 milyon dolara satılarak dijital sanatı piyasaya taşıdı.' },
  { q: '"Sanat ve yapay zeka" tartışmasının özü nedir?', a: 'AI sanat üretemez', a: ['Tamamen olumlu', 'AI üretilen görseller; özgünlük, telif hakkı, sanatçı emeği ve yaratıcılığın özüne dair derin etik ve felsefi soruları gündeme getirdi', 'Yalnızca araç', 'Sorun yok'], c: 1, e: 'Midjourney ve DALL-E gibi AI görsel üreticileri; "insan yaratıcılığı olmadan üretilen eser sanat mıdır?", "eğitim verisindeki sanatçıların hakları korunuyor mu?" ve "sanatçı emeğinin değeri ne olacak?" sorularını tartışmaya açtı.' },
  { q: '"Edgar Degas" hangi teknikten etkilenerek figürlerini beklenmedik açılardan çizdi?', a: ['Empresyonizm teorisi', 'Japon baskılar ve fotoğrafın kesme/kırpma estetiği', 'Kübizm kuralları', 'Akademi normu'], c: 1, e: 'Degas; Japon ukiyo-e baskılarının asimetrik kompozisyonundan ve fotoğrafın anlık dondurma etkisinden ilham alarak figürleri frame dışına taşan, alışılmadık bakış açılarıyla yakaladı.' },
  { q: '"Mary Cassatt" hangi çevreyle yakın ilişki kurdu?', a: ['Sürrealistler', 'Degas ve Empresyonist çevre; Paris\'teki Amerikalı koleksiyonculara Empresyonizm\'i tanıttı', 'Dadaistler', 'Kübistler'], c: 1, e: 'Cassatt; Paris\'te Degas ile dostluk kurdu ve Amerikalı zengin koleksiyonculara —özellikle Havemeyer ailesine— Empresyonist eserler önererek bu sanatın Amerika\'ya açılmasını sağladı.' },
  { q: '"Empresyonist resimde" tamamlanmamış görünen fırça izleri neden estetik bir tercih haline geldi?', a: ['Tembellik', 'Anı yakalamak için hızlı uygulamanın kaçınılmaz ürünü; bu "taslak" görünüm canlılık ve hareket duygusu kattı', 'Bütçe kısıtı', 'Teknik yetersizlik'], c: 1, e: 'Empresyonistler; günışığının saniyeler içinde değiştiğini ve bunu yakalayabilmek için hızlı, kaygısız fırça darbelerinin zorunlu olduğunu savundu. Bu yaklaşım akademik "bitmiş yüzey" anlayışını bilinçli olarak reddeden estetik bir tercihe dönüştü.' },
  { q: '"Camille Pissarro" empresyonizm içinde nasıl bir rol oynadı?', a: ['Kurucusu değil', 'Tek başına hem Empresyonist hem Neo-Empresyonist sergiye katılan; genç sanatçılara (Cézanne, Gauguin) mentor olan dürüst figür', 'Sadece manzara', 'Yalnızca Paris'], c: 1, e: 'Pissarro; tüm sekiz bağımsız Empresyonist sergiye katılan tek sanatçıydı. Hem Cézanne\'ı hem Gauguin\'i yönlendirdi; sonunda Seurat\'nın puan ticilizmini benimseyip Neo-Empresyonizme geçti.' },
  { q: '"Gustave Moreau" hangi akımın öncüsü sayılır?', a: ['Kübizm', 'Sembolizm; mitolojik ve dinî konuları yoğun, zengin renkler ve ayrıntılı süslemelerle aktarması', 'Pop Art', 'Minimalizm'], c: 1, e: 'Moreau; Yunan mitolojisi ve Doğu gizemini aşırı dekore edilmiş ve renkli tablolarda yorumlayan Sembolizm\'in öncüsüdür. Matisse ve Rouault\'nun öğretmeni olarak Ekspresyonizm\'e de köprü oluşturdu.' },
  { q: '"Pierre Bonnard" hangi özellikleriyle Empresyonizm\'i aştı?', a: ['Tamamen aştı', 'Rengi duyguyu ifade aracı olarak kullanan yoğun ve titreşen paleti ve mahrem iç mekan kompozisyonlarıyla Post-Empresyonizm\'de özel bir yer edindi', 'Soyutlamaya geçti', 'Kübizme uyarladı'], c: 1, e: 'Bonnard; "Nabiler" grubunun bir üyesi olarak Japon baskı etkisini ve Gauguin\'in düz renk alanlarını benimsedi. Işık-renk ilişkisini ısrarlı biçimde derinleştiren iç mekan ve manzara tabloları onun özgün dilidir.' },
  { q: '"Édouard Vuillard" handen konuyla tanınır?', a: ['Bale sahneleri', 'Kapalı desenli kumaş ve duvar kağıtlarının içinde neredeyse eriyen figürlerle mahrem ev iç mekanları', 'At yarışları', 'Açık deniz'], c: 1, e: 'Vuillard; "Nabiler" grubu içinde özellikle aile mekan ve figürlerini yoğun desenli yüzeyler içinde eriterek "iç mekan resimleri"nin şairi oldu. Dekoratif desen ve figürü tek tuvale taşıyan bu yaklaşım Japonizm\'den beslendi.' },
  { q: '"Fauvism (Fovizm)"in adı nereden gelir?', a: ['Lider sanatçıdan', 'Eleştirmen Louis Vauxcelles\'in 1905 Salon d\'Automne\'da "vahşi hayvanlar" (fauves) dediği sanatçı grubuna atıfla', 'Manifestodan', 'Renk teorisinden'], c: 1, e: 'Eleştirmen Vauxcelles; 1905\'te Matisse ve arkadaşlarının aşırı canlı renkli tablolarını "les fauves" (vahşi hayvanlar) olarak nitelendirdi. Sanatçılar bu aşağılayıcı etiketi sahiplenerek hareketin adı haline getirdi.' },
  { q: '"Raoul Dufy" hangi tarzıyla tanınır?', a: ['Karanlık ve dramatik', 'Canlı renkler, özgür çizgi ve neşeli deniz, yarış pisti, konser sahnelerinin şenlikli yorumu', 'Soyut geometri', 'Fotogerçekçilik'], c: 1, e: 'Dufy; Fovizm\'den etkilenen ama sonra kendine özgü serbest fırça çizgileri ve neşeli renk düzlemleriyle yat yarışları, müzik toplantıları ve Fransız Rivierası sahnelerini aktaran özgün bir dil geliştirdi.' },
  { q: '"Robert Delaunay" hangi akımı kurdu?', a: ['Kübizm', 'Orphism (Orfizm/Orfik Kübizm); renk kontrastı ve ritmi aracılığıyla soyut ışık dinamiğini araştıran akım', 'Fovizm', 'Minimalizm'], c: 1, e: 'Delaunay; Kübizm\'den yola çıkarak renk kontrastını ana ifade aracı yapan Orfizm\'i kurdu. Eşi Sonia Delaunay ile birlikte Eş Zamanlı Renk teorisini moda, tekstil ve soyut tablolara uyguladılar.' },
  { q: '"Sonia Delaunay" tasarım dünyasına nasıl katkı sundu?', a: ['Sadece resim', 'Orfik renk ritmini moda, tekstil ve grafik tasarıma taşıyarak sanat-moda sınırını yıktı', 'Heykel', 'Fotoğraf'], c: 1, e: 'Sonia Delaunay; eşi Robert ile geliştirdiği renk kontrast teorisini kumaş tasarımı, moda, sahne kostümü ve reklam posterine taşıyarak sanat-zanaat-moda arasındaki hiyerarşiyi bilinçli biçimde sarstı.' },
  { q: '"František Kupka" soyut sanat tarihindeki yeri nedir?', a: 'Kübist', a: ['Pop sanatçı', 'Kandinsky ile eş zamanlı ama bağımsız olarak 1912\'de tam soyut eserler üreten Çek öncü; müzikle renk arasındaki analoji üzerine kurulu dili', 'Fütürist', 'Dadaist'], c: 1, e: 'Kupka; Kandinsky\'den bağımsız biçimde 1912\'de soyut resme ulaştı. Müziksel ritim ve rengi görselleştirme çabası olan "Amorpha" serisi, soyut sanatın birbiriyle bağlantısız iki farklı kaynaktan eş zamanlı doğduğunu gösterir.' },
  { q: '"De Chirico"nun "metafizik resmi" nedir?', a: ['Sürrealizm', 'Bomboş meydanlar, uzun gölgeler ve bağlamından koparılmış nesnelerle huzursuzluk ve yabancılık duygusu yaratan 1910\'lar İtalyan akımı', 'Kübizm', 'Gerçekçilik'], c: 1, e: 'Giorgio de Chirico; boş mimari perspektifler, uzun öğle gölgeleri ve bağlamından koparılmış heykeller içeren "Pittura Metafisica"sıyla Sürrealizm\'i doğrudan etkiledi; ancak kendisi bu akımla özdeşleşmeyi reddetti.' },
  { q: '"Carlo Carrà" ve "Umberto Boccioni" hangi İtalyan akımının simgeleri?', a: ['Empresyonizm', 'Fütürizm; makine çağını, dinamizmi ve enerjiyi parçalı formlarla tuvaline taşıdılar', 'Kübizm', 'Arte Povera'], c: 1, e: 'Boccioni\'nun "Uzaydaki Süregelen Hareket Biçimleri" ve Carrà\'nın dinamik kompozisyonları; Fütürizm\'in hareket, hız ve modern yaşamın enerjisini resmde içselleştirme çabasının en güçlü örnekleridir.' },
  { q: '"Klee"nin "resim müziği gibidir" anlayışı neyi ifade eder?', a: ['Sadece mecaz', 'Zaman, ses ve ritim gibi soyut müziksel parametrelerin çizgi, renk ve biçim aracılığıyla görsel karşılık bulabileceği', 'Biyografi', 'Teknik'], c: 1, e: 'Klee; keman virtüözü olması ve müzik tutkusuyla rengi zamana yayılan müzikal bir deneyim olarak ele aldı. Bauhaus\'taki ders notları "Pedagojik Sketchbook" sanatçıların müzik-görsel sanat ilişkisini bugün hâlâ başvurduğu kaynak.' },
  { q: '"Vasily Kandinsky"nin "Nokta ve Çizgi Yüzeye" kitabı neyi anlatır?', a: 'Renk teorisi', a: ['Mimarlık', 'Noktanın, çizginin ve düzlemin soyut ifade kapasitesini analiz eden; Bauhaus ders kitabı olan temel sanat teorisi eseri', 'Müzik teorisi', 'Fotoğrafçılık'], c: 1, e: 'Kandinsky\'nin 1926 tarihli "Punkt und Linie zu Fläche" (Nokta ve Çizgi Yüzeye) kitabı; geometrik sanat unsurlarının psikolojik ve ifadesel anlamını inceleyen ve Bauhaus eğitiminin temel referansı haline gelen sanat teorisi klasiğidir.' },
  { q: '"László Moholy-Nagy" Bauhaus\'a hangi katkıyı yaptı?', a: 'Resim dersi', a: ['Heykel dersi', 'Fotoğraf, ışık tasarımı ve endüstriyel tasarımı Bauhaus programına entegre etti; "Yeni Görme" anlayışının öncüsü', 'Mimarlık dersi', 'Müzik dersi'], c: 1, e: 'Moholy-Nagy; fotoğram (kamerasız fotoğraf), ışık-mekân modülatörü ve endüstriyel malzeme çalışmalarıyla Bauhaus\'ta görsel eğitimi fotoğraf ve teknoloji ile buluşturdu. Chicago\'ya göç ederek Yeni Bauhaus\'u kurdu.' },
  { q: '"Josef Albers" hangi araştırmasıyla sanat tarihine geçti?', a: 'Heykel teorisi', a: ['Fotoğraf teorisi', '"Rengin Etkileşimi" (Interaction of Color); rengin bağlama göre nasıl algılandığını sistematize eden, grafik tasarım ve renk teorisini dönüştüren çalışma', 'Mimarlık manifestosu', 'Müzik teorisi'], c: 1, e: 'Albers; "Interaction of Color" (1963) kitabında aynı rengin farklı arka planlarda tamamen farklı algılandığını görsel örneklerle kanıtladı. Bu çalışma sanat eğitimi, grafik tasarım ve renk psikolojisinin temel başvuru kaynağı.' },
  { q: '"Arshile Gorky" Soyut Dışavurumculuk tarihinde nasıl bir köprü figürdür?', a: 'Kübizm-Pop', a: ['Empresyonizm-Minimalizm', 'Sürrealist otomatizmi (bilinçdışı serbest çizim) ve Biyomorfik soyutlamayı ABD\'ye taşıyarak Soyut Dışavurumculuğa zemin hazırladı', 'Fovizm-Kübizm', 'Arte Povera-Land Art'], c: 1, e: 'Gorky; Ermenistan\'dan göç eden ve New York\'ta Breton, Miró gibi Sürrealistlerle tanışan sanatçıdır. Sürrealist otomatizm ile biyomorfik biçimleri birleştiren dili, De Kooning ve Pollock nesline ilham vererek Soyut Dışavurumculuğun filizlenmesine katkı sağladı.' },
  { q: '"Lee Krasner" sanat tarihinde neden uzun süre ikinci planda kaldı?', a: 'Yeteneği az', a: ['Erken öldü', 'Kocası Pollock\'un gölgesinde kalması; feminist sanat tarihi hareketi 1970\'lerden itibaren onun bağımsız başarısını öne çıkardı', 'Soyut yapmadı', 'Heykel yaptı'], c: 1, e: 'Krasner; Soyut Dışavurumculuğun özgün ve güçlü bir temsilcisiydi ama Pollock\'la evliliği kariyer görünürlüğünü gölgede bıraktı. Feminist sanat tarihi hareketi 1970\'lerden itibaren onu hak ettiği yere oturttu.' },
  { q: '"Helen Frankenthaler" hangi yeni tekniği geliştirdi?', a: 'Drip painting', a: ['Collage', '"Soak-stain" (emdirme-leke) tekniği; sulandırılmış boyayı hazırlanmamış kaneviçeye dökerek boyayı kumaşa işledi', 'Spray boya', 'Pastel'], c: 1, e: 'Frankenthaler; 1952\'de "Mountains and Sea" tablosunda boyayı yere serili hazırlıksız kaneviçeye dökerek boyayla tuvalin iç içe geçmesini sağladı. Bu "soak-stain" tekniği Renk Alanı resminin doğmasına katkı sundu.' },
  { q: '"Louise Bourgeois" hangi büyük heykel serisiyle tanınır?', a: '"Çiçekler"', a: ['"Nilüferler"', '"Örümcek" (Maman) serisi; devasa bronz örümcekler annelik, koruma ve kırılganlığı sembolize eder', '"Heykeller"', '"Köprüler"'], c: 1, e: 'Louise Bourgeois\'nın "Maman" (Anne, 1999) başlıklı dev örümcek heykeli; annesini, ipek böceği ve ağını, koruma ve tehdidin bir arada var olduğunu simgeler. Dünya müzelerinde kopyaları sergilenen bu heykel çağdaş sanatın ikonik eserleri arasına girdi.' },
  { q: '"Donald Judd" Minimalizm\'de neyi savundu?', a: 'Renk teorisi', a: ['Doğa taklidi', '"Specific Objects" (Özgün Nesneler) manifestosu; resim ve heykel arasındaki hiyerarşiyi kırmak ve üç boyutlu endüstriyel nesneleri doğrudan sanat alanına taşımak', 'Figüratif resim', 'Fotoğraf'], c: 1, e: 'Judd; 1965 tarihli "Specific Objects" makalesinde hem resmin hem geleneksel heykelin kısıtlamalarından arınmış yeni bir üç boyutlu nesne kategorisi önerdi. Fabrikada üretilen, yinelenmiş endüstriyel kutu ve raflar bu manifestonun ürünü.' },
  { q: '"Sol LeWitt" kavramsal sanatı nasıl tanımladı?', a: 'Eseri yaparak', a: ['Satarak', '"Bir kavramsal sanat eserinde fikir veya konsept, eserin en önemli yönüdür; tüm planlama ve kararlar önceden yapılır, icra mekanik meseledir"', 'Sergileyerek', 'Koleksiyona girerek'], c: 1, e: 'LeWitt; 1967\'deki "Paragraphs on Conceptual Art" makalesiyle kavramsal sanatı teorize etti. Duvar çizimleri; yalnızca talimat metni biçiminde satılır, her mekânda başkası tarafından uygulanır — nesne değil fikir satılır.' },
  { q: '"Bruce Nauman" hangi çeşitli ortam ve temalarla çalışır?', a: 'Yalnızca neon', a: ['Sadece video', 'Neon, video, ses, performans ve enstalasyon; dil oyunları, beden deneyimi ve psikolojik rahatsızlık temaları', 'Sadece heykel', 'Sadece fotoğraf'], c: 1, e: 'Nauman; 1960\'lardan bu yana neon metin, video döngüleri, ses enstalasyonları ve performansla dil, beden ve mekan sınırlarını sorgulayan disiplinlerarası bir sanat pratiği sürdürüyor. "The True Artist Helps the World by Revealing Mystic Truths" neon çalışması ikonikleşti.' },
  { q: '"Cindy Sherman" sanatın neyi sorgular?', a: 'Moda sektörü', a: ['Teknik beceri', 'Kendini farklı karakter ve kimliklere büründürerek fotoğrafladığı "Untitled Film Stills" serisiyle kadın temsilini, medya imgesini ve kimlik inşasını', 'Heykel üretimi', 'Renk teorisi'], c: 1, e: 'Sherman; 1977\'den itibaren kendisini farklı kadın arketiplerinde fotoğraflayan seri üretimiyle kimlik, temsil ve medya kültürünü sorguluyor. "Untitled Film Stills" serisi filmin kadın klişelerini alt ederken yeniden kurgulayan sanatsal dönüm noktası.' },
  { q: '"Barbara Kruger" sanat dilinde hangi aracı kullanır?', a: 'Yağlı boya', a: ['Heykel', 'Kırmızı çerçeve içinde siyah-beyaz fotoğraf üzerine beyaz Futura Oblique fontuyla güç, tüketim ve cinsiyet söylemlerini sorgulayan metin-görsel kombinasyonu', 'Kolaj', 'Video'], c: 1, e: 'Kruger; ticari reklamın görsel diline sahip çıkarak "Your Body Is a Battleground" gibi sloganlarla güç ilişkilerini, cinsiyetçiliği ve tüketim ideolojisini kamusal mekanda sorgulayan bir sanat dili kurdu.' },
  { q: '"Richard Serra"nın "Tilted Arc" enstalasyonu neden yıkıldı?', a: 'Bozuldu', a: ['Özel istek', 'New York\'ta kamusal mekana kuruldu ama çalışanlar geçişi engellediğini öne sürerek kaldırılmasını istedi; sanat-kamusal alan geriliminin ikonik davası oldu', 'Sergi bitti', 'Taşındı'], c: 1, e: '"Tilted Arc" (1981); New York Federal Plaza\'ya yerleştirilen dev çelik duvardır. Meydandaki çalışanlar geçişi engellediğini öne sürdü; 1989\'da mahkeme kararıyla yıkıldı. Serra\'nın "bütünleşik eser" tezine rağmen alınan bu karar kamusal-sanat tartışmasının mihenk taşı oldu.' },
  { q: '"Kara delik" olarak anılan sanat eseri hangisidir?', a: 'Gerçek kara delik', a: ['Astronomi tablosu', 'Anish Kapoor\'un "Descent into Limbo" (Sonsuzluğa İniş) enstalasyonu; izleyicinin derinlik yanılsamasına kapıldığı gerçek çukur veya yapay siyah yüzey', 'Fotoğraf', 'Heykel'], c: 1, e: 'Kapoor\'un bazı enstalasyonları; Vantablack gibi ışığı %99,96 oranında emen kara boya ya da gerçek çukurla oluşturulan sonsuz derinlik yanılsamasıyla izleyiciyi sınırlılığa ve sonsuzluğa aynı anda yüzleştirir.' },
  { q: '"Olafur Eliasson" sanatının çevresel boyutu nedir?', a: 'Yok', a: ['Yalnızca estetik', 'İklim değişikliği, ışık kirliliği ve doğa-insan ilişkisini çevre sanatı ve etkinizm ile harmanlayan bilinçli ekoloji mesajı', 'Yalnızca teknoloji', 'Yalnızca estetik'], c: 1, e: 'Eliasson; eriyen Grönland buzullarından getirdiği buz parçalarını müze önüne koyduğu "Ice Watch" enstalasyonuyla iklim krizini fiziksel deneyime dönüştürüyor. Doğa fenomenlerini mekana taşıyan sanatı ekoloji aktivizmiyle iç içe.' },
  { q: '"Takashi Murakami" hangi kültürel sentezi temsil eder?', a: 'Japon-Çin', a: ['Amerikan-Fransız', '"Superflat" kavramı; Japon anime ve manga estetiğini ticari sanatla buluşturan, tüketim kültürünü ironi ve coşkuyla kucaklayan Japonya merkezli çağdaş hareket', 'Avrupa-Asya', 'Kore-Japon'], c: 1, e: 'Murakami; ukiyo-e düz yüzeyini anime ikonografisiyle birleştiren "Superflat" manifestosunu kurdu. Louis Vuitton ile kolaborasyonu, müze ile moda-ticaret arasındaki sınırı bilinçli olarak silerek küresel sanat-ticaret diyaloğu açtı.' },
  { q: '"Ai Weiwei" sanat-aktivizm ilişkisini nasıl kurdu?', a: 'Yalnızca sanatla', a: ['Yalnızca aktivizmle', 'Çin siyasi sistemini, insan haklarını ve bürokratik şiddeti sanat enstalasyonları, sosyal medya ve beden tanıklığıyla sorgulayan Çinli sanatçı-aktivist', 'Yalnızca mimariyle', 'Yalnızca müzikle'], c: 1, e: 'Ai Weiwei; Sichuan depremi kurban listelerini derleyen dijital çalışmalardan mülteci botlarıyla Alman konsert salonu sararına kadar geniş bir siyasi sanat pratiği sürdürüyor. Çin hükümetince tutuklanması uluslararası baskıyla serbest kalmasına yol açtı.' },
  { q: '"Kara sanatçılar hareketi" (Black Art Movement) nedir?', a: 'Renk kullanımı', a: ['Müzik akımı', '1960-70\'lerde ABD\'de Afrikalı-Amerikalı sanatçıların siyasi farkındalık ve kültürel kimliği merkeze alan hareket; Faith Ringgold ve Romare Bearden öncüleri', 'Yalnızca resim', 'Mimarlık'], c: 1, e: 'Black Arts Movement; Sivil Haklar hareketi ve Siyah Güç politikasıyla eşzamanlı gelişti. Romare Bearden\'ın kolajları, Faith Ringgold\'un kumaş sanatı ve Elizabeth Catlett\'in heykelleri Afrikalı-Amerikalı deneyimi ve direncini görsel sanata taşıdı.' },
  { q: '"Feminist sanat hareketi" 1970\'lerde ne başardı?', a: 'Kadın sanatçı seçti', a: ['Müze kurdu', 'Sanat tarihinin erkek merkezli yapısını, müzedeki cinsiyet uçurumunu sorguladı; "Women House" (1972) ve Guerrilla Girls gibi girişimlerle kurumsal dönüşümü zorladı', 'Yalnızca sergi açtı', 'Devlet desteği sağladı'], c: 1, e: 'Judy Chicago\'nun "The Dinner Party" ve "Women House" projesi; Guerrilla Girls\'ün billboard kampanyaları ve Linda Nochlin\'in "Neden Büyük Kadın Sanatçılar Yok?" makalesi feminist sanat hareketinin müze ve akademi üzerindeki kalıcı dönüştürücü etkisini simgeler.' },
  { q: '"Guerrilla Girls" kim olduklarını neden gizler?', a: 'Utandıkları için', a: ['Yasadışı olduğu için', 'Gorilla maskesi takarak anonimliği seçtiler; kimliğe değil mesaja odaklanılsın ve üyelik değişse de hareket sürsün istediler', 'Sanatçı değiller', 'Korkudan'], c: 1, e: 'Guerrilla Girls; 1985\'ten bu yana gorilla maskeleriyle anonim kalan feminist sanat aktivistlerdir. Kimlik gizliliği mesajı ön plana çıkarır; "Do women have to be naked to get into the Met Museum?" posteri sanat kurumundaki cinsiyet eşitsizliğini ikonik biçimde sergiler.' },
  { q: '"Sanat tarihinin" sistematik bir disiplin olarak başlangıcı ne zaman kabul edilir?', a: 'Antik Çağ', a: ['Rönesans', '18-19. yüzyıl; Winckelmann\'ın Yunan sanatını tarihsel bağlama oturtmasıyla ve ardından Alman üniversitelerinin sanat tarihi kürsüsü kurmasıyla', 'Orta Çağ', '20. yüzyıl'], c: 1, e: 'Johann Joachim Winckelmann; 1764\'te "Geschichte der Kunst des Altertums"u (Antik Çağ Sanat Tarihi) yayımladı. Bu eser; sanatı dönem, stil ve kültürel bağlamla açıklayan sistematik sanat tarihinin kurucu metni kabul edilir.' },
  { q: '"Giorgio Vasari"nin "Sanatçıların Hayatları" kitabının önemi nedir?', a: 'İlk sanat kitabı', a: ['İlk fotoğraf kitabı', '1550\'de yayımlanan ve Leonardo\'dan Michelangelo\'ya sanatçı biyografilerini derleyen; sanat tarihi yazımının ilk sistematik örneği', 'İlk ansiklopedi', 'İlk eleştiri'], c: 1, e: 'Vasari\'nin "Le Vite de\' più eccellenti pittori, scultori e architettori" (1550, 1568); Rönesans sanatçılarının biyografilerini ve üslup gelişimini aktaran ilk kapsamlı sanat tarihi metnidir. Sanat tarihi disiplininin temel referansı.' },
  { q: '"İkonoloji" ikonografiden nasıl ayrışır?', a: 'Aynı şey', a: ['Yalnızca sembol', 'İkonografi sembolleri kataloglar; ikonoloji ise bu sembolleri dönemin toplumsal, dini ve felsefi bağlamıyla açıklar — Panofsky\'nin üç katmanlı yorum modeli', 'Yalnızca Rönesans', 'Yalnızca resim'], c: 1, e: 'Panofsky; sanat yorumunu üç katmana ayırdı: birincil (ne görüyorum?), ikonografik (ne anlam taşıyor?) ve ikonolojik (döneminin hangi değerini yansıtıyor?). İkonoloji en derin kültürel anlam katmanını çözer.' },
  { q: '"Deconstruction (Yapısalcılık eleştirisi)" sanatı nasıl etkiledi?', a: 'Hiç etkilemedi', a: ['Yalnızca edebiyat', 'Derrida\'nın "her metin kendini çürütür" tezi; sanat eserini tek anlamlı okumadan kurtarıp çelişkili yorumlara açtı', 'Yalnızca mimarlık', 'Sadece 1990\'lar'], c: 1, e: 'Derrida\'nın Yapıbozum teorisi; anlamın sabit olmadığını, her eserin kendi içinde çelişkiler taşıdığını öne sürdü. Bu yaklaşım; sanat eleştirisinde çoğul okuma, hegemonik anlatı sorgulaması ve kimlik politikaları üretimini besledi.' },
  { q: '"Postmodern sanat" modernizmden nasıl ayrışır?', a: 'Teknoloji farkı', a: ['Zaman farkı', 'Evrensel ilerleme anlatısını, özgünlük mitini ve biçimsel saflığı reddeder; ironi, alıntılama, melezlik ve çoğulculuğu benimser', 'Renk farkı', 'Boyut farkı'], c: 1, e: 'Modernizm; özgünlük, ilerleme ve biçimsel saflık arayışındayken Postmodernizm bu anlatıları kuşkuyla karşılar. Alıntılama (quotation), ironi, pastiş ve kültürel melezlik Postmodern sanatın temel stratejileridir.' },
  { q: '"Titian (Tiziano)" Venedik resmini nasıl dönüştürdü?', a: ['Perspektif buldu', 'Rengi formun üzerine çıkaran, atmosferik derinlik ve doğal ışıkla figürü adeta tenine büründüren özgün Venedik okulu üslubu', 'Fresk tekniği', 'Minyatür'], c: 1, e: 'Titian; konturun değil rengin hacim ve duygu yarattığını gösteren boya tekniğiyle Floransa resim geleneğinden ayrıştı. Yaşlandıkça serbest, neredeyse yoğrulmuş gibi görünen fırça işçiliği Empresyonizm\'i önceden haber verdi.' },
  { q: '"Paolo Veronese" tabloları hangi özellikleriyle öne çıkar?', a: ['Karanlık tonlar', 'Zengin kumaşlar, parlak renkler ve şenlikli büyük figür kompozisyonları; Venedik\'in ihtişamını aktaran görkemli sahneler', 'Soyutlama', 'Dini sadelik'], c: 1, e: 'Veronese; "Kana\'da Düğün" ve "Levi Evindeki Ziyafet" gibi dev boyutlu, zengin kostümlü ve parlak renkli tablolarıyla Venedik zenginliğini ve dekorativizmini yansıttı. İnquisition onu dini tablolara saygısızlık gerekçesiyle yargıladı.' },
  { q: '"Tintoretto" resim hızı ve tekniğiyle nasıl bir yer edinedi?', a: ['En yavaş ressam', 'Manierizma\'nın dinamik figür kalabalığı ve dramatik ışık-gölge arasında köprü kuran, olağanüstü hızıyla ünlü Venedikli usta', 'Minyatürcü', 'Fresk uzmanı'], c: 1, e: 'Tintoretto; "Titian\'ın rengi ve Michelangelo\'nun çizimi" parolasıyla çalışan ve inanılmaz üretim hızıyla efsaneleşen Venedikli ustadır. San Rocco\'daki dev Cennet tablosu 22x10 metre boyutuyla dünyanın en büyük tuval resimleri arasındadır.' },
  { q: '"El Greco" İspanya\'da hangi özgün dili geliştirdi?', a: ['Gerçekçi portreler', 'Uzatılmış figürler, soğuk renk paleti ve mistik bir gerilimle dini duyarlılığı Manierizma\'yı aşarak ifade eden Girit-İspanyol dili', 'Manzara', 'Natürmort'], c: 1, e: 'El Greco (Domenikos Theotokopoulos); Bizans ikon geleneğinden gelen ruhsallığı İtalyan Manierizmасı tekniğiyle ve Toledo\'nun mistik atmosferiyle harmanlayarak özgün bir üslup kurdu. 20. yüzyılda yeniden keşfedilip Ekspresyonizm\'in öncüsü olarak alkışlandı.' },
  { q: '"Diego Velázquez"in "Las Meninas" neden sanat tarihinin en çok incelenen tablosudur?', a: ['Büyük boyutu', 'Ressamın kendini tuvalde göstermesi, aynadaki yansıma ve izleyiciyle kurulan karmaşık bakış ilişkisi; temsil ve gerçeklik üzerine çok katmanlı bir sorgulama', 'Zengin renkleri', 'Kraliyet konusu'], c: 1, e: '"Las Meninas" (1656); Velázquez\'in kendisini ve İspanya Kraliçesi\'ni tuvalde konumlandırdığı, gerçeklik-illüzyon ve izleyici-eser ilişkisini çözülmez bir komplekslite içine sokan başyapıttır. Foucault ve Picasso başta olmak üzere pek çok düşünür ve sanatçı bu tabloya yorum yaptı.' },
  { q: '"Peter Paul Rubens" Barok resminde neyi simgeleştirdi?', a: ['Sadelik', 'Kıvrımlı dolgun figürler, canlı renk ve hareket; Barok dönemin yaşam sevinci, güç ve dramatizmi', 'Geometrik düzen', 'Karanlık tema'], c: 1, e: 'Rubens; büyük boyutlu mitolojik ve dini sahnelerinde dolgun, canlı renk paletli figürleri dinamik kompozisyonlarla birleştirdi. "Rubensque" sıfatı bugün dolgun, güçlü güzelliği tanımlamak için kullanılır.' },
  { q: '"Anthony van Dyck" hangi alanda ustalaştı?', a: ['Natürmort', 'Aristokrasiyi kibar, zarif ve güçlü gösteren saray portreciliği; İngiltere Kraliyet sarayının baş ressamı oldu', 'Manzara', 'Dini fresk'], c: 1, e: 'Van Dyck; Rubens\'in asistanlığından çıkıp İngiltere\'ye geçti ve Kral I. Charles\'ın baş ressamı olarak düzinelerce soylu portresini çizdi. Zarif uzun parmak, ince bel ve ipeksi kumaş detayları onun ayırt edici imzasıdır.' },
  { q: '"Frans Hals" portrecilikte neyi kırdı?', a: ['Renk sınırını', 'Donuk poz yerine anlık ifadeyi, kahkahayı ve hareketi yakalayan spontan fırça işçiliğiyle Hollanda portresini hayata kavuşturdu', 'Boyut sınırını', 'Konu sınırını'], c: 1, e: 'Hals; "Gülen Cavalier" ve "İçen Oğlan" gibi tablolarında anlık neşeyi ve hareketi spontan, özgür fırça darbeleriyle yakaladı. 19. yüzyılda yeniden keşfedilip Empresyonistlerin teknik öncüsü olarak saygı gördü.' },
  { q: '"Jan Steen" Hollanda resminde hangi konuya odaklandı?', a: ['Dini konular', 'Karmaşık, eğlenceli ve ahlaklı mesaj içeren günlük yaşam sahneleri; ahlaki alegori ile komik anlatıyı birleştiren Hollanda aile iç mekânları', 'Manzara', 'Portreler'], c: 1, e: 'Steen; tavernalar, aile sahneleri ve karnaval atmosferinde ahlaki mesajlar içeren tablolar üretti. "Jan Steen household" deyimi bugün bile Hollandaca\'da düzensiz ev anlamında kullanılmaktadır.' },
  { q: '"Johannes Vermeer" sadece kaç tablo bıraktı?', a: '200', a: ['500', 'Yaklaşık 34-36 onaylanmış eser; az üretimi rağmen her tablonun ışık ve sessizliği nedeniyle en çok incelenen ressamlardan biri', '100', '50'], c: 1, e: 'Vermeer; yaklaşık 34-36 eserle sanat tarihinin en az üreten ama en çok incelenen ustalarından biridir. Delft atölyesindeki ışıklı pencere, lacivert-sarı renk düzeni ve sessiz iç mekan sahneleri onu eşsiz kılar.' },
  { q: '"Camera Obscura" Vermeer\'in resmindeki rolü hakkında ne tartışılır?', a: 'Hiç ilgisi yok', a: ['Onu öğretti', 'Vermeer\'in ışık ve kompozisyon mükemmelliği için muhtemelen camera obscura (ışık kutusu) kullandığı teorisi; David Hockney bu hipotezi güçlü argümanlarla savundu', 'Fotoğraf makinesi kullandı', 'Ayna kullandı'], c: 1, e: 'David Hockney ve Philip Steadman; Vermeer\'in tablolarındaki optik mükemmelliğin camera obscura yardımıyla elde edildiğini öne sürdü. Bu tartışma; sanat ile teknoloji, özgünlük ve yardımcı araç arasındaki sınırı sorgulatmaya devam ediyor.' },
  { q: '"Jacob van Ruisdael" Hollanda resminde neyle öne çıktı?', a: ['Portreler', 'Dramatik gökyüzü, fırtınalı bulutlar ve melankolik orman manzaralarıyla Hollanda manzara resminin zirvesine ulaştı', 'Natürmort', 'Dini sahneler'], c: 1, e: 'Ruisdael; 17. yüzyıl Hollanda manzara resminin en güçlü temsilcisidir. Dev bulutlar, ağır rüzgar altındaki ağaçlar ve ıssız değirmen sahneleri; sonraki yüzyılda İngiliz Romantikler ve Barbizon okulu üzerinde derin etki bıraktı.' },
  { q: '"Meindert Hobbema"nın "Middelhaarnis Kavak Yolu" tablosu neden önemlidir?', a: ['İlk resim', 'İki yanı kavak sıralı yolun perspektifle derinlediği bu tablo; manzara resminde perspektif kullanımının en etkileyici örneklerinden biri', 'İlk manzara', 'İlk hollanda'], c: 1, e: '"The Avenue at Middelhaarnis" (1689); iki yanı kavak sıralı ıssız yolun dramatik perspektif derinliğiyle verildiği ve İngiliz Romantik manzara geleneğini doğrudan etkilediği Hollanda altın çağı manzarasının geç dönemi başyapıtı.' },
  { q: '"William Hogarth" 18. yüzyıl İngiltere\'sinde ne yaptı?', a: ['Kraliyet portrecisi', 'Toplumsal hiciv ve ahlaki alegori içeren anlatı seriler; "Fahişenin Kariyeri" ve "Seçim Törenleri" gibi hayattan sahneler', 'Manzara resmi', 'Natürmort'], c: 1, e: 'Hogarth; İngiliz sosyal eleştiri geleneğini resim ve gravürle birleştiren öncüdür. "A Rake\'s Progress" ve "Marriage à la Mode" serileri; Londra yüksek ve alt sınıfının ahlaki çöküşünü anlatı sırasıyla aktarır.' },
  { q: '"Thomas Gainsborough" hangi iki alanda ustalaştı?', a: ['Heykel ve manzara', 'Portre ve manzara; aristokrasiyi zarif biçimde betimleyen portreleri ile pastoral İngiliz manzaraları', 'Gravür ve baskı', 'Heykel ve resim'], c: 1, e: 'Gainsborough; hem "Blue Boy" gibi aristokrat portreleri hem de pastoral manzaraları ile Joshua Reynolds ile birlikte 18. yüzyıl İngiliz resminin iki büyük isminden biridir. Renk uygulama tarzı Empresyonistleri etkiledi.' },
  { q: '"Joshua Reynolds" sanat tarihindeki kurumsal rolü nedir?', a: 'Yalnızca ressam', a: ['Fotoğrafçı', 'Royal Academy of Arts\'ın ilk başkanı (1768) olarak akademik sanat eğitimini ve "Grand Manner" portreciliğini sistematize etti', 'Heykeltıraş', 'Mimar'], c: 1, e: 'Reynolds; İngiliz sanatının kurumsal çerçevesini Royal Academy ile oluşturdu ve "Discourses on Art" konuşmalarıyla Yunan-Roma idealine dayalı "Grand Manner" estetiğini tanımladı.' },
  { q: '"William Blake" sanat ve şiiri nasıl bir araya getirdi?', a: ['Ayrı tuttu', 'Şiir ve görsel sanatı el baskısıyla (illuminated printing) bir arada sunarak Romantizm\'in vizyoner öncüsü oldu', 'Yalnızca şiir', 'Yalnızca gravür'], c: 1, e: 'Blake; kendi geliştirdiği rölyef baskı tekniğiyle şiir ve resmi aynı sayfaya taşıdı. "Songs of Innocence and Experience" ve "Jerusalem" bu bütünleşik sanatın başyapıtları. Mistik vizyonları ve endüstri eleştirisiyle Romantizm\'in en özgün sesidir.' },
  { q: '"Henry Fuseli"nin "Kabus (The Nightmare)" tablosu neyi anlatır?', a: ['Manzara', 'Uyuyan bir kadının göğsüne çöken iblisle bilinçdışı, cinsellik ve korku imgesini melankolik dramatizm içinde birleştiren Romantik dönemi öncesi çarpıcı eser', 'Mitolojik savaş', 'Kraliyet ailesi'], c: 1, e: '"The Nightmare" (1781); Fuseli\'nin bilinçdışı ve cinsel kaygıyı kâbusu temsil eden iblis figürüyle görselleştirdiği tablodur. Freud bu tabloyu rüya analizinde referans göstermiş; Gotik ve Romantizm geleneğini derinden etkilemiştir.' },
  { q: '"John Constable" İngiliz manzarasını nasıl dönüştürdü?', a: ['Akademik manzara', 'Bulutları bilimsel gözlemle eskizleyen ve anın atmosferini canlı, taze boya darbesiyle aktaran doğa gerçekçiliği', 'Dramatik kurgusal', 'Tarihi manzara'], c: 1, e: 'Constable; geleneksel idealize manzara yerine Suffolk\'un tarlalarını, değirmenlerini ve bulutlu gökyüzünü doğrudan gözlemle gerçek yağmur ve ışıkla aktardı. Paris\'teki eserleri Delacroix\'ı ve Barbizon okulunu derinden etkiledi.' },
  { q: '"Thomas Cole" Amerikan sanat tarihinde ne kurdu?', a: 'Pop Art okulu', a: ['Minimalizm akımı', '"Hudson River School (Hudson Nehri Okulu)"; Amerikan doğasını ulusal kimlik ve yüce güzellik metaforu olarak yücelten ilk özgün Amerikan sanat hareketi', 'Kübizm', 'Sürrealizm'], c: 1, e: 'Thomas Cole; 1820\'lerde Hudson Vadisi\'nin şaşalı manzaralarını devasa boyutlu tablolara aktardı. Bu "Hudson River School" hareketi; Amerikan ulusal kimliğini doğanın yüce güzelliğiyle özdeşleştiren ilk özgün sanat okulu oldu.' },
  { q: '"Winslow Homer" Amerikan resminde hangi güçlü temayı ele aldı?', a: ['Soyut sanat', 'İnsan ve doğanın mücadelesi; deniz ve balıkçı figürlerini gerçekçi-dramatik bir dille aktaran özgün Amerikalı perspektif', 'Kentsel yaşam', 'Saray portreleri'], c: 1, e: 'Homer; Amerikan İç Savaşı\'ndan denizcilere, balıkçılardan kasırgaya uzanan geniş tematiğiyle Amerikan deneyimini güçlü dramatizm içinde resmeden özgün Amerikalı ustadır.' },
  { q: '"James McNeill Whistler" sanat felsefesini hangi söylemle özetledi?', a: '"Güzellik gerçektir"', a: ['"Sanat sanat içindir"', '"Sanat için sanat" (art for art\'s sake); sanatın herhangi bir ahlaki veya sosyal amaca hizmet etmemesi gerektiğini savunan estetizm tutumu', '"Sanat toplumdur"', '"Sanat doğadır"'], c: 1, e: 'Whistler; sanatın kendi içinde değer taşıdığını ve ahlaki ya da anlatısal işlevden bağımsız olması gerektiğini savundu. "Nocturne" serileri bu müzik metaforu kullanılan, saf atmosfer ve renk deneyimi arayışının ürünüdür.' },
  { q: '"Mary Stevenson Cassatt" hangi teknik etkiyle özdeşleşir?', a: ['Karakalem', 'Japonizm etkisiyle yapılan düz renk alanları, asimetrik kompozisyon ve ince konturlu baskı teknikleri', 'Fotogerçekçilik', 'Suluboya'], c: 1, e: 'Cassatt; 1890\'da Paris\'te düzenlenen Japon baskı sergisinden derin biçimde etkilenip kendi renkli baskı serisini üretti. Asimetrik kompozisyon, düz renk alanları ve zarif konu bu eserlerin belirgin özelliğidir.' },
  { q: '"Cecilia Beaux" Amerikan resim tarihinde neden önemlidir?', a: 'İlk kadın ressam', a: ['Soyut öncü', 'Sargent ile dönemin en başarılı portreci olarak anılan; Pennsylvania Güzel Sanatlar Akademisi\'nde ders veren ilk kadın öğretmenlerden biri', 'Empresyonizm kurucusu', 'Pop Art öncüsü'], c: 1, e: 'Beaux; Sargent ile birlikte dönemin en gözde Amerikalı portrecisi oldu. 1895\'te Pennsylvania Güzel Sanatlar Akademisi\'nde ders vererek kurumsal sanat eğitimindeki cinsiyet engelini yıkan önemli figürlerden biri.' },
  { q: '"Käthe Kollwitz" hangi tematik yoğunlukla tanınır?', a: ['Soylular', 'İşçi sınıfının acısını, ölümü ve savaş acılarını güçlü gravür ve litograflarla aktaran Alman Ekspresyonist sanatçı', 'Manzara', 'Soyut'], c: 1, e: 'Kollwitz; Alman yoksul işçi çevrelerini, savaş acısını ve ölümü son derece duygusal ama teknik olarak mükemmel gravür ve litograflarla aktardı. "Anne ve Ölü Çocuk" serisi savaş karşıtı sanatın evrensel simgesi.' },
  { q: '"Emil Nolde" Alman Ekspresyonizminde hangi özgün temayı yarattı?', a: ['Portreler', 'Canlı, neredeyse ham renk ve bozulmuş figürlerle spiritüel ve yabanıl dini sahneleri aktaran özgün Ekspresyonizm', 'Soyut geometri', 'Minimalizm'], c: 1, e: 'Nolde; vahşi, patlayan renk kullanımı ve bozulmuş figürleriyle dini coşkuyu ve yabanıllığı Alman Ekspresyonizmi\'nin en özgün sesi olarak aktardı. Nazi tarafından "yozlaşmış sanatçı" damgası vurulup üretimi yasaklandı.' },
  { q: '"Ernst Ludwig Kirchner" "Die Brücke" (Köprü) grubuyla ne kurdu?', a: ['Empresyonizm', 'Alman Ekspresyonizminin ilk örgütlü topluluğu; keskin çizgiler, çarpıtılmış figürler ve sarsıcı kentsel yabancılaşmayı aktaran avantgard grup', 'Minimalizm', 'Pop Art'], c: 1, e: '"Die Brücke" (Köprü); 1905\'te Dresden\'de Kirchner, Heckel ve Schmidt-Rottluff tarafından kurulan ve geleneksel Alman sanatından modern dışavurumculuğa köprü olmayı amaçlayan ilk Ekspresyonist örgütlü harekettir.' },
  { q: '"August Macke" ve "Franz Marc" "Der Blaue Reiter" (Mavi Süvari) grubunu nasıl kurdu?', a: ['Berlin\'de', 'Münih\'te Kandinsky ve Marc öncülüğünde; maneviyatı renk ve soyutlama aracılığıyla ifade eden Ekspresyonist kolektif', 'Paris\'te', 'Viyana\'da'], c: 1, e: '"Der Blaue Reiter" (Mavi Süvari); 1911\'de Münih\'te Kandinsky ve Marc\'ın kurduğu, rengi manevi ifadenin aracı olarak kullanan ve çeşitli sanat formlarını bir arada değerlendiren Ekspresyonist ittifaktır.' },
  { q: '"Franz Marc" hangi sembolik renk anlayışıyla tanınır?', a: ['Mavi=hüzün', 'Her rengi sembolik anlam yüküyle kullanan; mavi=erillik-manevi, sarı=dişilik-neşe, kırmızı=güç-şiddet gibi bağlantılar', 'Kırmızı=aşk', 'Yeşil=umut'], c: 1, e: 'Marc; rengi duygusal ve spiritüel anlamla doldurdu: mavi eriliği ve manevi arılığı, sarı kadınsallığı, kırmızı şiddeti temsil ederdi. Mavi at imgeleri bu renk sembolizminin en tanınan görsel ifadesidir.' },
  { q: '"Egon Schiele" kaç yaşında hayatını kaybetti?', a: '30', a: ['45', '28; 1918 İspanyol gribi salgınında öldü. Kısa ama son derece yoğun sanat pratiği bıraktı', '35', '50'], c: 1, e: 'Schiele; 1918\'de 28 yaşında İspanyol gribi nedeniyle hayatını kaybetti. Kısa yaşamında çarpıtılmış figürleriyle beden ve ruhun kırılganlığını aktaran yüzlerce tablo ve çizim bıraktı.' },
  { q: '"Oskar Kokoschka" hangi akımın önemli temsilcisidir?', a: 'Kübizm', a: ['Minimalizm', 'Avusturya Ekspresyonizmi; psikolojik derinlik ve ruhsal gerilimi görünür kılan portreler ve fırtınalı manzaralar', 'Pop Art', 'Sürrealizm'], c: 1, e: 'Kokoschka; bireyin iç dünyasını ve psikolojik gerilimi çarpıtılmış yüz ifadeleri ve sarsıcı renk kullanımıyla aktaran Avusturya Ekspresyonizminin en büyük temsilcilerinden biridir.' },
  { q: '"Max Beckmann" sanat anlayışını nasıl özetledi?', a: 'Soyut anlatım', a: ['Gerçekçilik', '"Figürü asla terk etmedim; mitoloji ve insan dramını yeniden yorumlayan Yeni Nesnelcilik (Neue Sachlichkeit) çerçevesinde Alman deneyimini aktardım"', 'Minimalizm', 'Saf renk'], c: 1, e: 'Beckmann; "Yeni Nesnelcilik" (Neue Sachlichkeit) akımının önemli temsilcisi olarak figüratif resmi terk etmedi. Mitolojik ve alegorik içerikli "triptych" (üçlü panel) serisi Almanya\'nın Weimar ve Nazi dönemi travmasını aktarır.' },
  { q: '"Georg Grosz" Weimar Cumhuriyeti\'ni nasıl yansıttı?', a: 'Yüceltici', a: ['Tarafsız', 'Keskin siyasi hiciv ve karikatüre yakın bir dil; ahlaki çöküş içindeki burjuvaziyi, militarizmi ve yoksulluğu vahşice aktaran Alman Ekspresyonist çizimleri', 'Soyut', 'Romantik'], c: 1, e: 'Grosz; Weimar Almanyası\'nın savaş sonrası ahlaklı bozulmasını, askeri budalalığını ve işçi yoksulluğunu keskin hicivli, karikatüre yakın tablo ve çizimleriyle mahkum etti. Naziler tarafından "yozlaşmış sanat" listesine alındı.' },
  { q: '"Hannah Höch" Dada\'ya hangi katkıyı yaptı?', a: 'Manifesto yazdı', a: ['Galeri kurdu', 'Dergi ve gazete görsellerini kesip yeniden düzenleyerek toplumsal cinsiyet ve Weimar kültürünü eleştiren fotomontaj öncülüğü', 'Performans', 'Heykel'], c: 1, e: 'Hannah Höch; Dada fotomontajının öncüsüdür. Magazin ve gazete görsellerini kesen ve yeniden düzenleyerek oluşturduğu "Cut with the Kitchen Knife" (1919) yeni insan, kadın rolü ve Weimar cumhuriyetinin çelişkilerini eleştirir.' },
  { q: '"Kurt Schwitters" Dada\'dan ayrışan "Merz" akımını neden kurdu?', a: 'Dada\'ya katılamadı', a: ['Dada\'yı beğenmedi', 'Berlin Dada\'sı onu reddetti; kendi adını verdiği "Merz" sanatıyla çöp ve bulunan nesneleri şiirsel bir bütünlük içinde birleştirdi', 'Para kazanmak için', 'Almanya\'yı temsil etmek için'], c: 1, e: 'Berlin Dada grubunca reddedilen Schwitters; bulduğu çöp ve nesne parçalarını kolajlayan "Merzbau" (Merz yapı) enstalasyonlarını kendi evinde oluşturdu. Bugün Arte Povera ve kavramsal sanatın öncüsü sayılır.' },
  { q: '"Francis Picabia" hangi iki harekette etkili oldu?', a: 'Kübizm-Pop Art', a: ['Empresyonizm-Fovizm', 'Dada ve Sürrealizm; makineleri erotik ya da absürd biçimde yorumlayan "makine resimleri" ile her iki akıma köprü kurdu', 'Minimalizm-Land Art', 'Arte Povera-Fluxus'], c: 1, e: 'Picabia; hem New York hem Zürih Dada\'sına katkı sundu; sonra Sürrealizm\'e geçti. Makineleri cinsellik, absürdite ve yorumsal özgürlükle yeniden hayal eden "makine portreleri" onun özgün katkısıdır.' },
  { q: '"Man Ray" sanat tarihine hangi katkılarla geçti?', a: 'Yalnızca fotoğraf', a: ['Yalnızca resim', 'Rayografi (kamerasız fotoğraf), solarizasyon ve Sürrealist fotoğraf; Dada ve Sürrealizm\'in iki ayağında da temel figür', 'Heykel', 'Performans'], c: 1, e: 'Man Ray; hem Dada hem Sürrealizm\'in temel figürü olarak fotoğramı (kağıt üzerine nesne bırakılıp ışığa maruz bırakma) ve solarizasyonu geliştirdi. Lee Miller ile işbirliği modern sanat fotoğrafçılığının kilometre taşlarındandır.' },
  { q: '"László Moholy-Nagy" ışık ve hareket üzerine hangi çalışmayı yaptı?', a: 'Sadece resim', a: ['Sadece fotoğraf', '"Işık-Uzay Modülatörü" (1930); motorla hareket eden ve gölge oyunları yaratan bu kinetik heykel ışığı üç boyutlu sanat malzemesi yapan ilk örneklerden', 'Sadece yazı', 'Sadece performans'], c: 1, e: 'Moholy-Nagy\'nin elektrik motoruyla dönen ve farklı yüzeylere gölge oyunları projekte eden "Light-Space Modulator"; ışığı ve zamanı heykel malzemesi olarak kullanan kinetik sanatın ve ışık sanatının erken başyapıtı.' },
  { q: '"Nicolas de Staël" hangi iki kutup arasında köprü kurdu?', a: 'Gerçekçi-Soyut', a: ['Kübist-Empresyonist', 'Soyut ve figüratif arasında; renk bloklarının fiziksel varlığını figüratif imgeyle yorumsal gerilimde tutan özgün dili', 'Pop-Minimal', 'Land-Fluxus'], c: 1, e: 'De Staël; kalın boya katmanlarıyla oluşturduğu renk bloklarını figüratif bir bağlam içinde ama tam soyutlamadan kaçınan bir dengeyle sundu. Ömrünün sonuna kadar soyut ve figüratif arasındaki gerilimi besleyen bu denge kendine özgüdür.' },
  { q: '"Alberto Giacometti" heykellerinin karakteristik özelliği nedir?', a: 'Tombul figürler', a: ['Bronz büstler', 'Son derece ince, uzatılmış ve yüzey işlenceli figürler; yabancılaşma, varoluşsal yalnızlık ve insanın kırılganlığı', 'Renkli heykeller', 'Büyük anıtlar'], c: 1, e: 'Giacometti; İkinci Dünya Savaşı sonrasında varoluşçu felsefeyle örtüşen ince-uzun kırılgan bronz figürleri yarattı. Figürlerin her girişimde yeniden daraltılması —asla tam olmama duygusu— sanatçının tutkusunun merkezindeydi.' },
  { q: '"Henry Moore" hangi heykel formlarıyla tanınır?', a: ['İnce portreler', 'Organik biyomorf formlar; soyut yatar insan figürleri, delikli yüzeyler ve anıtsal açık hava heykelleri', 'Geometrik küpler', 'Gerçekçi figürler'], c: 1, e: 'Moore; toprağa uzanmış figür ve anne-çocuk temalarını organik, bazen delikli biyomorf formlarla yeniden yaratan İngiliz çağdaş heykelinin en önemli ismidir. Eserleri dünya başkentleri ve müze bahçelerini süslemektedir.' },
  { q: '"Barbara Hepworth" heykelinin temel özelliği nedir?', a: 'Bronz portreciliği', a: ['Gerçekçi figür', 'Tahta ve taştaki organik biçimler, şekli içten boşaltan delikler ve soyut form aracılığıyla insan-doğa ilişkisi', 'Metal geometri', 'Yerleştirme'], c: 1, e: 'Hepworth; organik biçimlerde açtığı deliklerle içini ve dışını eş değere çıkardı; bu "delik" motifi heykelini tanımlayan imzasıdır. Cornwallis\'in deniz ve kaya manzarasına duyarlılığı çalışmalarına derin biçimde işledi.' },
  { q: '"David Smith" Amerikan heykelini nasıl dönüştürdü?', a: 'Taş heykeli', a: ['Seramik', 'Kaynak makinesiyle çelik boru ve plakaları birleştirerek endüstriyel malzemeyi soyut ekspresyonist heykel diline taşıdı', 'Mermer', 'Ahşap oyma'], c: 1, e: 'Smith; kaynak makinesini heykel aracı olarak kullanan öncüdür. "Cubi" serisi; parlak cilalı paslanmaz çelik küpler ve silindirlerin dinamik dengesiyle Amerikan Soyut Dışavurumculuğunun heykel boyutunu kurdu.' },
  { q: '"Alexander Calder" hangi heykel formunu icat etti?', a: 'Bronz döküm', a: ['Taş oyma', '"Mobile" (hareketli heykel); havaya asılan ve hava akımıyla sürekli değişen dengeli formlar ile statik "stabile"ler', 'Video heykel', 'Neon heykel'], c: 1, e: 'Calder; hava akımlarıyla hareket eden dengeli metal parçacıklarından oluşan "mobile"yi icat etti. Bu kinetik heykeller denge, hareket ve rastlantısallığı bir araya getirir. Marcel Duchamp "mobile" adını önerdi.' },
  { q: '"Jean Tinguely" kinetik sanatla ne yaptı?', a: 'Sakin heykeller', a: ['Yalnızca fotoğraf', '"Meta-Mécanique" makineleri; işe yaramaz, zamanla kendi kendini imha eden makineler yaptı. 1960\'ta Homage to New York MoMA bahçesinde yandı', 'Soyut tablolar', 'Müzik aletleri'], c: 1, e: 'Tinguely; endüstri çöpünden inşa ettiği "işe yaramaz" makineleri çalıştırarak kaos, tesadüf ve ölümlülüğü performansla birleştirdi. 1960\'ta MoMA bahçesinde izleyiciler önünde ateşe verilen "Homage to New York" kinetik sanatın ikonik anıdır.' },
  { q: '"Arte Povera"nın günümüze etkisi nedir?', a: 'Bitti', a: ['Sadece İtalya', 'Hazır nesne kullanımı, doğal malzeme ve kavramsal süreç; günümüz çağdaş sanatının temel stratejilerini besledi', 'Yalnızca müzede', 'Mimarlığa geçti'], c: 1, e: 'Arte Povera; "değersiz" malzemelerin sanat bağlamına taşınması, kavramsal sürecin öne çıkması ve endüstriyel karşıtı ekoloji anlayışıyla günümüz enstalasyon sanatı, materyal araştırmaları ve ekoloji sanatının köklü referansı.' },
  { q: '"Sanat eseri" ile "zanaat" arasındaki fark nedir?', a: ['Zanaat daha iyi', 'Fark yoktur', 'Sanat kavramsal özgünlük ve duygu-fikri öncelikler; zanaat ustalık, teknik ve işlev odaklıdır — ancak bu sınır her dönem tartışılmıştır', 'Zanaat daha eski'], c: 2, e: 'Antik Çağ\'da ayrım yoktu; Orta Çağ loncaları ikisini bir tuttu. Rönesans\'ta sanatçı el zanaatçısından ayrıştı. Bauhaus ikisini yeniden birleştirdi; günümüz çağdaş sanatı bu sınırı sürekli sorgular.' },
  { q: '"Müzik biçimleri" arasında "füg" nedir?', a: ['Solo parça', 'Temanın farklı seslerde sırayla girdiği ve karmaşık karşı noktalı dokuda gelişen çok sesli kompozisyon biçimi', 'Şarkı formu', 'Sonat bölümü'], c: 1, e: 'Füg; bir temanın farklı seslerde ard arda girmesiyle başladığı ve temaların karşılıklı geliştirildiği (stretto, inversion, augmentation) kontrapuntal biçimdir. Bach\'ın "İyi Tamperlenmiş Klavye"si füg sanatının zirvesi.' },
  { q: '"Keman" nasıl bir çalgıdır?', a: ['Nefesli', 'Yaylı çalgıların en tizi; dört tel, yay ve reçine kombinasyonuyla konser salonlarının vazgeçilmez solist enstrümanı', 'Tuşlu', 'Vurmalı'], c: 1, e: 'Keman (violin); 16. yüzyılda İtalya\'da gelişen dört telli yaylı çalgıdır. Sol el teli tutar, sağ el yayı kullanır. Stradivari kemanları günümüzde milyonlarca dolar değerindedir.' },
  { q: '"Piyano" hangi mekanizmayla ses üretir?', a: ['Teller titreşir', 'Tuşa basılınca çekiç keçesi ilgili teli vurur; telin titreşimi ses tahtasıyla ampliye olur', 'Hava üflenir', 'Boru titreşir'], c: 1, e: 'Piyano (pianoforte); "yavaşça-kuvvetlice" demektir. Tuşa uygulanan basıncın şiddeti çekiç hızını değiştirir; bu sayede piyano hem hafif hem güçlü çalabilir — seleflerinden davulçembalo ve clavicorddaki temel fark.' },
  { q: '"Oda müziği" ne anlama gelir?', a: ['Müzik odası', 'Küçük topluluklar için yazılmış (ikili, üçlü, dörtlü vb.); orkestral bütünden farklı, samimiyet gerektiren form', 'Solo eser', 'Konserto'], c: 1, e: 'Oda müziği (chamber music); büyük konser salonları yerine küçük mekânlarda çalınan ve her sesi ayrı bir sanatçının üstlendiği topluluk müziğidir. Dörtlü (string quartet) en yaygın formudur; Haydn, Mozart ve Beethoven bu alanda eserler verdi.' },
  { q: '"Operetta (operet)" ile "opera" arasındaki fark nedir?', a: 'Aynı şey', a: ['Yalnızca dil', 'Operet; daha kısa, komik ve popüler; konuşma diyalogları içerir. Opera; dramatik, recitative veya tamamen şarkıyla aktarılan büyük ölçekli form', 'Müzik yok', 'Sadece dans'], c: 1, e: 'Operetta; 19. yüzyılda gelişen, diyalog içeren, komik ve hafif müzikal tiyatrodur. Offenbach ve Johann Strauss en önemli temsilcileri. Opera ise tamamen müzikle anlatılan ve çoğunlukla dramatik içerikli yapıttır.' },
  { q: '"Broadway müzikali" ile "opera" arasındaki temel fark nedir?', a: 'Dil farkı', a: ['Ülke farkı', 'Broadway müzikali; mikrofon kullanır, genellikle dans ve diyalog içerir, popüler sahneleme. Opera; akustik ses, libretto ve büyük orkestral yap', 'Yok', 'Sahne büyüklüğü'], c: 1, e: 'Broadway müzikali; mikrofonlu ses, danslı sahneleme, konuşma diyalogları ve popüler müzikle opera\'dan ayrışır. Ancak son yıllarda "opera pop" alanında bu sınır giderek bulanıklaşmaktadır.' },
  { q: '"Jazz improvisation (doğaçlama)" neden caz müziğinin özüdür?', a: 'Kurallar yoktur', a: ['Nota gerekli değil', 'Caz teorisi (akord yapıları, modlar) çerçevesinde anlık yaratıcı müzik üretimi; sanatçının kişisel ifadesi her performansı eşsiz kılar', 'Dinleyici karar verir', 'Yalnızca solo'], c: 1, e: 'Caz doğaçlaması; belirlenen akord ilerlemesi ve form (12 bar blues, AABA gibi) içinde anlık melodik yaratımdır. Bu esneklik; caz\'ı her çalınışta farklı kılan ve sanatçının kimliğini müzikleştiren temel unsur.' },
  { q: '"Türk sanatçı Erol Akyavaş"ın önemi nedir?', a: 'Heykeltıraş', a: ['Grafik tasarımcı', 'İslam kaligrafi geleneğini ve Ortadoğu imgelerini soyut resim diliyle harmanlayan, New York\'ta kariyer yapan Türk çağdaş ressamı', 'Fotoğrafçı', 'Ressam'], c: 1, e: 'Erol Akyavaş; İslam kaligrafi ve simgeciliğini soyut dışavurumculukla sentezleyen ve New York sanat dünyasında tanınırlık kazanan Türk ressamdır. Eserlerinde Ortadoğu kültürel hafızası ve Batı soyut sanatı buluşur.' },
  { q: '"Türk sanatçı Ömer Uluç" hangi özgün dilini geliştirdi?', a: 'Soyut minimalizm', a: ['Gerçekçi portreler', 'Figür ve doğayı yoğun renk örgüsü içinde birleştiren; insan vücudu, erotizm ve varoluşsal gerilimi aynı anda aktaran özgün tuval dili', 'Minyatür', 'Video sanatı'], c: 1, e: 'Ömer Uluç; yoğun, canlı renkler ve dinamik fırça işçiliğiyle figür, hayvan ve doğa imgelerini erotik ve varoluşsal bir atmosferde birleştiren kendine özgü Türk çağdaş resim dilini kurdu.' },
  { q: '"Bubi (Elif Çelebi)" Türk çağdaş sanatında neden öne çıkar?', a: 'Fotoğrafçı', a: ['Ressam', 'Çelik ve metal gibi sert malzemeleri yumuşak ve duyarlı formlara dönüştüren heykel çalışmaları; beden, kimlik ve dönüşüm temaları', 'Grafik', 'Video'], c: 1, e: 'Bubi (Elif Çelebi); çelik ve metal gibi endüstriyel malzemeleri hassas, organik ve duyarlı formlara dönüştürerek beden ve kimlik üzerine güçlü heykeller üreten Türk çağdaş sanatçıdır.' },
  { q: '"Sanatçı manifestosu" neden yazılır?', a: 'Tanıtım için', a: ['Satış için', 'Yeni bir sanat anlayışını, değeri reddedilen akademik normu ya da geleceğe yönelik vizyonu kamuoyuna ilan etmek; grup kimliği oluşturmak', 'Yasal zorunluluk', 'Müze belgesi'], c: 1, e: 'Sanat manifestoları; Fütürizm (1909), Dada (1918), Sürrealizm (1924) ve Fluxus gibi hareketlerin yeni estetiği ve kültürel tavrı duyurduğu metinlerdir. Hem program belgesi hem kültürel provokasyon işlevi görür.' },
  { q: '"Sanat tarihinin ana akımları" kronolijik sırayla nelerdir?', a: 'Doğrusal değil', a: ['Kesin liste var', 'Doğrusal değil; Antik Çağ → Orta Çağ → Rönesans → Barok/Rokoko → Neo-Klasizm/Romantizm → Gerçekçilik → Empresyonizm → Post-Empresyonizm → Modern/Çağdaş akımlar', 'Yalnızca Batı', 'Yalnızca 5 dönem'], c: 0, e: 'Sanat tarihinin seyri doğrusal değildir; bölgesel, kültürel ve dönemsel akımlar birbirine paralel ve tepkisel biçimde gelişir. Batı merkezci bu kronoloji; İslam, Çin, Japon ve diğer büyük sanat gelenekleri dahil edildiğinde çok daha karmaşık bir tabloya dönüşür.' },
  { q: '"Sanatın demokratikleşmesi" ne anlama gelir?', a: 'Sanatın ucuzlaması', a: ['Devlet kontrolü', 'Sanatın müze duvarlarından dijital platformlara, kamusal alana ve eğitime yayılarak daha geniş kitlelere ulaşması ve üretim imkânının artması', 'Yalnızca müze açılımı', 'Ücretsiz sanat'], c: 1, e: 'Sanatın demokratikleşmesi; çevrimiçi koleksiyonlar, ücretsiz müze günleri, kamusal sanat projeleri, açık kaynaklı yaratıcı araçlar ve sosyal medya sayesinde hem sanat tüketimi hem üretiminin giderek daha geniş kitlelere açılmasıdır.' },
  { q: '"Orta Çağ aydınlatılmış el yazması" nedir?', a: 'Baskılı kitap', a: ['Duvar resmi', 'Altın varak ve canlı renkli minyatürlerle süslenmiş dini ve seküler elyazması; Lindisfarne İncili ve Kells Kitabı en tanınan örnekler', 'Gravür', 'Fresk'], c: 1, e: 'Aydınlatılmış el yazması (illuminated manuscript); altın, gümüş ve canlı renkli boyalarla süslenmiş, kenar süsleme ve minyatür sahneler içeren ortaçağ el yazısı kitabıdır. Manastır çalışma odalarında (scriptorium) üretilirdi.' },
  { q: '"Tapiçeri (goblen)" sanatı nedir?', a: 'Boyama tekniği', a: ['Baskı tekniği', 'Renkli iplik veya yünlerin tezgah üzerinde elle dokunmasıyla oluşturulan ve büyük duvar dekorasyonu olarak kullanılan tekstil sanatı', 'Heykel', 'Vitray'], c: 1, e: 'Tapiçeri; renkli ipliklerin çözgü teline dik olarak dokunduğu ve karmaşık sahne veya desenlerin işlendiği tekstil sanatıdır. Bayeux Tapestry (1070\'ler) ve Versailles koleksiyonu bu sanatın en ünlü örnekleri.' },
  { q: '"Majolika" nedir?', a: 'İtalyan kumaş', a: ['Fransız baskı', 'Kalay oksit sırlı, parlak ve renkli figüratif resimlerle süslenmiş İtalyan seramiği; Rönesans\'ın dekoratif sanatının önemli bir kolu', 'Hollanda taş', 'Alman porselen'], c: 1, e: 'Majolika; kalay oksit içeren opak beyaz sırla kaplı, üzerine metal oksit boyalarla figür ve desen işlenen İtalyan seramiğidir. 15-16. yüzyılda Faenza ve Deruta gibi şehirlerde üretilen ürünler Rönesans koleksiyonculuğunun önemli parçalarıdır.' },
  { q: '"Jade (yeşim taşı)" Çin sanatında nasıl bir anlam taşır?', a: ['Yalnızca süs', 'Erdem, ölümsüzlük ve gökyüzü ile insanı birleştiren kutsal madde; Çin sanatında beş bin yılı aşan kutsal simgesel değer', 'Ticaret malı', 'Yalnızca takı'], c: 1, e: 'Jade; Konfüçyüs ahlakının beş erdemini temsil eden (merhamet, adalet, cesaret, bilgelik ve dürüstlük) ve ölümsüzlüğü simgeleyen Çin medeniyetinin en kutsal malzemesidir. Neolitik çağdan bu yana törensel ve sanatsal nesnelerde kullanıldı.' },
  { q: '"Kilim" ile "halı" arasındaki fark nedir?', a: 'Boyut', a: ['Yalnızca renk', 'Kilim düz dokuma (hav yok); halı yığ/yün havı ile daha kalın, sert ve uzun süre dayanıklı. Her ikisi de yüzyıllık el işçiliği geleneğini paylaşır', 'Yalnızca malzeme', 'Bölge'], c: 1, e: 'Kilim; weft-faced (atkı ön planlı) düz dokumadır, hav (yığ) içermez. Halı ise düğümlü yün havıyla daha kalın ve tekstürdür. Her ikisi de Orta Asya ve Anadolu el sanatı geleneğinin olağanüstü örneklerini barındırır.' },
  { q: '"Seramik sanatında sırın" işlevi nedir?', a: 'Yalnızca renk', a: ['Sadece sertlik', 'Cam benzeri mineral kaplama; gözenekliği kapatır, su geçirmezliği sağlar, renk ve parlaklık katar; 1000°C üzerinde fırınlanır', 'Yalnızca süsleme', 'Yalnızca dayanıklılık'], c: 1, e: 'Sır; silika, alumina ve çeşitli minerallerin yüksek ısıda eriyerek pişirilmiş seramiğin yüzeyinde cam benzeri bir tabaka oluşturmasıdır. İşlevsel olarak suya dayanıklılık sağlar; estetik olarak renk, parlaklık ve desen imkânı sunar.' },
  { q: '"Origami" Japon sanatında ne anlama gelir?', a: 'Kağıt boyama', a: ['Kağıt kesme', '"Oru" (katlamak) + "kami" (kağıt); kağıdı kesmeden yalnızca katlamayla figür oluşturma sanatı; Japonya\'da hem sanat hem meditasyon', 'Kağıt baskı', 'Kağıt yazma'], c: 1, e: 'Origami; kesme veya yapıştırma olmaksızın yalnızca katlama teknikleriyle kağıdı üç boyutlu figüre dönüştüren Japon sanatıdır. Turna kuşu en ikonik formudur. Günümüzde mimarlık, uzay mühendisliği ve biyomedikal alanlarda ilham kaynağı.' },
  { q: '"Bonsai" sanatının felsefesi nedir?', a: 'Küçük ağaç', a: ['Hızlı büyüme', 'Miniatur kap içinde ağacı asırlarca yaşatırken doğanın büyüklüğünü küçük ölçekte yansıtmak; sabır, denge ve insanın doğaya saygısını ifade eder', 'Süs bitkisi', 'Botanik deney'], c: 1, e: 'Bonsai; Çin\'den Japonya\'ya geçen ve asırlık ağaçları küçük kaplar içinde yetiştirme sanatıdır. Her kesim ve şekillendirme bilinçli estetik karardır. "Wabi-sabi" felsefesiyle kusurlu ve geçici güzelliği ön plana çıkarır.' },
  { q: '"İslam geometrik sanatının" temel ilkesi nedir?', a: 'Serbest desen', a: ['Figür tasviri', 'Matematik kesinliğinde yinelenen geometrik örüntüler; Allah\'ın sonsuzluğunu ve yaratılışın düzenini figür tasviri olmaksızın görselleştirme', 'Botanik motifler', 'Hiyeroglif'], c: 1, e: 'İslam geometrik sanatı; figür tasvirinin sınırlandırıldığı dinî bağlamda matematiksel hassasiyetle sonsuz tekrar üreten yıldız örüntüler, arabesk ve girift geometrilerle Allah\'ın sonsuz yaratıcılığını simgeler.' },
  { q: '"Müzede "retrospective" sergi" ne anlama gelir?', a: 'İleri bakış', a: ['Koleksiyon satışı', 'Bir sanatçının belirli bir dönemini veya tüm kariyerini kronolojik ya da tematik olarak bir arada sunan kapsamlı geriye dönük bakış sergisi', 'Grup sergisi', 'Satış sergisi'], c: 1, e: 'Retrospektif; bir sanatçının kariyerini ya da belirli dönemini kapsamlı biçimde sunan büyük müze sergisidir. İzleyiciye sanatçının gelişimini, dönüşümünü ve dönemini anlamasını sağlayan en zengin sergi formatı.' },
  { q: '"Vernissage" ne anlama gelir?', a: 'Müze satışı', a: ['Sergi sonu', 'Serginin halka açılmadan önceki sanatçı, küratör ve davetsiz misafirlere özel açılış töreni', 'Galeri kapanış', 'Katalog lansmanı'], c: 1, e: 'Vernissage (Fransızca: "varnisleme"); tarihsel olarak açılış öncesi sergi tablolarının son verniklendiği gün anlamına gelir. Günümüzde sergi açılışının öncesindeki özel davetlilere yönelik tören için kullanılır.' },
  { q: '"Fotoğraf veya dijital baskı" sanat olabilir mi?', a: 'Hayır', a: ['Yalnızca fotoğraf', 'Evet; çerçeveleme, ışık, kompozisyon ve kavramsal bilinç barındırdığında baskı ve dijital üretim galeri ve müze koleksiyonlarında sanat eseri statüsü kazanır', 'Yalnızca büyük boyut', 'Sadece analog'], c: 1, e: 'Fotoğrafın sanat olarak kabul görmesi; Alfred Stieglitz\'in 1902 mücadelesiyle başladı. Günümüzde Cindy Sherman\'ın kurgulanmış fotoğraflarından Andreas Gursky\'nin dijital düzenlemelerine kadar baskı ve dijital üretim müzayedede en yüksek fiyatlar arasında.' },
  { q: '"Sanat dünyasında "artist statement" nedir?', a: 'Özgeçmiş', a: ['Katalog metni', 'Sanatçının kendi çalışmasını, motivasyonunu, kavramsal çerçevesini ve niyetini kendi sesiyle anlattığı kısa kişisel metin', 'Eleştiri', 'Galeri duyurusu'], c: 1, e: 'Artist statement; sanatçının neden ve nasıl ürettiğini, hangi sorularla boğuştuğunu ve eserlerinin bağlamını kendi perspektifiyle anlattığı özgün metindir. Başvurular, kataloglar ve müze etiketlerinde kimlik belgesi işlevi görür.' },
  { q: '"Müzede "docent" kim olduğu?"', a: 'Müze güvenliği', a: ['Küratör', 'Müzede rehberlik yapan, gönüllü veya ücretli uzman; ziyaretçileri eserler ve tarih konusunda bilgilendiren eğitim çalışanı', 'Restorasyon uzmanı', 'Koleksiyoncu'], c: 1, e: 'Docent; müze ve galeride hem bireysel hem grup rehberliği yapan ve sanat tarihi bilgisini izleyiciyle paylaşan eğitim görevlisidir. Pek çok müzede gönüllü docent programları topluluk katılımının temel bileşeni.' },
  { q: '"Sanat kitapları ve sanat eleştirisi" hangi dönemden itibaren yaygınlaştı?', a: '20. yüzyıl', a: ['Antik Çağ', 'Gutenberg baskısıyla birlikte 15. yüzyıldan itibaren; Vasari\'nin 1550 tarihli sanatçı biyografisi ve sonraki eleştiri gelenekleriyle kurumsallaştı', 'Orta Çağ', '18. yüzyıl'], c: 1, e: 'Gutenberg baskısının icadı; sanat kitaplarını çoğaltmayı mümkün kıldı. Vasari (1550) sistematik sanat tarihi yazımını başlatırken; 18. yüzyılda Denis Diderot ve 19. yüzyılda John Ruskin gibi isimlerle sanat eleştirisi bağımsız bir edebi tür oldu.' },
  { q: '"Türk sanatında hat ustası Şeyh Hamdullah"nın önemi nedir?', a: 'Minyatür ustası', a: ['Heykeltıraş', 'Osmanlı hat geleneğinin kurucusu sayılır; Yusuf tarzını yenileyerek 6 temel hat türünü yeniden standart haline getirdi', 'Ressam', 'Mimar'], c: 1, e: 'Şeyh Hamdullah (1436-1520); Osmanlı hat sanatının "mimarı" kabul edilir. Aklam-ı sitte adlı altı temel hat türünü yeniden formüle ederek sonraki yüzyıllar boyunca Osmanlı kaligrafi geleneğinin standardını kurdu.' },
  { q: '"Hattat Hafız Osman"ın Osmanlı sanatındaki yeri nedir?', a: 'Ressam', a: ['Müzisyen', '17. yüzyılın büyük Osmanlı hattatı; sülüs ve nesih türlerinde mükemmelliğe ulaşan ve bugün hâlâ referans gösterilen levha ve hilyeler', 'Mimar', 'Seramikçi'], c: 1, e: 'Hafız Osman (1642-1698); Osmanlı sülüs ve nesih hattının zirvesini temsil eder. Hilye-i şerif (Hz. Peygamber\'in tarifinin hat sanatıyla düzenlendiği levha) formunu mükemmelleştirdi; bugün Türk hat sanatının simgesi kabul edilir.' },
  { q: '"Levnî" Osmanlı sanatında neden önemlidir?', a: ['Hattat', 'Osmanlı minyatür sanatının 18. yüzyıldaki zirvesi; renkli ve canlı saray yaşamı sahneleri ile kadın figürlerini aktaran ressam', 'Mimar', 'Seramikçi'], c: 1, e: 'Levnî (Abdülcelil Çelebi); 18. yüzyıl Osmanlı minyatür geleneğinin son büyük ustasıdır. Surname-i Vehbi için yaptığı şenlik tasvirleri ve kadın figürlerindeki renk canlılığı döneminin en önemli görsel belgeleridir.' },
  { q: '"Nakkaş Osman" kim olduğu?"', a: ['Müzisyen', 'Kanuni ve Murad III dönemlerinde saray nakışhanesi şefi; tarihsel anlatım sahnelerini aktaran Osmanlı minyatürcü', 'Hattat', 'Mimar'], c: 1, e: 'Nakkaş Osman; 16. yüzyıl Osmanlı sarayında nakışhane şefliği yapan ve padişah portreciliğini geliştiren minyatürcüdür. "Şehnâme-i Selim Han" ve "Hünernâme"nin görsel anlatıları onun atölyesinin ürünüdür.' },
  { q: '"Türk sedef işçiliği (sedefkârlık)" neyi tanımlar?', a: ['Mermer işleme', 'Deniz kabuğu iç yüzeyindeki parlak tabakayı (sedef/Mother of Pearl) ahşap, kemik veya fildişine kakma sanatı', 'Çini boyama', 'Deri işleme'], c: 1, e: 'Sedefkârlık; Türk el sanatlarının en zarif kollarından biridir. Osmanlı döneminde mobilya, müzik aleti ve mihraplarda uygulandı. Ud, tambur ve diğer çalgıların sedef kakmalı gövdeleri hem estetik hem ses kalitesi açısından değerlidir.' },
  { q: '"Osmanlı çini sanatında" hangi renk "Türk kırmızısı" olarak anılır?', a: ['Kobalt mavisi', 'Mercan kırmızısı (bolus kırmızısı); yüksek ısıda sırın üzerinde patlayıcı canlı bir kırmızı oluşturan Bole pigmenti', 'Fıstık yeşili', 'Beyaz'], c: 1, e: '"Türk kırmızısı" ya da mercan kırmızısı; 16. yüzyıl İznik çinilerinde kobalt mavisiyle birlikte kullanılan, yüksek ısı teknikle üretilmesi son derece zor canlı kırmızıdır. Bu rengi başarıyla üretebilen ustalar döneminde büyük değer taşıdı.' },
  { q: '"Türk ve İslam Eserleri Müzesi" nerede bulunur?', a: ['Ankara', 'İstanbul, Sultanahmet\'te İbrahim Paşa Sarayı\'nda; Türk-İslam sanatının dünyanın en zengin koleksiyonlarından birine ev sahipliği', 'İzmir', 'Bursa'], c: 1, e: 'Türk ve İslam Eserleri Müzesi; 1914\'te kurulan ve dünyanın en kapsamlı Türk-İslam sanatı koleksiyonunu barındıran müzedir. Sultanahmet\'teki 16. yüzyıl İbrahim Paşa Sarayı\'nda hizmet vermekte.' },
  { q: '"Topkapı Sarayı Müzesi"nin öne çıkan koleksiyonları nelerdir?', a: ['Yalnızca silah', 'Hırka-i Saadet dairesi kutsal emanetleri, Çin ve Japon porselenleri, minyatürler, Osmanlı hazinesi ve kaftanlar', 'Yalnızca halı', 'Yalnızca kılıç'], c: 1, e: 'Topkapı; Hz. Peygamber\'e ait kutsal emanetler, Çin ve Japon porselen koleksiyonu (12.000+ parça), Osmanlı padişahlarına ait kaftan ve mücevherler ile binlerce minyatür eseriyle dünyanın en zengin saray koleksiyonlarından biri.' },
  { q: '"Çinili Köşk" neyi barındırır?', a: ['Silah müzesi', 'İstanbul Arkeoloji Müzeleri bünyesinde, Selçuklu ve Osmanlı çini sanatının önemli bir koleksiyonu', 'Modern sanat', 'Hat müzesi'], c: 1, e: 'Çinili Köşk (1472); Topkapı Sarayı bahçesinde Fatih Sultan Mehmet döneminden kalma en eski yapıdır. Günümüzde Selçuklu ve Osmanlı çini koleksiyonuna ev sahipliği yapan İstanbul Arkeoloji Müzeleri\'nin bir bölümüdür.' },
  { q: '"İstanbul Arkeoloji Müzesi"nin en önemli eseri hangisidir?', a: ['Kılıç koleksiyonu', 'İskender Lahti (Büyük İskender\'e ait olduğu düşünülen ve kabartmalarıyla başyapıt sayılan mermer lahit)', 'Roma heykeli', 'Osmanlı kaftanı'], c: 1, e: 'İskender Lahdi; MÖ 325-300\'e tarihlenen ve Büyük İskender\'in Pers ve aslan avı sahneleriyle süslenmiş olağanüstü mermer lahittir. Sidon\'da (Lübnan) bulunup İstanbul\'a getirilen bu eser antik heykel sanatının en görkemli örneklerinden.' },
  { q: '"Ankara Anadolu Medeniyetleri Müzesi" neden önemlidir?', a: ['Modern sanat', 'Hitit, Urartu, Frig ve diğer Anadolu medeniyetlerine ait arkeolojik eserlerin dünyanın en kapsamlı koleksiyonlarından birini barındırması', 'Osmanlı sanatı', 'Bizans eserleri'], c: 1, e: 'Anadolu Medeniyetleri Müzesi; Paleolitik\'ten Demir Çağı\'na Anadolu\'nun tüm önemli kültür eserlerini barındıran ve UNESCO tarafından "Yılın Müzesi" seçilen eşsiz bir arkeoloji hazinesidir.' },
  { q: '"Sanat eseri yağmalanması" nasıl ele alınır?', a: 'Önemsiz', a: ['Geri verilemez', 'Uluslararası hukuk ve UNESCO sözleşmeleri; savaş veya sömürge döneminde çalınan eserlerin kaynak ülkelere iadesi için çerçeve oluşturdu', 'Yalnızca antika', 'Sadece savaş'], c: 1, e: '1954 Lahey Sözleşmesi ve 1970 UNESCO Sözleşmesi; kültürel mülkü savaş ve yasadışı ticaretten koruyan temel uluslararası belgelerdir. Elgin Mermerleri, Nefertiti büstü gibi davalar iade tartışmalarını güncellikte tutuyor.' },
  { q: '"Kültürel miras korumanın" uluslararası çerçevesi nedir?', a: 'Her ülke kendi', a: ['Yalnızca BM', 'UNESCO Dünya Mirası Listesi ve koruma sözleşmeleri; insanlığın ortak değeri olan doğal ve kültürel miras alanlarını standartlar çerçevesinde güvence altına alır', 'Yalnızca zengin ülkeler', 'Sadece müzeler'], c: 1, e: 'UNESCO\'nun 1972 tarihli "Dünya Mirası Sözleşmesi"; olağanüstü evrensel değere sahip kültürel ve doğal alanları koruma altına alan ve 190\'dan fazla taraf ülkeyle dünyanın en geniş mirası koruma çerçevesidir.' },
  { q: '"Restorasyon ile konservasyon" arasındaki fark nedir?', a: 'Aynı şey', a: ['Yalnızca temizlik', 'Konservasyon; mevcut durumu istikrara kavuşturur. Restorasyon; kayıp bölümleri tamamlamayı hedefler — daha müdahaleci, etik tartışması daha yoğun', 'Yalnızca müze işi', 'Yalnızca eski eserler'], c: 1, e: 'Konservasyon; eserin daha ileri bozunmasını önlemeyi hedefler (temizlik, stabilizasyon, çevre kontrolü). Restorasyon ise özgün görünümü yeniden yaratmayı amaçlar; bu müdahale ne kadar ileri gidilmeli sorusu etik tartışmanın merkezinde.' },
  { q: '"Dünyanın en pahalıya satılan tablosu" hangisidir?', a: 'Mona Lisa', a: ['Guernica', 'Salvator Mundi (2017\'de 450 milyon dolara Christie\'s\'te satılan, Da Vinci\'ye atfedilen tablo)', 'Yıldızlı Gece', 'Nilüferler'], c: 1, e: '"Salvator Mundi"; 2017\'de Christie\'s müzayedesinde 450 milyon dolara satılarak özel koleksiyona girdi ve tüm zamanların en pahalı açık artırma satış rekoru oldu. Tabonun Da Vinci\'ye atfedilmesi tartışmalı olmayı sürdürüyor.' },
  { q: '"En çok ziyaret edilen müze" hangisidir?', a: 'MoMA', a: ['British Museum', 'Louvre; yıllık 7-9 milyon ziyaretçiyle en çok ziyaret edilen sanat müzesi (Mona Lisa etkisi)', 'Smithsonian', 'Hermitage'], c: 1, e: 'Louvre; yıllık 7-9 milyon ziyaretçiyle dünyanın en çok ziyaret edilen sanat müzesidir. Ziyaretçilerin büyük çoğunluğu doğrudan Mona Lisa için gelir; Venüs de Milo ve Zafer Nike de en çok görülen eserler arasında.' },
  { q: '"Sanat ve empati" arasında nasıl bir bağ kurulur?', a: 'Bağ yok', a: ['Yalnızca estetik', 'Sanat; farklı bakış açılarına ve deneyimlere ait hikâyeleri aktararak izleyicide başkasının duygusunu hissetme (empati) kapasitesini besler', 'Yalnızca duygu', 'Sadece eğitimde'], c: 1, e: 'Nörobilim araştırmaları; sanat eseri veya edebiyatla karşılaşmanın "ayna nöronları" aracılığıyla empati kapasitesini artırdığını göstermektedir. Sanatın bu işlevi; kültürlerarası anlayış, tıp eğitimi ve toplumsal iyileştirme alanlarında uygulanmaktadır.' },
  { q: '"Müzede fotoğraf çekmek" neden kısıtlanabilir?', a: 'Yalnızca estetik', a: ['Güvenlik', 'Telif hakkı (eseri hâlâ korunan eserlerin izinsiz çoğaltılması), flaş ışığının boya zarar vermesi ve sessizlik/deneyim koruması', 'Yalnızca maddi', 'Yalnızca teknik'], c: 1, e: 'Müze fotoğraf politikaları; telif hakkı süresi devam eden eserlerin yasadışı çoğaltılması riski, flaş ve kızılötesi ışığın boya ve pigment hasarı, ayrıca diğer ziyaretçilerin deneyiminin korunması gibi çoklu gerekçeye dayanır.' },
  { q: '"Sanat piyasasında" sahte eser oranı hakkında ne söylenebilir?', a: 'Yok denecek kadar az', a: ['Kesin veri var', 'Uzmanlar piyasadaki eserlerin ciddi bir yüzdesinin sahte veya yanlış atıf taşıdığını öne sürüyor; kesin rakam tartışmalı', 'Sadece antika', 'Sadece heykelde'], c: 1, e: 'Sahtecilik uzmanları; piyasada dolaşan eserlerin %10-50\'sinin sahte ya da yanlış atıf taşıdığını tahmin ediyor. İleri analitik teknikler (karbon tarihleme, boya kimyası analizi) sahteciliği tespit etmeyi geliştirdi ama sofistike sahteciler teknolojiyi de takip ediyor.' },
  { q: '"Vincent van Gogh"un eserleri yaşarken kaç kez satıldı?', a: 'Binlerce', a: ['Yüzlerce', 'Yalnızca bir kez; "Kırmızı Üzüm Bağları" 400 franka satıldı. Bugün milyarlarca dolar değerindeki eserler sağlığında ilgi görmedi', 'Onlarca', 'Hiç satılmadı'], c: 1, e: 'Van Gogh; hayattayken yalnızca "The Red Vineyard" adlı tablosunu satabildiği bilinmektedir. Bu tablo 1890\'da 400 Fransız frangına satıldı. Bugün eserleri müzayedelerde on milyonlarca dolar buluyor.' },
  { q: '"Sanatçı bakış açısı" ile "izleyici bakış açısı" arasındaki ilişki nedir?', a: 'Aynı', a: ['Çelişir', 'Sanatçı niyeti ile izleyici yorumu arasındaki boşluk anlam üretiminin verimli zeminidir; Roland Barthes "yazarın ölümü" makalesiyle bu özgürlüğü teorize etti', 'Sadece sanatçı önemli', 'Sadece izleyici önemli'], c: 1, e: 'Roland Barthes (1967 "Yazarın Ölümü"); anlamın sanatçı niyetiyle bitmediğini, her okuyucu/izleyicinin metnin yeniden doğumunda rol oynadığını savundu. Bu yaklaşım; eleştiri, eğitim ve sanat terapisinde yorumun özgürlüğüne zemin hazırladı.' },
  { q: '"Müzede "white space" düzenleme ilkesi" eserleri nasıl etkiler?', a: 'Eserleri küçültür', a: ['Eserleri gizler', 'Eser çevresinde bırakılan boşluk; izleyicinin dikkatini odaklar, esere nefes alanı tanır ve görsel gürültüyü azaltır', 'Eserleri korur', 'Yalnızca estetik'], c: 1, e: 'Sergi tasarımında "white space" (boşluk kullanımı); izleyicinin dikkatini esere odaklamasını, komşu eserlerle sağlıklı görsel ilişki kurmasını ve duygusal tükenme (museum fatigue) yaşanmasını önlemeyi hedefler.' },
  { q: '"Sanatta zaman" kavramı nasıl işlenir?', a: 'Sadece tarih sahneleri', a: ['Yalnızca müzik', 'Resimde dondurulan an, heykelde mekânsal süre, videoda gerçek zaman, performansta sona erme ve land art\'ta doğal dönüşüm; her form zamanı farklı işler', 'Sadece film', 'Sadece hız'], c: 1, e: 'Zaman sanatta çok boyutlu: Empresyonizm anlık ışığı; Duchamp "Hazır Yapıt"ta zamansız nesneyi; Nauman video döngüsünde sonsuz tekrarı; Heizer\'in "Double Negative"i on binlerce yıllık jeolojik zamanı kullanır. Her form zamanı farklı biçimde içselleştirir.' },
  { q: '"Sanatsal ilham" nereden gelir?', a: 'Yalnızca tanrıdan', a: ['Yalnızca doğadan', 'Gözlem, deneyim, kültürel miras, bilinçdışı süreçler, başka sanat eserleri ve toplumsal kriz; ilham çok yönlü ve kişisel kaynaklara sahip', 'Yalnızca rüyadan', 'Yalnızca okumaktan'], c: 1, e: 'Sanatsal ilham; doğa gözleminden bilinçdışı içgüdülere, sosyal adaletsizlikten kişisel kayba, başka sanatçıların eserlerinden günlük sıradan nesnelere kadar uzanan çok katmanlı bir süreçtir. Yaratıcılık araştırmaları; hazırlık, kuluçka, aydınlanma ve doğrulama aşamalarını tanımlar.' },
  { q: '"Renk teorisinde" komplementer (tamamlayıcı) renkler nelerdir?', a: 'Benzer renkler', a: ['Aynı ton', 'Renk çemberinde karşılıklı konumdaki renkler; kırmızı-yeşil, mavi-turuncu, sarı-mor. Yan yana kullanılınca zirveye çıkan canlılık ve titreşim yaratır', 'Pastel renkler', 'Soğuk renkler'], c: 1, e: 'Komplementer renkler; birbirinin karşısındaki renk çemberi çiftleridir. Yan yana kullanıldıklarında her ikisi de daha canlı görünür; karıştırıldıklarında nötr gri-kahverengi oluşur. Bu etkiyi bilinçli kullanan İzlenimciler ve Post-İzlenimciler canlılık sağladı.' },
  { q: '"Sanatın işlevi" tarihsel olarak nasıl değişti?', a: 'Hiç değişmedi', a: ['Yalnızca estetik', 'Dini ve ritüel işlevden (mağara resimlerinden katedral sanatına) statü ve güç simgeciliğine, kamusal eğitime, piyasa malına ve günümüz kimlik-eleştiri aracına', 'Yalnızca prestij', 'Yalnızca güzellik'], c: 1, e: 'Sanatın işlevi tarih boyunca dönüştü: Paleolitik mağara resimlerinin ritüel işlevinden Orta Çağ\'ın dini eğitim rolüne, Rönesans\'ın statü göstergesine, Aydınlanma\'nın kamusal eğitime, modernizmin özgün ifadesine ve günümüzün kimlik-siyaset aracına uzanır.' },
  { q: '"Dünyanın en ünlü heykellerinden biri" olan Özgürlük Anıtı kimler tarafından tasarlandı?', a: 'ABD\'li mimar', a: ['İngiliz mühendis', 'Fransız ressam Frédéric Bartholdi (heykel) ve Gustave Eiffel (iç çelik iskelet) ortak ürünü; 1886\'da New York Limanı\'na yerleştirildi', 'Amerikalı heykeltıraş', 'İtalyan usta'], c: 1, e: 'Özgürlük Anıtı; Fransız heykeltıraş Frédéric Auguste Bartholdi tarafından tasarlandı. İç çelik iskeleti ise Eyfel Kulesi\'nin de mimarı Gustave Eiffel tarafından inşa edildi. Fransız-Amerikan dostluğunun simgesi olarak 1886\'da hediye edildi.' },
  { q: '"Dünyanın yedi harikası"ndan hangisi günümüze ulaştı?', a: 'Olimpia Zeus heykeli', a: ['İskenderiye Feneri', 'Mısır\'daki Giza Büyük Piramiti; diğer altı harika çeşitli felaket ve dönemler boyunca yok oldu', 'Babil Asma Bahçeleri', 'Rodos Kolosu'], c: 1, e: 'Antik Çağın Yedi Harikası\'ndan yalnızca Giza\'daki Büyük Keops Piramiti günümüze ulaştı. Diğerleri; deprem, yangın veya bilinmeyen nedenlerle tarih boyunca yok oldu.' },
  { q: '"Michelangelo"nun "Yaratılış" freskinde" hangi sahne ikonikleşti?', a: 'Son yemek', a: ['Nuh Tufanı', 'Tanrı\'nın parmak ucunun Adem\'in parmak ucuna neredeyse değdiği "Adem\'in Yaratılışı" sahnesi', 'Musa\'nın tabletleri', 'Kıyamet günü'], c: 1, e: 'Sistine Şapeli tavanındaki "Adem\'in Yaratılışı"; iki parmağın hemen hemen temas ettiği boşluk ve Tanrı\'nın enerjiyle şarjlı Adem\'e yaşam verişiyle sanat tarihinin en tanınan ikonalarından biri haline geldi.' },
  { q: '"Salvador Dali"nin ikonik "Belleğin Kalıcılığı" tablosunda ne var?', a: 'Saat boşluğu', a: ['Sürrealist at', 'Eriyip akan saatler; zaman algısının göreliliğini ve bilinçdışının rüya mantığını aktaran 1931 tarihli Sürrealist başyapıt', 'Kristal köy', 'Gömülmüş fil'], c: 1, e: '"Belleğin Kalıcılığı" (1931); çorak bir manzarada eriyip akan yumuşak saatler ve ölü ağaçla Dali\'nin en tanınan eseridir. Zaman algısının ve fizik yasalarının rüya mantığında nasıl "erimesi" gerektiğini simgeliyor.' },
  { q: '"Soyut sanatta renk" nasıl işlev görür?', a: ['Yalnızca süsleme', 'Duygu, enerji ve anlam aktarımının birincil aracı — figüratif temsilden bağımsız olarak rengin kendisi mesajdır', 'Yalnızca kompozisyon', 'Yalnızca teknik'], c: 1, e: 'Soyut sanatta renk; Kandinsky için manevi titreşim, Rothko için duygusal kütlesellik, Albers için optik etkileşim ve Newman için varoluşsal boşluk gibi çok farklı anlamları taşır. Renk tek başına anlatı oluşturur.' },
  { q: '"Resimde "negative space" (negatif alan)" nedir?', a: ['Boş tuval', 'Figür veya nesnenin çevresindeki boş alan; bu alanın bilinçli kullanımı kompozisyona denge, ritim ve anlam katar', 'Siyah alan', 'Karanlık bölge'], c: 1, e: 'Negatif alan; resimde figürün dışında kalan boşluktur. Japon sanatı ve minimalist tasarım bu alanı aktif biçimde kullanır. "Tiger"ın siluetine değil çevresine bakıldığında da anlam çıkar — negatif alan şekil kadar önemlidir.' },
  { q: '"Sanat eğitiminde kreatif düşünce" neden önemsenir?', a: ['Yalnızca hobisi için', 'Sanat pratiği; problem çözme, çoklu perspektif, hata kabulü ve özgün fikir üretimi becerilerini geliştirerek STEM ötesi değer katar', 'Yalnızca sanatçılar için', 'Yalnızca çocuklarda'], c: 1, e: 'Sanat eğitiminin yaratıcı düşünce üzerindeki etkisi nörobilimsel olarak belgelenmiştir. Resim, müzik ve drama; farklı açılardan bakma, belirsizlikle yaşama ve özgün çözüm üretme becerilerini geliştirerek mühendislik ve bilimde bile rekabet avantajı sağlar.' },
];

